-- Schema for Domain: finance | Business: Power and Utilities | Version: v1_mvm
-- Generated on: 2026-04-29 23:12:55

-- ========= DATABASE =========
CREATE DATABASE IF NOT EXISTS `power_and_utilities`.`finance` COMMENT 'Manages financial planning, general ledger, cost accounting, budgeting, and financial reporting. Tracks CAPEX and OPEX, ROE and ROI metrics, EBITDA, depreciation, and regulatory accounting per FERC Uniform System of Accounts. Supports rate case cost-of-service studies, SOX compliance, and GAAP financial statement preparation.';

-- ========= TABLES =========
CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`cost_center` (
    `cost_center_id` BIGINT COMMENT 'Unique surrogate identifier for the cost center record in the Databricks Silver Layer. Primary key for all financial allocation and reporting joins.',
    `profit_center_id` BIGINT COMMENT 'Foreign key linking to finance.profit_center. Business justification: cost_center has profit_center attribute (STRING). profit_center is the master for profit centers. Normalizing this reference allows joining to get full profit center details (name, responsible_manager',
    `parent_cost_center_id` BIGINT COMMENT 'Self-referencing FK on cost_center (parent_cost_center_id)',
    `activity_type` STRING COMMENT 'Primary SAP activity type (LSTAR) associated with this cost center, representing the unit of output or service produced (e.g., labor hours, machine hours, kWh generated). Used for internal activity allocation, cost rate calculation, and transfer pricing between cost centers in the utilitys controlling model.',
    `allocation_method` STRING COMMENT 'Method used to allocate or distribute costs from this cost center to other cost objects (e.g., direct activity allocation, assessment cycle, distribution cycle, statistical key figure). Governs how shared service and overhead costs are spread across generation, T&D, and customer service functions for cost-of-service studies. [ENUM-REF-CANDIDATE: direct|indirect_activity|statistical_key_figure|assessment|distribution|none — promote to reference product]. Valid values are `direct|indirect_activity|statistical_key_figure|assessment|distribution|none`',
    `annual_capex_budget` DECIMAL(18,2) COMMENT 'Approved annual CAPEX budget amount for this cost center in the controlling area currency. Supports capital program tracking, AFUDC eligibility assessment, WIP monitoring, and rate base additions reporting to PUCs and FERC.',
    `annual_opex_budget` DECIMAL(18,2) COMMENT 'Approved annual OPEX budget amount for this cost center in the controlling area currency. Used for budget vs. actual variance reporting, rate case cost-of-service studies, and PBR performance tracking. Sourced from SAP S/4HANA CO planning versions.',
    `budget_fiscal_year` STRING COMMENT 'Fiscal year (YYYY) for which the annual OPEX and CAPEX budget amounts are applicable. Aligns with the utilitys SAP fiscal year variant and regulatory test year used in rate case filings.',
    `business_area` STRING COMMENT 'SAP Business Area (GSBER) representing a distinct operational segment of the utility (e.g., electric operations, gas operations, unregulated). Used for cross-company-code reporting and supports regulatory separation of electric and gas operations as required by state PUC accounting orders.. Valid values are `^[A-Z0-9]{1,4}$`',
    `capex_opex_indicator` STRING COMMENT 'Indicates whether this cost center primarily accumulates Capital Expenditures (CAPEX), Operating Expenditures (OPEX), or a mix of both. Critical for regulatory accounting, rate base determination, and FERC USoA plant account vs. expense account mapping. Supports AFUDC calculation eligibility and WIP tracking.. Valid values are `CAPEX|OPEX|MIXED`',
    `company_code` STRING COMMENT 'SAP Company Code (BUKRS) representing the legal entity to which this cost center is assigned. Aligns with the utilitys GAAP reporting entity and FERC jurisdictional entity for rate case and regulatory reporting purposes.. Valid values are `^[A-Z0-9]{1,4}$`',
    `controlling_area` STRING COMMENT 'SAP Controlling Area (KOKRS) to which this cost center belongs. Defines the organizational unit within which cost accounting is performed. Typically maps to the utilitys legal entity or consolidated reporting entity.. Valid values are `^[A-Z0-9]{1,4}$`',
    `cost_center_category` STRING COMMENT 'SAP cost center category code (KOSAR) classifying the type of cost center (e.g., E=Production/Operations, F=Overhead, H=Overhead, I=Investment, etc.). Determines which activity types and statistical key figures can be posted and controls planning behavior in SAP CO.. Valid values are `^[A-Z0-9]{1,2}$`',
    `cost_center_code` STRING COMMENT 'Externally-known alphanumeric code uniquely identifying the cost center within the SAP S/4HANA controlling area. Matches the SAP KOSTL field and is used in all FERC Uniform System of Accounts (USoA) cost allocations, rate case filings, and general ledger postings.. Valid values are `^[A-Z0-9_-]{2,20}$`',
    `cost_center_level` STRING COMMENT 'Numeric level of this cost center within the organizational hierarchy (e.g., 1=Division, 2=Department, 3=Work Group). Supports hierarchical drill-down in financial reporting and budget consolidation processes.',
    `cost_center_name` STRING COMMENT 'Short descriptive name of the cost center as maintained in SAP S/4HANA (KTEXT field). Used in financial reports, budget variance analyses, and cost-of-service studies submitted to state Public Utility Commissions (PUCs) and FERC.',
    `cost_center_status` STRING COMMENT 'Current lifecycle status of the cost center in SAP S/4HANA. active = open for postings; inactive = temporarily closed; locked = blocked for new postings (SAP lock indicator); pending_approval = awaiting activation; archived = historically closed and no longer in use. Controls whether financial transactions can be posted to this cost center.. Valid values are `active|inactive|locked|pending_approval|archived`',
    `cost_element_group` STRING COMMENT 'SAP cost element group associated with this cost center, grouping related primary and secondary cost elements (G/L accounts) for planning, budgeting, and reporting. Supports OPEX and CAPEX segregation required for FERC USoA account mapping.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this cost center master record was first created in the source system (SAP S/4HANA). Supports audit trail requirements for SOX Section 404 internal controls and data governance lineage in the Databricks Silver Layer.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for the cost centers controlling area currency (e.g., USD). Defines the currency in which budgets, actuals, and plan values are recorded and reported for this cost center.. Valid values are `^[A-Z]{3}$`',
    `department_code` STRING COMMENT 'Organizational department code to which this cost center belongs, as defined in the utilitys HR and finance organizational structure (SuccessFactors/Workday). Supports headcount and labor cost allocation reporting and aligns with the utilitys organizational chart for management reporting.. Valid values are `^[A-Z0-9_-]{1,10}$`',
    `depreciation_area` STRING COMMENT 'SAP Asset Accounting depreciation area code associated with assets assigned to this cost center. Defines the depreciation rules (GAAP book, FERC regulatory, tax) applied to utility plant assets tracked under this cost center. Supports FERC-prescribed depreciation rates and GAAP ASC 360 asset accounting.. Valid values are `^[0-9]{2}$`',
    `energy_commodity` STRING COMMENT 'Identifies whether this cost center supports electric operations, gas operations, both, or neither (corporate/shared services). Required for regulatory separation of electric and gas utility operations per state PUC accounting orders and FERC USoA commodity-specific account mapping.. Valid values are `electric|gas|both|none`',
    `ferc_account_code` STRING COMMENT 'Primary FERC Uniform System of Accounts (USoA) account code to which costs accumulated in this cost center are mapped for regulatory reporting. Required for FERC Form 1 (electric) and FERC Form 2 (gas) annual report filings. Enables direct traceability from cost center to regulatory account.. Valid values are `^[0-9]{3}(.[0-9]{1,3})?$`',
    `fiscal_year_variant` STRING COMMENT 'SAP Fiscal Year Variant (PERIV) assigned to this cost centers controlling area, defining the fiscal year calendar (e.g., K4 = calendar year Jan-Dec). Ensures correct period assignment for budget planning and actual cost postings in regulatory and GAAP financial reporting.. Valid values are `^[A-Z0-9]{2}$`',
    `functional_area` STRING COMMENT 'Primary utility functional area served by this cost center, aligned with FERC Uniform System of Accounts functional classifications (e.g., generation, transmission, distribution). Drives cost allocation to FERC accounts and supports cost-of-service studies for rate cases filed with PUCs and FERC. [ENUM-REF-CANDIDATE: generation|transmission|distribution_electric|distribution_gas|metering|customer_service|corporate|regulatory|finance|it|hr — promote to reference product]',
    `gl_account_group` STRING COMMENT 'SAP General Ledger account group associated with this cost center, defining the range of G/L accounts (FERC USoA accounts) that can be posted. Ensures that only appropriate expense and capital accounts are used for each functional area, supporting GAAP and FERC regulatory accounting integrity.. Valid values are `^[A-Z0-9_-]{1,10}$`',
    `headcount_plan` STRING COMMENT 'Approved planned headcount (number of full-time equivalent positions) assigned to this cost center for the current budget year. Used for labor cost planning, workforce analytics, and rate case labor cost justification in cost-of-service studies filed with PUCs.',
    `hierarchy_area` STRING COMMENT 'Node within the SAP standard cost center hierarchy (KHINR) to which this cost center belongs. Defines the organizational rollup path for management reporting, budget consolidation, and cost-of-service study aggregations aligned with the utilitys organizational structure.',
    `last_changed_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent modification to this cost center master record in SAP S/4HANA. Used for incremental ETL processing in the Databricks Lakehouse pipeline and SOX change management audit trail.',
    `location_code` STRING COMMENT 'Physical location or service territory code associated with this cost center. For field operations cost centers, maps to a geographic service district or substation area. Supports geographic cost allocation, T&D cost-of-service studies, and GIS-based reporting via ESRI ArcGIS integration.. Valid values are `^[A-Z0-9_-]{1,20}$`',
    `long_description` STRING COMMENT 'Extended narrative description of the cost centers business purpose, scope of activities, and organizational context. Supports regulatory documentation and rate case cost-of-service study narratives.',
    `plant_code` STRING COMMENT 'SAP Plant (WERKS) or physical facility/location to which this cost center is primarily assigned. For generation cost centers, maps to a specific power plant. For T&D cost centers, maps to a service territory or operating district. Supports asset-level cost tracking in conjunction with Oracle WAM or IBM Maximo EAM.. Valid values are `^[A-Z0-9]{1,4}$`',
    `profit_center` STRING COMMENT 'SAP Profit Center (PRCTR) to which this cost center is assigned for internal management reporting and segment profitability analysis. Supports GAAP segment reporting disclosures (ASC 280) and internal ROE/ROI analysis by business segment (electric, gas, corporate).. Valid values are `^[A-Z0-9_-]{1,10}$`',
    `regulatory_jurisdiction` STRING COMMENT 'Indicates the regulatory jurisdiction governing costs accumulated in this cost center. FERC = subject to FERC wholesale/transmission regulation; state_puc = subject to state Public Utility Commission retail rate regulation; both = dual jurisdiction; non_regulated = unregulated activities. Critical for cost allocation in rate cases and FERC Form 1/2 reporting.. Valid values are `FERC|state_puc|both|non_regulated`',
    `responsible_manager_code` STRING COMMENT 'Employee identifier of the manager accountable for the cost centers budget and expenditures, as maintained in SAP S/4HANA (VERAK field) and synchronized with SuccessFactors or Workday HCM. Used for budget approval workflows, variance reporting, and SOX internal control accountability assignments.',
    `responsible_manager_name` STRING COMMENT 'Full name of the manager responsible for this cost centers budget and financial performance. Displayed in financial reports, budget variance dashboards, and cost-of-service study documentation. Sourced from SAP S/4HANA cost center master (VERAK_NAME).',
    `source_system_code` STRING COMMENT 'Identifier of the operational source system from which this cost center master record originates (e.g., SAP S/4HANA client/system ID). Supports data lineage tracking in the Databricks Lakehouse Silver Layer and enables reconciliation between the lakehouse and the ERP system of record.. Valid values are `^[A-Z0-9_-]{1,20}$`',
    `sox_relevant` BOOLEAN COMMENT 'Indicates whether this cost center is within scope for Sarbanes-Oxley (SOX) Section 404 internal controls over financial reporting. SOX-relevant cost centers require documented controls, segregation of duties, and periodic management testing as part of the utilitys annual SOX compliance program.',
    `wbs_element` STRING COMMENT 'SAP Work Breakdown Structure (WBS) element associated with this cost center for capital project cost tracking. Links cost center CAPEX accumulation to specific capital projects in SAP PS (Project System), supporting AFUDC calculation, WIP reporting, and CIAC tracking for regulatory rate base purposes.. Valid values are `^[A-Z0-9._-]{1,24}$`',
    `work_order_settlement_profile` STRING COMMENT 'SAP settlement profile (ABCPROFIL) defining how maintenance and capital work order costs are settled to this cost center from Oracle WAM or IBM Maximo work orders integrated via SAP PM. Governs CAPEX vs. OPEX treatment of maintenance activities for regulatory accounting.',
    `valid_from` DATE COMMENT 'Date from which this cost center is valid and open for financial postings in SAP S/4HANA (DATAB field). Defines the start of the cost centers active period for budget planning, actual cost accumulation, and regulatory reporting.',
    `valid_to` DATE COMMENT 'Date through which this cost center is valid in SAP S/4HANA (DATBI field). After this date, no new postings are permitted. Nullable for open-ended cost centers. Supports historical cost center management and regulatory period-of-record requirements.',
    CONSTRAINT pk_cost_center PRIMARY KEY(`cost_center_id`)
) COMMENT 'Master record for organizational cost centers used to allocate and track OPEX and CAPEX across the utilitys functional units (generation, transmission, distribution, gas, corporate). Aligned with SAP S/4HANA cost center master and FERC Uniform System of Accounts (USoA) organizational hierarchy. Captures cost center code, description, responsible manager, functional area, plant/location assignment, and active status. Serves as the foundational dimension for all financial reporting and cost-of-service studies.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`gl_account` (
    `gl_account_id` BIGINT COMMENT 'Unique surrogate identifier for the general ledger account record in the Databricks Silver Layer. Serves as the primary key for all ledger postings, rate case cost-of-service studies, and FERC Form 1/2 regulatory filings.',
    `account_description` STRING COMMENT 'Extended narrative description of the GL accounts purpose, the types of transactions posted to it, and any special accounting treatment required. Provides guidance to accountants and auditors on proper account usage. Sourced from the SAP S/4HANA or Oracle ERP Cloud account master long text field.',
    `account_group` STRING COMMENT 'The account group in SAP S/4HANA or Oracle ERP Cloud that controls the number range and field selection for this GL account (e.g., UTIL_PLANT for utility plant accounts, OPEX for operating expense accounts, REVENUE for revenue accounts). Used in chart-of-accounts governance and ERP configuration management.',
    `account_name` STRING COMMENT 'The official descriptive name of the GL account as defined in the chart of accounts (e.g., Electric Plant in Service, Miscellaneous Intangible Plant, Operation and Maintenance Expense). Used in financial statements, rate case filings, and FERC Form 1/2 schedules.',
    `account_number` STRING COMMENT 'The externally-known chart-of-accounts number assigned to this GL account in SAP S/4HANA or Oracle ERP Cloud. Used as the primary business identifier for ledger postings, journal entries, and cross-system reconciliation. Aligns with the FERC Uniform System of Accounts numbering scheme (e.g., 101, 303, 408).. Valid values are `^[0-9]{3,10}$`',
    `account_short_name` STRING COMMENT 'Abbreviated display name for the GL account used in reports, dashboards, and ERP screen labels where space is limited. Sourced from the SAP S/4HANA or Oracle ERP Cloud short description field on the chart of accounts master.',
    `account_status` STRING COMMENT 'Current lifecycle status of the GL account in the chart of accounts. Active accounts accept journal entry postings; inactive accounts are retained for historical reporting but do not accept new postings; blocked accounts are temporarily locked pending review; pending_approval accounts are newly created and awaiting chart-of-accounts governance approval.. Valid values are `active|inactive|blocked|pending_approval`',
    `account_subtype` STRING COMMENT 'Secondary classification within the account_type that provides finer segmentation for financial reporting (e.g., current asset, non-current asset, operating revenue, non-operating expense, long-term liability, retained earnings). Used in GAAP balance sheet and income statement sub-classifications. [ENUM-REF-CANDIDATE: current_asset|non_current_asset|current_liability|non_current_liability|operating_revenue|non_operating_revenue|operating_expense|non_operating_expense|retained_earnings|paid_in_capital — promote to reference product]',
    `account_type` STRING COMMENT 'The fundamental financial statement classification of the GL account per GAAP: asset, liability, equity, revenue, or expense. Drives balance sheet vs. income statement placement and is used in FERC Form 1/2 schedule mapping and SOX financial reporting controls.. Valid values are `asset|liability|equity|revenue|expense`',
    `afudc_eligible` BOOLEAN COMMENT 'Indicates whether this GL account is eligible for Allowance for Funds Used During Construction (AFUDC) capitalization. AFUDC represents the cost of debt and equity funds used to finance construction projects and is capitalized to utility plant per FERC USoA guidelines. Applicable to CWIP accounts and certain capital project cost accounts.',
    `capex_opex_indicator` STRING COMMENT 'Classifies the GL account as a capital expenditure (CAPEX) account, operating expenditure (OPEX) account, or both. CAPEX accounts feed the utility plant and work-in-progress (WIP) schedules; OPEX accounts feed the income statement. Essential for AFUDC calculations, rate base determination, and IRP financial modeling.. Valid values are `capex|opex|both|not_applicable`',
    `chart_of_accounts_code` STRING COMMENT 'The chart-of-accounts identifier in SAP S/4HANA or Oracle ERP Cloud to which this GL account belongs (e.g., UTIL for the utility operating company chart, CORP for the corporate holding company chart). Supports multi-entity financial consolidation and intercompany eliminations.',
    `ciac_account_flag` BOOLEAN COMMENT 'Indicates whether this GL account records Contributions in Aid of Construction (CIAC) — cash or property contributed by customers or developers to fund utility infrastructure extensions. CIAC reduces rate base and is tracked separately per FERC USoA Account 271 and state PUC requirements.',
    `company_code` STRING COMMENT 'The ERP company code (legal entity identifier) in SAP S/4HANA or Oracle ERP Cloud to which this GL account is assigned. Represents the regulated utility operating company or holding company entity for which GAAP financial statements and FERC annual reports are prepared.',
    `cost_element_category` STRING COMMENT 'The SAP Controlling (CO) cost element category assigned to this GL account, indicating how costs flow through the cost accounting module. Primary cost elements represent costs originating from Financial Accounting (FI); secondary cost elements represent internal allocations and settlements. Used in O&M cost allocation studies for rate cases.. Valid values are `primary_cost|secondary_cost|revenue|not_applicable`',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this GL account master record was first created in the source ERP system (SAP S/4HANA or Oracle ERP Cloud). Used for chart-of-accounts audit trail, SOX change management controls, and data lineage tracking in the Databricks Silver Layer.',
    `currency_code` STRING COMMENT 'The ISO 4217 three-letter currency code in which this GL account is maintained (e.g., USD for US Dollar). Utility companies operating in the US maintain accounts in USD; multinational holding companies may maintain accounts in multiple currencies. Drives currency translation in financial consolidation.. Valid values are `^[A-Z]{3}$`',
    `deactivation_date` DATE COMMENT 'The date on which this GL account was deactivated and made unavailable for new journal entry postings. Null for currently active accounts. Historical balances remain accessible for reporting after deactivation. Used in chart-of-accounts governance and period-end close validation.',
    `depreciation_account_flag` BOOLEAN COMMENT 'Indicates whether this GL account is an accumulated depreciation or depreciation expense account. True for FERC accounts 108 (Accumulated Provision for Depreciation of Electric Utility Plant) and equivalent gas accounts. Used to identify accounts included in depreciation rate studies filed with state PUCs.',
    `effective_date` DATE COMMENT 'The date on which this GL account became effective and available for use in the chart of accounts. Marks the start of the accounts valid period for journal entry postings. Used in period-end close processes to validate that postings are made to accounts active during the posting period.',
    `ferc_account_code` STRING COMMENT 'The FERC Uniform System of Accounts (USoA) account code mapped to this GL account (e.g., 101 for Electric Plant in Service, 303 for Miscellaneous Intangible Plant, 408 for Taxes Other Than Income Taxes). Mandatory for FERC Form 1 (electric) and FERC Form 2 (gas) regulatory filings. A single internal GL account may map to one FERC account code.. Valid values are `^[0-9]{3}(.?[0-9]{1,4})?$`',
    `ferc_account_description` STRING COMMENT 'The official FERC USoA description for the mapped FERC account code. Provides the regulatory definition of allowable charges to this account as prescribed by FERC 18 CFR Parts 101 and 201. Used in rate case cost-of-service studies and FERC Form 1/2 narrative disclosures.',
    `ferc_form_reference` STRING COMMENT 'Identifies which FERC annual report form this account populates: FERC Form 1 (Major Electric Utilities), FERC Form 2 (Major Natural Gas Companies), FERC Form 1-F (Non-Major Electric Utilities), both (for common accounts), or not_applicable for accounts not reported to FERC. Drives automated FERC regulatory reporting extraction.. Valid values are `ferc_form_1|ferc_form_2|ferc_form_1_f|both|not_applicable`',
    `financial_statement_version` STRING COMMENT 'The financial statement version (FSV) code in SAP S/4HANA or Oracle ERP Cloud that governs how this account is presented in GAAP financial statements (e.g., GAAP_UTIL for GAAP utility financial statements, FERC_F1 for FERC Form 1 reporting). Supports multi-GAAP and regulatory reporting from a single chart of accounts.',
    `functional_class` STRING COMMENT 'The FERC USoA functional classification of the account within the utility function (e.g., generation, transmission, distribution, customer accounts, administrative and general). Used to allocate costs in rate case cost-of-service studies and to populate FERC Form 1/2 functional expense schedules.. Valid values are `generation|transmission|distribution|customer_accounts|administrative_general|other`',
    `gaap_classification` STRING COMMENT 'The GAAP financial statement line-item classification for this account (e.g., Utility Plant, Accumulated Depreciation, Long-Term Debt, Operating Revenues – Electric, Operation Expense – Fuel). Maps the account to the specific line in GAAP-compliant financial statements filed with the SEC and state PUCs. [ENUM-REF-CANDIDATE: utility_plant|accumulated_depreciation|regulatory_asset|regulatory_liability|operating_revenue|operation_expense|maintenance_expense|depreciation_expense|income_tax|long_term_debt|common_equity — promote to reference product]',
    `income_tax_account_flag` BOOLEAN COMMENT 'Indicates whether this GL account is an income tax account (current or deferred). True for FERC accounts 408 (Taxes Other Than Income Taxes), 409 (Income Taxes), 410/411 (Deferred Income Taxes). Used in SOX tax provision controls and rate case income tax normalization studies.',
    `last_modified_timestamp` TIMESTAMP COMMENT 'The timestamp when this GL account master record was most recently modified in the source ERP system. Tracks changes to account attributes such as status, FERC mapping, or posting controls. Used in SOX change management controls and incremental ETL processing for the Databricks Silver Layer.',
    `line_item_display` BOOLEAN COMMENT 'Indicates whether individual line items posted to this GL account are stored and displayable in the ERP system for audit and drill-down purposes. When True, auditors and financial analysts can view each individual posting. Required for SOX audit trail completeness on high-risk accounts.',
    `naruc_account_code` STRING COMMENT 'The NARUC Uniform System of Accounts code mapped to this GL account for state PUC regulatory reporting. State PUCs may require NARUC-aligned account codes that differ slightly from FERC USoA codes. Used in state annual report filings and state rate case cost-of-service studies.',
    `normal_balance` STRING COMMENT 'Indicates whether the accounts normal (expected) balance is a debit or credit per double-entry bookkeeping rules. Assets and expenses carry a debit normal balance; liabilities, equity, and revenues carry a credit normal balance. Used by the ERP posting engine to detect out-of-balance conditions and in SOX journal entry controls.. Valid values are `debit|credit`',
    `open_item_management` BOOLEAN COMMENT 'Indicates whether this GL account uses open item management in SAP S/4HANA or Oracle ERP Cloud, meaning individual line items remain open until cleared by a matching offsetting entry. Typically enabled for clearing accounts, bank accounts, and GR/IR (Goods Receipt/Invoice Receipt) accounts. Supports accounts receivable and accounts payable reconciliation.',
    `parent_account_number` STRING COMMENT 'The account number of the parent/summary GL account in the chart-of-accounts hierarchy. Enables roll-up of detailed accounts into summary accounts for financial statement presentation and FERC Form 1/2 schedule aggregation. Null for top-level summary accounts.',
    `plant_account_flag` BOOLEAN COMMENT 'Indicates whether this GL account is a utility plant account subject to FERC plant-in-service reporting, depreciation schedules, and rate base inclusion. True for accounts in the FERC 100-series (Electric Plant) and 200-series (Gas Plant). Used to filter accounts for AFUDC capitalization and depreciation rate studies.',
    `posting_allowed` BOOLEAN COMMENT 'Indicates whether direct journal entry postings are permitted to this GL account. False for summary/group accounts that only aggregate child accounts and do not accept direct postings. Sourced from the SAP S/4HANA account master Post Automatically Only or Oracle ERP Cloud Allow Posting flag.',
    `rate_base_eligible` BOOLEAN COMMENT 'Indicates whether balances in this GL account are eligible for inclusion in the utilitys rate base for rate case cost-of-service studies filed with FERC or state PUCs. Rate base typically includes net utility plant in service, working capital allowances, and regulatory assets. Used in PBR and traditional cost-of-service rate case models.',
    `reconciliation_account_flag` BOOLEAN COMMENT 'Indicates whether this GL account is a reconciliation account (subledger control account) in SAP S/4HANA, meaning postings are made automatically from subledger modules (Accounts Receivable, Accounts Payable, Asset Accounting) and direct manual postings are restricted. Critical for SOX subledger-to-general-ledger reconciliation controls.',
    `regulatory_asset_liability_flag` BOOLEAN COMMENT 'Indicates whether this GL account represents a regulatory asset or regulatory liability recognized under GAAP ASC 980 (Regulated Operations). Regulatory assets/liabilities arise from rate-regulated accounting deferrals approved by FERC or state PUCs (e.g., deferred fuel costs, storm damage deferrals, pension regulatory assets).',
    `source_system_account_code` STRING COMMENT 'The native account identifier as stored in the originating ERP system (SAP S/4HANA GL account number or Oracle ERP Cloud natural account segment value). Enables traceability from the Databricks Silver Layer record back to the source system for reconciliation and audit purposes.',
    `sox_relevant` BOOLEAN COMMENT 'Indicates whether this GL account is within scope for Sarbanes-Oxley (SOX) Section 404 internal controls over financial reporting. SOX-relevant accounts require documented controls, periodic testing, and management certification. Sourced from the SOX scoping assessment maintained by the internal audit and finance compliance teams.',
    `tax_category` STRING COMMENT 'The tax relevance category for this GL account in the ERP system, indicating whether the account is subject to sales/use tax, gross receipts tax, or is tax-exempt. Used in automated tax determination during invoice processing and in state PUC gross receipts tax reporting. [ENUM-REF-CANDIDATE: taxable_input|taxable_output|exempt|not_relevant — promote to reference product]',
    `utility_function` STRING COMMENT 'Identifies whether the GL account is associated with the electric utility function, gas utility function, common/shared services, or other non-utility operations. Critical for cost-of-service studies in rate cases, FERC Form 1 (electric) vs. FERC Form 2 (gas) filing segregation, and state PUC jurisdictional separation of revenues and expenses.. Valid values are `electric|gas|common|other`',
    `wip_account_flag` BOOLEAN COMMENT 'Indicates whether this GL account is a Work in Progress (WIP) / Construction Work in Progress (CWIP) account (FERC Account 107 – Construction Work in Progress – Electric, or equivalent gas account). WIP accounts accumulate capital project costs before transfer to plant-in-service upon project completion. Used in AFUDC calculation and capital project tracking.',
    CONSTRAINT pk_gl_account PRIMARY KEY(`gl_account_id`)
) COMMENT 'General ledger account master aligned to the FERC Uniform System of Accounts (USoA) chart of accounts for regulated electric and gas utilities. Captures account number, account name, FERC account code (e.g., Account 101 – Electric Plant in Service, Account 303 – Miscellaneous Intangible Plant), account type (asset, liability, equity, revenue, expense), normal balance indicator, and GAAP classification. Serves as the SSOT for all ledger postings, rate case cost-of-service studies, and FERC Form 1/2 regulatory filings. Sourced from SAP S/4HANA or Oracle ERP Cloud chart of accounts module.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`journal_entry` (
    `journal_entry_id` BIGINT COMMENT 'Unique surrogate identifier for each journal entry header record in the general ledger. Primary key for the journal_entry data product in the Databricks Silver Layer.',
    `cost_center_id` BIGINT COMMENT 'Reference to the primary cost center associated with this journal entry header, representing the organizational unit responsible for the costs (e.g., generation plant, transmission operations, distribution district, customer service). Supports FERC cost-of-service studies and rate case OPEX allocation.',
    `financial_period_id` BIGINT COMMENT 'Foreign key linking to finance.financial_period. Business justification: journal_entry has fiscal_year and fiscal_period attributes. financial_period is the master for fiscal periods. Normalizing this reference allows joining to get full period metadata. fiscal_year and fi',
    `profit_center_id` BIGINT COMMENT 'Reference to the profit center associated with this journal entry, representing a business segment for internal profitability reporting (e.g., electric distribution, gas distribution, generation). Supports segment reporting under GAAP ASC 280 and FERC jurisdictional cost separation.',
    `journal_entry_template_id` BIGINT COMMENT 'Identifier of the recurring entry template in the ERP system that generated this journal entry. Populated only when is_recurring = True. Enables traceability from posted entries back to the template for maintenance and audit purposes.',
    `wbs_element_id` BIGINT COMMENT 'Reference to the Work Breakdown Structure element for CAPEX project postings. Links journal entries to capital projects for AFUDC calculation, WIP tracking, and asset capitalization. Populated for capital expenditure entries; null for OPEX entries. Supports FERC CIAC and AFUDC regulatory accounting.',
    `approval_status` STRING COMMENT 'Workflow approval state of the journal entry indicating whether it has been reviewed and authorized by a second approver per SOX dual-approval controls. Values: pending (awaiting review), approved (authorized for posting), rejected (returned for correction), not_required (below materiality threshold or auto-approved). Critical for segregation-of-duties audit trail.. Valid values are `pending|approved|rejected|not_required`',
    `approval_timestamp` TIMESTAMP COMMENT 'The date and time when the journal entry was approved by the designated approver. Used for SOX dual-approval audit trail and period-close timeliness reporting. Null when approval_status is pending or not_required.',
    `approver_user_code` STRING COMMENT 'ERP system user ID of the individual who approved this journal entry under the dual-approval SOX control framework. Distinct from posting_user_id to enforce segregation of duties. Null when approval is not required or entry is pending approval.',
    `assignment_number` STRING COMMENT 'Alphanumeric assignment field used for sorting and grouping journal entries in account line item displays and financial reports. Often populated with a customer account number, asset number, or billing period for quick identification. Corresponds to ZUONR in SAP FI.',
    `capex_opex_indicator` STRING COMMENT 'Indicates whether this journal entry represents a capital expenditure (CAPEX) to be capitalized as a utility plant asset or an operating expenditure (OPEX) to be expensed in the current period. Critical for FERC rate base determination, GAAP ASC 360 asset capitalization, and PUC rate case cost-of-service studies.. Valid values are `CAPEX|OPEX`',
    `clearing_date` DATE COMMENT 'The date on which open items in this journal entry were cleared (matched and closed) against a payment or offsetting document. Populated when posting_status = cleared. Used for aging analysis and cash flow reporting.',
    `clearing_document_number` STRING COMMENT 'Document number of the clearing entry that matched and closed open items associated with this journal entry (e.g., payment clearing against an invoice). Populated when posting_status = cleared. Supports accounts receivable and accounts payable reconciliation.',
    `company_code` STRING COMMENT 'Four-character ERP company code identifying the legal entity or organizational unit within the utility that owns this journal entry (e.g., electric subsidiary, gas subsidiary, holding company). Used for intercompany elimination and FERC entity-level reporting. Corresponds to BUKRS in SAP FI.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for the transaction currency of this journal entry (e.g., USD for US Dollar). Required for multi-currency consolidation and FERC reporting. Most utility domestic entries will be USD; intercompany or PPA entries may use foreign currencies.. Valid values are `^[A-Z]{3}$`',
    `document_date` DATE COMMENT 'The date of the original business transaction or source document (e.g., invoice date, contract date) that triggered this journal entry. May differ from posting_date for accruals or late postings. Corresponds to BLDAT in SAP FI.',
    `document_number` STRING COMMENT 'Externally-known alphanumeric document number assigned by the ERP system (SAP S/4HANA or Oracle ERP Cloud) at the time of posting. Used by accountants and auditors to locate and reference a specific journal entry. Corresponds to BELNR in SAP FI or Document Number in Oracle GL.',
    `document_type_code` STRING COMMENT 'Two-character ERP document type code that classifies the nature of the journal entry (e.g., SA=General Ledger, AA=Asset Posting, KR=Vendor Invoice, DR=Customer Invoice, AB=Accounting Document, ZP=Payment Clearing). Controls number range assignment and account type permissibility. Corresponds to BLART in SAP FI. [ENUM-REF-CANDIDATE: SA|AA|KR|DR|AB|ZP|RV|WA|ML|RE — promote to reference product]',
    `entry_timestamp` TIMESTAMP COMMENT 'The system timestamp when this journal entry record was first created in the ERP system. Used for SOX audit trail and segregation-of-duties reporting. Represents RECORD_AUDIT_CREATED per canonical attribute requirements.',
    `entry_type` STRING COMMENT 'Business classification of the journal entry indicating its functional purpose: standard (normal operational posting), accrual (period-end estimate), reversal (correction of prior entry), intercompany (cross-entity elimination), recurring (template-based periodic posting), or statistical (non-financial cost allocation). Drives GAAP presentation and FERC regulatory accounting treatment.. Valid values are `standard|accrual|reversal|intercompany|recurring|statistical`',
    `ferc_account_code` STRING COMMENT 'Primary FERC Uniform System of Accounts code associated with this journal entry header (e.g., Account 101 for Steam Production Plant, Account 303 for Transmission Plant, Account 364 for Distribution Plant). Drives FERC Form 1 and Form 2 regulatory reporting. May be derived from line items but captured at header for summary reporting.',
    `fiscal_period` STRING COMMENT 'The accounting period (1–16) within the fiscal year in which this journal entry is posted. Periods 1–12 represent calendar months; periods 13–16 are special closing periods used for year-end adjustments. Corresponds to MONAT in SAP FI.',
    `fiscal_year` STRING COMMENT 'The fiscal year in which this journal entry is recorded (e.g., 2024). Used for annual financial statement preparation, FERC Form 1 reporting, and SOX period-close controls. Corresponds to GJAHR in SAP FI.',
    `functional_area_code` STRING COMMENT 'Code identifying the utility functional area to which this journal entry is attributed for cost-of-service and rate case analysis: GEN (Generation), TRN (Transmission), DST (Electric Distribution), GAS (Gas Distribution), CUS (Customer Service), ADM (Administrative and General), REG (Regulatory), FIN (Finance). Supports FERC jurisdictional cost separation and PUC rate case filings. [ENUM-REF-CANDIDATE: GEN|TRN|DST|GAS|CUS|ADM|REG|FIN — 8 candidates stripped; promote to reference product]',
    `header_text` STRING COMMENT 'Free-text description of the journal entry provided by the posting user, summarizing the business purpose or nature of the transaction (e.g., Q3 2024 Transmission Line Depreciation Accrual, October AMI Meter Installation CAPEX). Used for search, audit review, and financial reporting narrative. Corresponds to BKTXT in SAP FI.',
    `is_intercompany` BOOLEAN COMMENT 'Flag indicating whether this journal entry involves a transaction between two legal entities within the utility holding company structure (e.g., electric subsidiary billing gas subsidiary for shared services). True for intercompany entries requiring elimination in consolidated financial statements per GAAP ASC 810.',
    `is_recurring` BOOLEAN COMMENT 'Flag indicating whether this journal entry was generated from a recurring entry template (e.g., monthly depreciation, lease accruals, fixed O&M allocations). True when generated from a recurring template; False for manually created entries. Supports automated period-close processes.',
    `is_reversed` BOOLEAN COMMENT 'Flag indicating whether this journal entry has been reversed by a subsequent offsetting entry. True when a reversal document exists; False otherwise. Used to exclude reversed entries from financial statement balances and to identify correction activity for SOX audit purposes.',
    `last_changed_timestamp` TIMESTAMP COMMENT 'The system timestamp of the most recent modification to this journal entry header record. Used for SOX change-tracking, incremental ETL processing, and audit trail completeness. Represents RECORD_AUDIT_UPDATED per canonical attribute requirements.',
    `ledger_code` STRING COMMENT 'Identifier for the accounting ledger in which this entry is recorded. In SAP S/4HANA Universal Journal, 0L is the leading ledger (GAAP), while parallel ledgers (1L, 2L) may capture FERC regulatory accounting or IFRS. Ensures correct financial statement presentation per applicable accounting framework.. Valid values are `0L|1L|2L|3L`',
    `line_item_count` STRING COMMENT 'Total number of journal entry line items (debit and credit legs) associated with this header record. Used for data completeness validation, balanced-entry checks, and identifying complex multi-line entries requiring additional review. Supports SOX control monitoring.',
    `local_currency_code` STRING COMMENT 'ISO 4217 three-letter code for the company code local currency (functional currency) in which amounts are also recorded. Supports multi-currency translation for consolidated GAAP financial statements and FERC Form 1 reporting. Corresponds to WAERS for local currency in SAP FI.. Valid values are `^[A-Z]{3}$`',
    `posting_date` DATE COMMENT 'The date on which the journal entry is posted to the general ledger and affects account balances. Determines the fiscal period assignment. Distinct from the document date (transaction date) and entry date (system capture date). Corresponds to BUDAT in SAP FI.',
    `posting_status` STRING COMMENT 'Current lifecycle state of the journal entry in the ERP workflow: draft (in preparation), parked (saved but not posted), held (temporarily suspended), posted (committed to GL), reversed (offset entry created), or cleared (open items matched). Supports SOX period-close controls and dual-approval enforcement.. Valid values are `draft|posted|parked|held|reversed|cleared`',
    `posting_user_code` STRING COMMENT 'ERP system user ID of the individual who created and posted this journal entry. Essential for SOX segregation-of-duties controls, audit trail completeness, and detection of unauthorized postings. Corresponds to USNAM in SAP FI.',
    `reference_document_number` STRING COMMENT 'External reference number linking this journal entry to the originating business document (e.g., vendor invoice number, purchase order number, work order number, billing document number, rate case docket number). Enables drill-through from GL to source transaction for audit and reconciliation. Corresponds to XBLNR in SAP FI.',
    `reversal_date` DATE COMMENT 'The posting date of the reversing journal entry. Used to determine the fiscal period in which the reversal is recorded. Populated only when is_reversed = True. Supports accrual reversal scheduling and period-close management.',
    `reversal_document_number` STRING COMMENT 'Document number of the reversing journal entry that offsets this entry. Populated only when is_reversed = True. Enables audit trail linkage between original and reversal entries for GAAP error correction and SOX controls. Corresponds to STBLG in SAP FI.',
    `source_module` STRING COMMENT 'The ERP functional module that originated this journal entry: FI (Financial Accounting), CO (Controlling/Cost Accounting), MM (Materials Management), PM (Plant Maintenance/Asset Management), SD (Sales and Distribution), PS (Project System for CAPEX/WIP), HR (Human Resources), RE (Real Estate). Supports cross-module reconciliation and FERC cost-of-service allocation. [ENUM-REF-CANDIDATE: FI|CO|MM|PM|SD|PS|HR|RE — 8 candidates stripped; promote to reference product]',
    `total_credit_amount` DECIMAL(18,2) COMMENT 'Sum of all credit line item amounts for this journal entry in the transaction currency. Must equal total_debit_amount for a balanced entry per double-entry bookkeeping. Used for balanced-entry validation, GAAP financial statement preparation, and FERC regulatory reporting.',
    `total_credit_amount_local` DECIMAL(18,2) COMMENT 'Sum of all credit line item amounts translated into the company code local currency (functional currency). Used for domestic financial statement preparation and FERC regulatory reporting when transaction currency differs from local currency.',
    `total_debit_amount` DECIMAL(18,2) COMMENT 'Sum of all debit line item amounts for this journal entry in the transaction currency. Must equal total_credit_amount for a balanced entry per double-entry bookkeeping. Used for balanced-entry validation, GAAP financial statement preparation, and FERC regulatory reporting.',
    `total_debit_amount_local` DECIMAL(18,2) COMMENT 'Sum of all debit line item amounts translated into the company code local currency (functional currency). Used for domestic financial statement preparation and FERC regulatory reporting when transaction currency differs from local currency.',
    `trading_partner_code` STRING COMMENT 'Company code of the intercompany trading partner entity involved in this journal entry. Populated only when is_intercompany = True. Used for intercompany reconciliation and elimination in consolidated GAAP financial statements. Corresponds to VBUND in SAP FI.',
    CONSTRAINT pk_journal_entry PRIMARY KEY(`journal_entry_id`)
) COMMENT 'Header record for every general ledger posting made in the utilitys ERP system (SAP S/4HANA or Oracle ERP Cloud). Captures journal entry number, posting date, fiscal period, fiscal year, document type (standard, accrual, reversal, intercompany, recurring, statistical), posting key, total debit amount, total credit amount, currency, reference document, source module (FI, CO, MM, PM, SD), posting user, approval status, and reversal indicator. Supports GAAP financial statement preparation, SOX internal controls (segregation of duties audit trail, dual-approval enforcement), and FERC regulatory accounting. Each journal entry header links to one or more line items captured in journal_entry_line. Balanced entry validation (total debits = total credits) is enforced at this level.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`journal_entry_line` (
    `journal_entry_line_id` BIGINT COMMENT 'Unique surrogate identifier for each journal entry line item in the general ledger. Primary key for this record in the Silver Layer lakehouse.',
    `cost_center_id` BIGINT COMMENT 'FK to finance.cost_center',
    `financial_period_id` BIGINT COMMENT 'Foreign key linking to finance.financial_period. Business justification: journal_entry_line has fiscal_year and fiscal_period attributes. financial_period is the master for fiscal periods. Normalizing this reference allows joining to get full period metadata (period_name, ',
    `gl_account_id` BIGINT COMMENT 'FK to finance.gl_account',
    `journal_entry_id` BIGINT COMMENT 'Reference to the parent journal entry header record. Establishes the one-to-many relationship between the header and its line items. Corresponds to SAP BKPF-BELNR (Accounting Document Number) surrogate key.',
    `profit_center_id` BIGINT COMMENT 'FK to finance.profit_center',
    `account_type` STRING COMMENT 'SAP account type for this posting line: A=Asset, D=Customer (Debtor), K=Vendor (Creditor), M=Material, S=GL Account. Determines the subledger integration and reporting classification. Corresponds to SAP BSEG-KOART.. Valid values are `A|D|K|M|S`',
    `amount_company_currency` DECIMAL(18,2) COMMENT 'The monetary amount of this line item translated into the company codes local currency (e.g., USD). Used for consolidated financial statements, FERC reporting, and SOX-compliant audit trails. Corresponds to SAP BSEG-DMBTR.',
    `amount_transaction_currency` DECIMAL(18,2) COMMENT 'The monetary amount of this line item expressed in the transaction currency. Positive for debits, negative for credits (or vice versa per system convention). Corresponds to SAP BSEG-WRBTR.',
    `asset_number` STRING COMMENT 'SAP fixed asset number when this line item relates to an asset acquisition, depreciation, or retirement posting. Links to the asset accounting subledger for utility plant-in-service tracking. Corresponds to SAP BSEG-ANLN1.',
    `assignment_number` STRING COMMENT 'Free-form assignment field used to link this posting to a source document reference such as a customer account number, contract number, or payment reference. Supports open item management and clearing. Corresponds to SAP BSEG-ZUONR.',
    `business_area_code` STRING COMMENT 'SAP business area for cross-company-code segment reporting, enabling balance sheet and P&L reporting by business segment (e.g., electric utility, gas utility, unregulated). Corresponds to SAP BSEG-GSBER.. Valid values are `^[A-Z0-9]{4}$`',
    `capex_opex_indicator` STRING COMMENT 'Classifies this posting as a capital expenditure (CAPEX) or operating expenditure (OPEX). Critical for utility rate base determination, regulatory cost-of-service studies, and FERC plant accounting. Drives the distinction between plant-in-service additions and expense recognition.. Valid values are `CAPEX|OPEX`',
    `clearing_date` DATE COMMENT 'Date on which this open item was cleared (matched against a payment or offsetting entry). Null if the item remains open. Used for DSO (Days Sales Outstanding) analysis and collections reporting. Corresponds to SAP BSEG-AUGDT.',
    `clearing_document_number` STRING COMMENT 'Document number of the clearing transaction that offset this open item (e.g., payment clearing an invoice). Null if the item is still open. Supports accounts receivable/payable reconciliation and aging analysis. Corresponds to SAP BSEG-AUGBL.',
    `company_code` STRING COMMENT 'SAP company code representing the legal entity or regulated utility subsidiary to which this posting belongs. Used for entity-level financial reporting and FERC jurisdictional separation. Corresponds to SAP BSEG-BUKRS.. Valid values are `^[A-Z0-9]{4}$`',
    `company_currency_code` STRING COMMENT 'ISO 4217 three-letter currency code of the company codes local currency (typically USD for US utilities). Used for consolidated financial reporting. Corresponds to SAP BSEG-PSWSL.. Valid values are `^[A-Z]{3}$`',
    `customer_number` STRING COMMENT 'SAP customer (debtor) account number when this line item relates to a customer receivable posting (e.g., utility bill revenue recognition). Links to the accounts receivable subledger. Corresponds to SAP BSEG-KUNNR.',
    `debit_credit_indicator` STRING COMMENT 'Indicates whether this line item is a debit (D) or credit (C) posting to the GL account. Fundamental to double-entry bookkeeping and ensures journal entry balance. Corresponds to SAP BSEG-SHKZG.. Valid values are `D|C`',
    `document_date` DATE COMMENT 'The date of the original source document (invoice, contract, work order) that triggered this journal entry line. May differ from posting date for accruals and retroactive adjustments. Corresponds to SAP BKPF-BLDAT.',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts code mapped to this GL posting line. Required for FERC Form 1 (electric) and FERC Form 2 (gas) annual report filings. Enables regulatory cost-of-service studies and rate case preparation. Distinct from the internal GL account code.. Valid values are `^[0-9]{3}(.{1}[0-9]{1,3})?$`',
    `fiscal_period` STRING COMMENT 'Accounting period (1–16 in SAP, where 13–16 are special closing periods) within the fiscal year for this posting. Drives period-end close reporting, monthly P&L, and regulatory period reporting. Corresponds to SAP BSEG-MONAT.',
    `fiscal_year` STRING COMMENT 'The fiscal year in which this journal entry line is posted. Used for annual financial reporting, rate case cost-of-service studies, and FERC Form 1 annual report preparation. Corresponds to SAP BSEG-GJAHR.',
    `functional_area_code` STRING COMMENT 'SAP functional area classifying the business function of this posting (e.g., generation, transmission, distribution, customer service, administration). Supports functional cost reporting required for FERC cost-of-service studies and rate case filings. Corresponds to SAP BSEG-FKBER.',
    `line_item_text` STRING COMMENT 'Free-text description of this individual posting line providing context for the transaction (e.g., Q3 fuel adjustment accrual, Substation transformer replacement CAPEX). Supports SOX audit trail and financial statement footnote preparation. Corresponds to SAP BSEG-SGTXT.',
    `line_number` STRING COMMENT 'Sequential line item number within the parent journal entry, used to order and uniquely identify each posting line within a document. Corresponds to SAP BSEG-BUZEI (Line Item Number).',
    `open_item_indicator` BOOLEAN COMMENT 'Indicates whether this line item remains open (uncleared) in the GL. True = open item pending clearing; False = item has been cleared. Drives accounts receivable/payable aging reports and collections workflows.',
    `order_number` STRING COMMENT 'SAP internal order number for overhead cost collection, capital investment orders, or maintenance orders. Used to accumulate costs for specific projects or activities before settlement to cost centers or WBS elements. Corresponds to SAP BSEG-AUFNR.',
    `plant_code` STRING COMMENT 'SAP plant code identifying the operational facility (generation plant, service center, substation) associated with this posting. Enables plant-level cost analysis and asset-level CAPEX/OPEX tracking. Corresponds to SAP BSEG-WERKS.. Valid values are `^[A-Z0-9]{4}$`',
    `posting_date` DATE COMMENT 'The date on which this line item is posted to the general ledger, determining the accounting period assignment. Critical for period-end close, accrual cutoff, and FERC regulatory reporting. Corresponds to SAP BSEG-BUDAT.',
    `posting_key` STRING COMMENT 'Two-digit SAP posting key that determines the account type, debit/credit side, and field status for this line item (e.g., 40=GL debit, 50=GL credit, 01=customer invoice, 31=vendor invoice). Corresponds to SAP BSEG-BSCHL.. Valid values are `^[0-9]{2}$`',
    `quantity` DECIMAL(18,2) COMMENT 'Quantity associated with this line item when the posting relates to a quantity-based transaction (e.g., MWh of energy purchased, MCF of gas consumed, number of meters installed). Corresponds to SAP BSEG-MENGE.',
    `quantity_unit` STRING COMMENT 'Unit of measure for the quantity field (e.g., MWh for energy, MCF for gas, EA for each/count, HR for hours). Aligns with utility industry standard units for energy and gas accounting. Corresponds to SAP BSEG-MEINS. [ENUM-REF-CANDIDATE: MWh|kWh|MCF|Therm|MW|kW|EA|HR|M3|GJ — 10 candidates stripped; promote to reference product]',
    `reference_document_number` STRING COMMENT 'External reference document number (e.g., vendor invoice number, purchase order number, work order number) that originated this posting. Enables cross-system traceability from GL to source transaction. Corresponds to SAP BKPF-XBLNR.',
    `regulatory_jurisdiction` STRING COMMENT 'Identifies the regulatory jurisdiction applicable to this posting: FERC (federal jurisdiction for transmission and wholesale), STATE (state PUC jurisdiction for distribution and retail), BOTH (dual jurisdiction), or UNREGULATED (non-regulated activities). Supports jurisdictional cost separation required for rate case filings.. Valid values are `FERC|STATE|BOTH|UNREGULATED`',
    `reversal_document_number` STRING COMMENT 'Document number of the reversing or reversed journal entry. Populated when reversal_indicator is True, enabling traceability between original and reversing entries for SOX audit and period-close reconciliation. Corresponds to SAP BKPF-STBLG.',
    `reversal_indicator` BOOLEAN COMMENT 'Indicates whether this line item is part of a reversal document (True) or an original posting (False). Reversal entries are critical for period-end accrual management and SOX audit trail integrity.',
    `segment_code` STRING COMMENT 'Financial reporting segment assigned to this line item for GAAP segment disclosures (e.g., regulated electric, regulated gas, unregulated). Supports GAAP ASC 280 segment reporting requirements in annual financial statements. Corresponds to SAP BSEG-SEGMENT.',
    `source_ledger_code` STRING COMMENT 'Identifies the source ledger or subledger from which this posting originated (e.g., 0L=Leading Ledger, 2L=IFRS Ledger, US=US GAAP Ledger). Supports parallel accounting for GAAP and regulatory reporting. Corresponds to SAP BSEG-RLDNR.. Valid values are `^[A-Z0-9]{2}$`',
    `special_gl_indicator` STRING COMMENT 'SAP special GL indicator identifying non-standard postings such as down payments (A), guarantees (B), or bill of exchange (W). Used to segregate special transactions in balance sheet reporting. Corresponds to SAP BSEG-UMSKZ.. Valid values are `^[A-Z0-9]?$`',
    `tax_amount` DECIMAL(18,2) COMMENT 'Tax amount calculated for this line item in company code currency. Includes applicable sales tax, use tax, or gross receipts tax. Corresponds to SAP BSEG-WMWST.',
    `tax_code` STRING COMMENT 'Tax code assigned to this line item determining applicable tax rates and tax account postings (e.g., sales tax, use tax, gross receipts tax). Required for tax compliance reporting and regulatory filings. Corresponds to SAP BSEG-MWSKZ.. Valid values are `^[A-Z0-9]{2}$`',
    `transaction_currency_code` STRING COMMENT 'ISO 4217 three-letter currency code of the original transaction (e.g., USD for domestic, CAD for cross-border Canadian operations). Corresponds to SAP BSEG-WAERS.. Valid values are `^[A-Z]{3}$`',
    `vendor_number` STRING COMMENT 'SAP vendor (creditor) account number when this line item relates to a vendor payable posting. Links to the accounts payable subledger for vendor balance and aging reporting. Corresponds to SAP BSEG-LIFNR.',
    `wbs_element_code` STRING COMMENT 'Project WBS element code for CAPEX postings, enabling capital project cost tracking, AFUDC calculation, and WIP balance management. Critical for utility plant accounting and rate base determination. Corresponds to SAP BSEG-PS_PSP_PNR (WBS Element).',
    CONSTRAINT pk_journal_entry_line PRIMARY KEY(`journal_entry_line_id`)
) COMMENT 'Line-item detail for each general ledger journal entry posting. Captures line number, GL account, cost center, WBS element, functional area, debit/credit indicator, amount in transaction currency, amount in company code currency, tax code, profit center, segment, and business area. Enables granular cost allocation, FERC account-level reporting, and SOX-compliant audit trails at the individual posting level. One-to-many relationship with journal_entry header.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`capex_project` (
    `capex_project_id` BIGINT COMMENT 'Unique surrogate identifier for the capital expenditure project record in the Databricks Silver Layer. Primary key for the capex_project data product.',
    `cost_center_id` BIGINT COMMENT 'Foreign key linking to finance.cost_center. Business justification: capex_project has cost_center attribute (STRING). cost_center is the master for cost centers. Normalizing this reference allows joining to get full cost center details (name, responsible_manager, func',
    `location_id` BIGINT COMMENT 'Foreign key linking to asset.asset_location. Business justification: Capital projects must be assigned to service territory locations for geographic cost allocation, regulatory jurisdiction determination, and project portfolio management. Replaces denormalized function',
    `rate_case_id` BIGINT COMMENT 'Reference to the regulatory rate case in which this capital projects costs are included for rate base recovery. Links capital investment to the regulatory docket for cost-of-service studies and plant additions testimony.',
    `actual_cost_to_date` DECIMAL(18,2) COMMENT 'Cumulative actual capital expenditures incurred on the project to date, expressed in US dollars. Sourced from the ERP cost collection against the WBS element. Used for CWIP balance reporting, budget variance analysis, and capital program tracking.',
    `actual_in_service_date` DATE COMMENT 'Actual date on which the capital project assets were placed in service and transferred from CWIP to plant in service accounts. Triggers AFUDC cessation, depreciation commencement, and inclusion in rate base. Null until the project reaches in-service status.',
    `afudc_accrued_amount` DECIMAL(18,2) COMMENT 'Cumulative AFUDC amount capitalized to the project to date, expressed in US dollars. Represents the financing cost of construction capitalized per FERC accounting rules. Included in the total project cost and rate base upon in-service. Null if afudc_eligible is False.',
    `afudc_eligible` BOOLEAN COMMENT 'Flag indicating whether this capital project is eligible for Allowance for Funds Used During Construction (AFUDC) accrual (True) or not (False). AFUDC represents the cost of financing construction and is capitalized to the project per FERC accounting rules. Eligibility is determined by project type, duration, and regulatory authorization.',
    `afudc_rate` DECIMAL(18,2) COMMENT 'AFUDC accrual rate applied to the projects CWIP balance to calculate the monthly AFUDC capitalization, expressed as a decimal (e.g., 0.075000 for 7.5%). Rate is set by the utilitys regulatory accounting policy and approved by FERC or state PUC. Null if afudc_eligible is False.',
    `asset_class` STRING COMMENT 'Asset class designation that categorizes the type of utility plant asset being constructed or acquired (e.g., Overhead Lines, Underground Cable, Transformers, Meters, Gas Mains, Buildings, IT Equipment). Aligns with Oracle WAM or IBM Maximo asset class hierarchy and FERC plant account groupings. [ENUM-REF-CANDIDATE: overhead_lines|underground_cable|transformers|meters|gas_mains|buildings|it_equipment|generation_equipment|substation_equipment|vehicles — promote to reference product]',
    `authorization_date` DATE COMMENT 'Date on which the capital budget for this project was formally authorized through the utilitys capital appropriations approval process. Marks the transition from planned to approved status and enables commitment of funds.',
    `authorized_budget_amount` DECIMAL(18,2) COMMENT 'Total capital budget amount authorized by the utilitys capital appropriations process for this project, expressed in US dollars. Represents the approved spending ceiling for the project. Used for capital program tracking, variance analysis, and rate case cost-of-service studies.',
    `capex_opex_split_pct` DECIMAL(18,2) COMMENT 'Percentage of total project costs classified as capital expenditure (CAPEX) versus operating expenditure (OPEX), expressed as the CAPEX percentage (0.00 to 100.00). Supports GAAP capitalization policy compliance and regulatory cost classification for rate case filings.',
    `ciac_amount` DECIMAL(18,2) COMMENT 'Dollar amount of Contribution in Aid of Construction (CIAC) received or expected for this project, expressed in US dollars. Reduces the utilitys net capital investment and rate base. Null if ciac_indicator is False.',
    `ciac_indicator` BOOLEAN COMMENT 'Flag indicating whether this capital project involves a Contribution in Aid of Construction (CIAC) from a customer or developer (True) or not (False). CIAC represents funds or assets contributed by third parties to fund utility infrastructure extensions. Affects rate base treatment and tax accounting under GAAP and FERC rules.',
    `close_date` DATE COMMENT 'Date on which the capital project was formally closed in the ERP system, finalizing all cost postings and completing the CWIP-to-plant transfer. Null until the project reaches closed status.',
    `cost_center` STRING COMMENT 'SAP or ERP cost center code associated with the sponsoring department for this capital project. Used for cost allocation, departmental CAPEX reporting, and rate case cost-of-service studies.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the capital project record was first created in the source ERP system (SAP PS or Oracle Projects), in ISO 8601 format with timezone offset. Supports audit trail, SOX compliance, and data lineage tracking.',
    `cwip_account` STRING COMMENT 'FERC Account 107 (Electric) or Account 105 (Gas) Construction Work in Progress sub-account code used to accumulate project costs prior to in-service date. Supports CWIP balance reporting for rate case filings and regulatory plant additions schedules.',
    `depreciation_rate` DECIMAL(18,2) COMMENT 'Annual straight-line depreciation rate applied to the capital project assets upon in-service, expressed as a decimal (e.g., 0.033333 for 3.33% / 30-year life). Determined by the utilitys FERC-approved or PUC-approved depreciation study by asset class. Null until the project is placed in service.',
    `estimated_cost_at_completion` DECIMAL(18,2) COMMENT 'Current forecast of total project cost at completion, expressed in US dollars. Reflects the project managers latest estimate incorporating actual costs to date plus remaining work. Supports capital program forecasting and rate case cost-of-service studies.',
    `ferc_plant_account` STRING COMMENT 'FERC Uniform System of Accounts plant account number to which the completed capital project will be classified upon in-service (e.g., Account 101 Electric Plant in Service, Account 107 Construction Work in Progress, Account 303 Miscellaneous Intangible Plant, Account 350 Land and Land Rights - Transmission). Critical for regulatory accounting, rate base calculations, and FERC Form 1 reporting.',
    `fiscal_year` STRING COMMENT 'Fiscal year in which the capital project is primarily budgeted and tracked (e.g., 2024). Used for annual capital program reporting, budget cycle alignment, and year-over-year CAPEX trend analysis.',
    `is_blanket_project` BOOLEAN COMMENT 'Flag indicating whether this is a blanket capital project (True) or a specific discrete capital project (False). Blanket projects represent recurring capital programs (e.g., annual pole replacement, annual meter deployment) that aggregate multiple small work orders under a single project authorization. Specific projects represent discrete capital investments with defined scope and budget.',
    `justification_category` STRING COMMENT 'Primary business justification category for the capital investment. Used for capital program portfolio analysis and regulatory prudency demonstrations. Values: reliability (grid or system reliability improvement), safety (worker or public safety), regulatory_compliance (mandated by FERC, PUC, EPA, NERC, PHMSA, or OSHA), growth (customer growth or load growth), replacement (end-of-life asset replacement), efficiency (operational efficiency improvement), environmental (environmental remediation or GHG reduction). [ENUM-REF-CANDIDATE: reliability|safety|regulatory_compliance|growth|replacement|efficiency|environmental — 7 candidates stripped; promote to reference product]',
    `last_updated_timestamp` TIMESTAMP COMMENT 'Timestamp when the capital project record was most recently modified in the source ERP system, in ISO 8601 format with timezone offset. Supports change tracking, SOX audit trail, and incremental data pipeline processing.',
    `nerc_reliability_standard` STRING COMMENT 'NERC reliability standard (e.g., FAC-001, TPL-001, PRC-005) that mandates or drives this capital project, if applicable. Null if the project is not driven by a NERC compliance requirement. Supports regulatory compliance reporting and capital prudency documentation.',
    `plant_addition_amount` DECIMAL(18,2) COMMENT 'Final gross plant addition amount recorded to the FERC plant in service account upon project close-out and in-service transfer, expressed in US dollars. Represents the capitalized cost of the asset placed in service, net of any CIAC. Used for FERC Form 1 plant additions schedule and rate base calculations.',
    `priority_rank` STRING COMMENT 'Numeric priority ranking of the capital project within the utilitys annual capital program, used for capital budget allocation and deferral decisions. Lower numbers indicate higher priority. Assigned during the annual capital planning cycle.',
    `program_name` STRING COMMENT 'Name of the capital program or portfolio under which this project is grouped (e.g., Grid Modernization Program, Gas Main Replacement Program, AMI Deployment Program). Supports capital program-level reporting and strategic investment tracking.',
    `project_description` STRING COMMENT 'Detailed narrative description of the capital project scope, including the work to be performed, assets to be installed or replaced, and business justification. Supports rate case cost-of-service studies and regulatory reporting to PUCs and FERC.',
    `project_manager` STRING COMMENT 'Name or employee identifier of the project manager responsible for delivering the capital project on time and within budget. Used for accountability tracking, capital program reporting, and escalation routing.',
    `project_name` STRING COMMENT 'Short human-readable name or title of the capital expenditure project (e.g., Substation 12 Transformer Replacement, Annual Pole Replacement Program FY2024). Used in dashboards, capital program reports, and regulatory plant additions filings.',
    `project_number` STRING COMMENT 'Externally-known alphanumeric project identifier assigned by the Enterprise Resource Planning (ERP) system (e.g., SAP PS WBS element or Oracle Project number). Used for cross-system reference, regulatory filings, and rate case cost-of-service studies.',
    `project_start_date` DATE COMMENT 'Date on which capital project activities (design, procurement, or construction) formally commenced. Used for project duration tracking, AFUDC accrual period calculation, and capital program scheduling.',
    `project_status` STRING COMMENT 'Current lifecycle status of the capital expenditure project. Drives capital program prioritization, CWIP balance reporting, and regulatory plant additions reporting. Values: planned (identified but not yet authorized), approved (capital budget authorized), in_progress (construction or implementation underway), complete (work finished, pending close-out), closed (fully closed and placed in service or written off), cancelled (project terminated prior to completion).. Valid values are `planned|approved|in_progress|complete|closed|cancelled`',
    `project_type` STRING COMMENT 'Functional classification of the capital project by utility business segment. Used for capital program segmentation, regulatory reporting, and rate base allocation. Values: transmission (high-voltage bulk electric infrastructure), distribution (last-mile electric delivery), generation (power plant assets), gas (natural gas pipeline and distribution), it (information technology infrastructure), environmental_compliance (environmental or regulatory compliance investments).. Valid values are `transmission|distribution|generation|gas|it|environmental_compliance`',
    `regulatory_jurisdiction` STRING COMMENT 'Regulatory jurisdiction governing the capital project for rate base and cost recovery purposes. Values: ferc (subject to FERC jurisdiction, e.g., transmission assets), state_puc (subject to state Public Utility Commission jurisdiction, e.g., distribution assets), both (dual jurisdiction), exempt (not subject to rate regulation).. Valid values are `ferc|state_puc|both|exempt`',
    `revised_budget_amount` DECIMAL(18,2) COMMENT 'Most recent revised authorized budget amount reflecting approved budget amendments or change orders since original authorization. Null if no revisions have been approved. Supports capital program variance reporting and rate case prudency reviews.',
    `service_territory` STRING COMMENT 'Geographic service territory or operating division within which the capital project is located (e.g., Northern Region, Southern Region, Metro District). Used for geographic capital program analysis and regulatory jurisdiction reporting.',
    `sox_control_relevant` BOOLEAN COMMENT 'Flag indicating whether this capital project is subject to Sarbanes-Oxley (SOX) internal controls over financial reporting (True) or not (False). SOX-relevant projects require documented approval workflows, segregation of duties, and audit trail maintenance per SOX Section 302 and 404 requirements.',
    `sponsoring_department` STRING COMMENT 'Name or code of the utility business department or organizational unit sponsoring and accountable for the capital project (e.g., Transmission Engineering, Distribution Operations, Gas Operations, IT). Used for capital program allocation and departmental CAPEX reporting.',
    `target_in_service_date` DATE COMMENT 'Planned date on which the capital project assets are expected to be placed in service and transferred from Construction Work in Progress (CWIP) to plant in service accounts. Drives capital program scheduling, AFUDC cessation planning, and regulatory plant additions forecasting.',
    `wbs_element` STRING COMMENT 'Work Breakdown Structure element code that hierarchically organizes the capital project within the utilitys capital program. Aligns with SAP PS WBS element or Oracle Projects task structure for cost collection and CWIP balance reporting.',
    CONSTRAINT pk_capex_project PRIMARY KEY(`capex_project_id`)
) COMMENT 'Master record for capital expenditure projects tracked under the utilitys capital program. Captures WBS (Work Breakdown Structure) element, project number, project description, asset class, FERC plant account (e.g., Account 101 Electric Plant in Service, Account 107 Construction Work in Progress), project type (transmission, distribution, generation, gas, IT, environmental/compliance), authorized capital budget, AFUDC (Allowance for Funds Used During Construction) eligibility flag and accrual rate, CIAC (Contribution in Aid of Construction) indicator and amount, project manager, in-service date target, actual in-service date, project status (planned, approved, in-progress, complete, closed, cancelled), and blanket vs. specific project indicator. Supports CAPEX tracking, rate base calculations, CWIP balance reporting, regulatory plant additions reporting, and capital program prioritization. Blanket projects represent recurring capital programs (e.g., annual pole replacement) while specific projects represent discrete capital investments.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`capex_expenditure` (
    `capex_expenditure_id` BIGINT COMMENT 'Unique surrogate identifier for each capital expenditure transaction record in the Silver layer lakehouse. Primary key for this entity.',
    `capex_project_id` BIGINT COMMENT 'Reference to the authorized capital project or WBS (Work Breakdown Structure) element to which this expenditure is charged. Links the expenditure to the approved capital budget authorization.',
    `cost_center_id` BIGINT COMMENT 'FK to finance.cost_center',
    `financial_period_id` BIGINT COMMENT 'Foreign key linking to finance.financial_period. Business justification: capex_expenditure has fiscal_year and fiscal_period attributes. financial_period is the master for fiscal periods. Normalizing this reference allows joining to get full period metadata. fiscal_year an',
    `gl_account_id` BIGINT COMMENT 'FK to finance.gl_account',
    `master_id` BIGINT COMMENT 'Reference to the fixed asset or asset-under-construction to which this expenditure will be capitalized upon project completion. Null while the project is in Construction Work in Progress (CWIP) status.',
    `material_master_id` BIGINT COMMENT 'Foreign key linking to supply.material_master. Business justification: Capital expenditures often involve specific materials (transformers, poles, cable, meters) that must be tracked for asset records, warranty management, and FERC plant accounting. Links capex spend to ',
    `purchase_order_id` BIGINT COMMENT 'FK to supply.purchase_order',
    `vendor_id` BIGINT COMMENT 'Reference to the vendor or contractor who supplied materials or services for this capital expenditure. Sourced from the ERP vendor master (SAP S/4HANA or Oracle ERP Cloud).',
    `work_order_id` BIGINT COMMENT 'Reference to the work order (from Oracle WAM or IBM Maximo) under which the capital work was performed. Connects the financial expenditure to the physical asset maintenance or construction activity.',
    `afudc_amount` DECIMAL(18,2) COMMENT 'The dollar amount of AFUDC accrued on this capital expenditure for the applicable period. Calculated as expenditure balance multiplied by the AFUDC rate. Capitalized to the asset cost basis and recovered through depreciation in rates.',
    `afudc_rate` DECIMAL(18,2) COMMENT 'The AFUDC rate applied to this expenditure for the period, expressed as a decimal (e.g., 0.075 for 7.5%). AFUDC represents the cost of financing construction and is capitalized to the asset cost basis per FERC regulations and GAAP ASC 835-20.',
    `approval_reference` STRING COMMENT 'Reference number or identifier for the capital authorization document (e.g., Capital Appropriation Request, Board Resolution, or CPCN number) that approved this expenditure. Required for SOX compliance and audit trail.',
    `approved_by` STRING COMMENT 'Name or employee identifier of the individual who approved this capital expenditure transaction. Required for SOX internal controls documentation and audit trail.',
    `asset_class` STRING COMMENT 'High-level classification of the utility asset type being constructed or acquired. Drives FERC plant account assignment and depreciation rate selection. Values align with FERC Uniform System of Accounts plant categories.. Valid values are `generation|transmission|distribution|gas_distribution|general_plant|intangible`',
    `budget_amount` DECIMAL(18,2) COMMENT 'The approved capital budget amount for the project or WBS element at the time of this expenditure. Used for budget-to-actual variance analysis and capital spend tracking against authorized CAPEX.',
    `capitalization_status` STRING COMMENT 'Current capitalization lifecycle state of this expenditure. wip indicates the cost is in Construction Work in Progress (CWIP); placed_in_service indicates the asset has been capitalized to the fixed asset register; expensed indicates the cost was reclassified as OPEX; reversed indicates a correcting entry; pending_review indicates awaiting capitalization determination.. Valid values are `wip|placed_in_service|expensed|reversed|pending_review`',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this capital expenditure record was first created in the source system or ingested into the Silver layer. Used for audit trail, SOX compliance, and data lineage tracking.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for the expenditure amounts (e.g., USD). Power and Utilities operates primarily in USD; this field supports multi-currency ERP configurations and foreign contractor invoices.. Valid values are `^[A-Z]{3}$`',
    `expenditure_amount` DECIMAL(18,2) COMMENT 'Gross amount of the capital expenditure in USD before any adjustments. Represents the base cost charged to the CAPEX project for this transaction line. Used for CWIP balance tracking and budget variance analysis.',
    `expenditure_date` DATE COMMENT 'The actual calendar date on which the capital expenditure was incurred or the cost was recognized. This is the principal business event date used for CWIP balance reporting and period-end close.',
    `expenditure_description` STRING COMMENT 'Free-text description of the capital expenditure, including the nature of work performed, materials procured, or services rendered. Provides context for audit review, rate case cost justification, and asset capitalization documentation.',
    `expenditure_number` STRING COMMENT 'Externally-known business identifier for this capital expenditure transaction, typically sourced from the ERP system (e.g., SAP S/4HANA document number or Oracle ERP Cloud transaction number). Used for cross-system traceability and audit.',
    `expenditure_type` STRING COMMENT 'Classification of the nature of the capital expenditure. Drives cost allocation and capitalization treatment. Values: labor (internal workforce), materials (equipment and supplies), contractor (third-party services), overhead (allocated indirect costs), afudc_accrual (Allowance for Funds Used During Construction accrual), other.. Valid values are `labor|materials|contractor|overhead|afudc_accrual|other`',
    `ferc_plant_account` STRING COMMENT 'FERC Uniform System of Accounts plant account number (e.g., Account 310-399 for Electric Plant in Service, Account 107 for CWIP) to which this expenditure is classified. Required for FERC Form 1 regulatory reporting and rate case cost-of-service studies.',
    `fiscal_period` STRING COMMENT 'The fiscal accounting period (month number, 1-12) within the fiscal year in which this expenditure is posted. Used for monthly CAPEX tracking, period-end close reconciliation, and management reporting.',
    `fiscal_year` STRING COMMENT 'The fiscal year in which this capital expenditure is recorded. Used for annual CAPEX budget tracking, FERC Form 1 annual reporting, and year-over-year capital spend analysis.',
    `functional_location` STRING COMMENT 'The physical or logical functional location code (from Oracle WAM, IBM Maximo, or ESRI ArcGIS GIS system) identifying where the capital work is being performed. Examples: substation identifier, transmission line segment, distribution circuit, gas pipeline segment.',
    `invoice_number` STRING COMMENT 'The vendor invoice number associated with this capital expenditure. Used for accounts payable matching, audit trail, and dispute resolution. Sourced from the ERP accounts payable module.',
    `is_afudc_eligible` BOOLEAN COMMENT 'Indicates whether this expenditure qualifies for AFUDC accrual under FERC regulations and GAAP ASC 835-20. True if the expenditure is part of a qualifying construction project with a construction period exceeding the AFUDC threshold.',
    `is_capitalized` BOOLEAN COMMENT 'Indicates whether this expenditure has been formally capitalized to the fixed asset register (True) or remains in CWIP or has been expensed (False). Used to filter capitalized vs. in-progress costs for balance sheet reporting.',
    `net_amount` DECIMAL(18,2) COMMENT 'Net capital expenditure amount after adjustments, credits, or reversals (expenditure_amount + tax_amount minus any credits). Represents the final capitalized cost contribution of this transaction to the project.',
    `placed_in_service_date` DATE COMMENT 'The date on which the constructed or acquired asset was placed in service and transferred from CWIP (Construction Work in Progress) to the fixed asset register. Triggers the start of depreciation and AFUDC cessation. Null while the project remains in WIP status.',
    `posting_date` DATE COMMENT 'The date on which the expenditure was posted to the General Ledger (GL) in the ERP system. May differ from expenditure_date due to period-end accruals or late postings. Used for financial period reconciliation.',
    `quantity` DECIMAL(18,2) COMMENT 'Quantity of units (hours, units of material, etc.) associated with this capital expenditure. For labor expenditures, represents hours worked. For materials, represents units procured. Used for unit cost analysis and project cost benchmarking.',
    `regulatory_jurisdiction` STRING COMMENT 'Indicates the regulatory jurisdiction governing this capital expenditure for rate recovery purposes. ferc for FERC-jurisdictional transmission assets, state_puc for state-regulated distribution assets, both for dual-jurisdiction assets, non_regulated for unregulated capital.. Valid values are `ferc|state_puc|both|non_regulated`',
    `service_territory` STRING COMMENT 'The utility service territory or operating division where the capital expenditure is incurred. Used for jurisdictional cost allocation in rate cases filed with state Public Utility Commissions (PUCs) and FERC.',
    `source_system` STRING COMMENT 'Identifies the operational system of record from which this capital expenditure record was sourced. Used for data lineage, ETL reconciliation, and audit trail in the Databricks Silver layer lakehouse.. Valid values are `sap_s4hana|oracle_erp_cloud|oracle_wam|ibm_maximo|manual`',
    `source_transaction_reference` STRING COMMENT 'The native transaction identifier from the source operational system (e.g., SAP S/4HANA accounting document number, Oracle ERP Cloud expenditure item ID). Enables traceability from the Silver layer back to the system of record for reconciliation and audit.',
    `tax_amount` DECIMAL(18,2) COMMENT 'Sales or use tax amount associated with this capital expenditure, if applicable. Capitalized taxes are included in the cost basis of the asset per GAAP. Reported separately for tax compliance and rate case cost-of-service studies.',
    `unit_of_measure` STRING COMMENT 'Unit of measure for the expenditure quantity (e.g., hours for labor, each for equipment units, feet/miles for cable or pipeline, kVA or MW for electrical equipment). Used for unit cost benchmarking and project cost analysis. [ENUM-REF-CANDIDATE: hours|each|feet|miles|kva|mw|lbs|tons|other — 9 candidates stripped; promote to reference product]',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp when this capital expenditure record was last modified in the source system or updated in the Silver layer. Used for change tracking, incremental ETL processing, and SOX audit trail.',
    `wbs_element` STRING COMMENT 'The specific WBS element code within the capital project hierarchy to which this expenditure is charged. Provides granular cost tracking within a multi-phase or multi-component capital project.',
    CONSTRAINT pk_capex_expenditure PRIMARY KEY(`capex_expenditure_id`)
) COMMENT 'Transactional record of actual capital expenditures charged to a CAPEX project or WBS element. Captures expenditure date, amount, expenditure type (labor, materials, contractor, overhead, AFUDC accrual), purchase order reference, vendor, cost center, GL account, FERC plant account, capitalization status (WIP vs. placed-in-service), and approval reference. Enables tracking of spend against authorized capital budget, supports CWIP (Construction Work in Progress) balance reporting, and feeds the fixed asset capitalization process upon project completion.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`budget` (
    `budget_id` BIGINT COMMENT 'Unique surrogate identifier for each budget record in the Silver Layer lakehouse. Each record represents a unique combination of budget version, budget type, cost center, GL account, and fiscal year. Sourced from SAP S/4HANA CO-PA or Oracle ERP Cloud Budgetary Control module.',
    `capex_project_id` BIGINT COMMENT 'FK to finance.capex_project',
    `cost_center_id` BIGINT COMMENT 'Reference to the cost center responsible for this budget record. Cost centers represent organizational units (e.g., Generation Operations, T&D Maintenance, Customer Service) used for OPEX and CAPEX allocation in FERC Uniform System of Accounts reporting.',
    `financial_period_id` BIGINT COMMENT 'Foreign key linking to finance.financial_period. Business justification: budget has fiscal_year and fiscal_period attributes. financial_period is the master for fiscal periods. Normalizing this reference allows joining to get full period metadata (period dates, status, etc',
    `gl_account_id` BIGINT COMMENT 'Reference to the General Ledger account associated with this budget record. GL accounts are structured per FERC Uniform System of Accounts (e.g., Account 401 for Revenue, Account 500-series for O&M expenses, Account 100-series for utility plant CAPEX).',
    `profit_center_id` BIGINT COMMENT 'FK to finance.profit_center',
    `allocation_factor` DECIMAL(18,2) COMMENT 'The proportional allocation factor (0.000000 to 1.000000) used to distribute shared or common costs across jurisdictions, functional areas, or cost centers in rate case cost-of-service studies. Derived from FERC-approved or PUC-approved allocation methodologies (e.g., plant ratio, revenue ratio, customer count).',
    `approval_date` DATE COMMENT 'The date on which this budget record received formal approval (yyyy-MM-dd). Marks the start of the authorized budget execution period. Used for SOX audit trail, board resolution documentation, and rate case filing timelines.',
    `approval_status` STRING COMMENT 'Current workflow status of the budget record in the approval lifecycle. draft indicates budget under preparation; pending_approval indicates submitted for management or board review; approved indicates authorized for execution; rejected indicates returned for revision; superseded indicates replaced by a revised version.. Valid values are `draft|pending_approval|approved|rejected|superseded`',
    `approved_amount` DECIMAL(18,2) COMMENT 'The total board- or management-approved budget amount in USD for this cost center, GL account, and fiscal year combination. Represents the authorized spending or revenue target. Used as the baseline for budget-vs-actual variance analysis and rate case test year cost-of-service calculations.',
    `approved_by` STRING COMMENT 'Name or employee identifier of the executive or board member who formally approved this budget record. Required for SOX audit trail and internal control documentation. For CAPEX budgets, may reference the Capital Expenditure Committee or Board of Directors approval.',
    `asset_category` STRING COMMENT 'The utility asset category for CAPEX budget records (e.g., Generation Plant, Transmission Lines, Distribution Substation, Gas Pipeline, Smart Meter/AMI, IT Infrastructure). Aligns with FERC plant account classifications for regulatory depreciation and rate base inclusion. Null for OPEX budget records.',
    `budget_type` STRING COMMENT 'Classifies the nature of the budget record. opex covers O&M operating expenditures; capex covers capital expenditures for utility plant additions; revenue covers projected rate revenues; depreciation covers regulatory depreciation expense budgets; regulatory covers rate case and compliance cost budgets. Aligns with FERC Uniform System of Accounts classification.. Valid values are `opex|capex|revenue|depreciation|regulatory`',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this budget record was first created in the source system or ingested into the Silver Layer lakehouse (yyyy-MM-ddTHH:mm:ss.SSSXXX). Required for SOX audit trail and data governance lineage tracking.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for all monetary amounts in this budget record (e.g., USD). Supports multi-currency reporting for utilities with cross-border operations or international PPAs. Typically USD for domestic U.S. utility operations.. Valid values are `^[A-Z]{3}$`',
    `depreciation_rate_pct` DECIMAL(18,2) COMMENT 'The annual regulatory depreciation rate (as a percentage) applied to CAPEX budget records for utility plant additions. Established by PUC-approved depreciation studies. Used to calculate budgeted depreciation expense for rate case cost-of-service studies and FERC Form 1 reporting. Null for OPEX budget records.',
    `effective_end_date` DATE COMMENT 'The date on which this budget record expires or is superseded (yyyy-MM-dd). For annual budgets, typically the last day of the fiscal year. For multi-year long-range plans, may extend 3–10 years. Nullable for open-ended rolling forecasts.',
    `effective_start_date` DATE COMMENT 'The date from which this budget record becomes effective and spending or revenue targets are active (yyyy-MM-dd). Typically the first day of the fiscal year or the effective date of a mid-year budget revision. Used for temporal budget validity tracking.',
    `energy_type` STRING COMMENT 'Identifies whether this budget record pertains to electric or gas utility operations, or a specific generation fuel type. Required for FERC jurisdictional cost separation between electric and gas operations, and for RPS (Renewable Portfolio Standard) compliance cost tracking.. Valid values are `electric|gas|renewable|nuclear|unallocated`',
    `ferc_account_code` STRING COMMENT 'The FERC Uniform System of Accounts account number (e.g., 401, 500, 101) mapped to this budget record. Required for FERC Form 1 annual report filing and rate case cost-of-service studies. Enables regulatory cost allocation between electric plant, O&M, and revenue accounts.',
    `fiscal_period` STRING COMMENT 'The fiscal period (month number 1–12) within the fiscal year for which this budget amount is recorded. Enables monthly budget-vs-actual variance reporting and period-level financial planning cycles in SAP S/4HANA or Oracle ERP Cloud.',
    `fiscal_year` STRING COMMENT 'The fiscal year to which this budget record applies (e.g., 2025). Used for annual budget cycle management, rate case test year identification, and multi-year capital program planning. Aligns with the utilitys regulatory fiscal year as filed with the PUC and FERC.',
    `functional_area` STRING COMMENT 'The business functional area associated with this budget record (e.g., Generation, Transmission, Electric Distribution, Gas Distribution, Customer Service, Corporate). Used for cost-of-service allocation in rate case studies and FERC jurisdictional separation of costs between electric and gas operations.',
    `notes` STRING COMMENT 'Free-text narrative field for budget analysts to document assumptions, drivers, variance explanations, or special circumstances associated with this budget record. Supports rate case workpaper documentation and SOX audit trail requirements.',
    `owner` STRING COMMENT 'Name or employee identifier of the manager or director responsible for this budget record (e.g., Director of Generation Operations, VP of T&D). Accountable for budget execution, variance explanations, and SOX attestation of financial controls for their cost center.',
    `pbr_target_flag` BOOLEAN COMMENT 'Indicates whether this budget record is associated with a PBR (Performance-Based Ratemaking) performance target or incentive mechanism established by the PUC. True = linked to a PBR metric (e.g., SAIDI, SAIFI, customer satisfaction); False = standard budget record.',
    `period_amount` DECIMAL(18,2) COMMENT 'The budget amount allocated to the specific fiscal period (month) within the fiscal year, in USD. Supports monthly budget-vs-actual variance reporting and cash flow planning. The sum of all period amounts for a fiscal year should equal the approved_amount for annual budget records.',
    `planning_cycle` STRING COMMENT 'Identifies the financial planning cycle that produced this budget record. annual is the primary year-end budget cycle; mid_year_review is the formal mid-year reforecast; quarterly forecasts (q1–q3) are rolling updates; long_range covers multi-year IRP and capital program planning cycles.. Valid values are `annual|mid_year_review|q1_forecast|q2_forecast|q3_forecast|long_range`',
    `prior_year_actual_amount` DECIMAL(18,2) COMMENT 'The actual expenditure or revenue recorded in the prior fiscal year for the same cost center and GL account combination, in USD. Used as a baseline reference for budget development, trend analysis, and rate case historical test year comparisons filed with the PUC.',
    `rate_case_test_year_flag` BOOLEAN COMMENT 'Indicates whether this budget record is designated as part of the rate case test year cost-of-service study submitted to the PUC or FERC. True = this record is included in the test year filing; False = standard budget record not designated for rate case use.',
    `regulatory_jurisdiction` STRING COMMENT 'The regulatory jurisdiction to which this budget record is allocated (e.g., FERC, State PUC name, Unregulated). Used for jurisdictional cost separation in rate case filings, FERC Form 1 reporting, and allocation of shared costs between regulated and unregulated business segments.',
    `source_record_reference` STRING COMMENT 'The natural key or document number from the originating source system (e.g., SAP CO document number, Oracle budget line ID). Used for data lineage, reconciliation between the lakehouse Silver Layer and the ERP source system, and SOX audit trail.',
    `source_system` STRING COMMENT 'Identifies the operational system of record from which this budget record was sourced. Supports data lineage tracking in the Databricks Silver Layer lakehouse. Typical sources include SAP S/4HANA CO-PA, Oracle ERP Cloud Budgetary Control, Hyperion Planning, or Anaplan for financial planning.. Valid values are `sap_s4hana|oracle_erp_cloud|manual_upload|hyperion|anaplan`',
    `updated_timestamp` TIMESTAMP COMMENT 'The timestamp when this budget record was last modified in the source system or Silver Layer lakehouse (yyyy-MM-ddTHH:mm:ss.SSSXXX). Used for incremental ETL processing, change data capture, and SOX audit trail of budget amendments.',
    `variance_threshold_pct` DECIMAL(18,2) COMMENT 'The allowable percentage deviation between budgeted and actual amounts before a budget variance alert or escalation is triggered. Expressed as a percentage (e.g., 10.00 for 10%). Used in monthly budget-vs-actual variance reporting and SOX internal control monitoring.',
    `version` STRING COMMENT 'Identifies the planning iteration of this budget record. original is the board-approved annual budget; revised reflects mid-year amendments; forecast is the rolling latest estimate; long_range_plan covers multi-year capital programs (IRP/CAPEX plans); supplemental covers emergency or regulatory-driven additions.. Valid values are `original|revised|forecast|long_range_plan|supplemental`',
    `wbs_element` STRING COMMENT 'The Work Breakdown Structure element code from SAP Project System (PS) or Oracle ERP Project module, used to track CAPEX budgets at the project or sub-project level. Supports AFUDC (Allowance for Funds Used During Construction) tracking and WIP (Work in Progress) capitalization per FERC accounting rules.',
    CONSTRAINT pk_budget PRIMARY KEY(`budget_id`)
) COMMENT 'Annual and multi-year financial budget record for the utility, organized by cost center, GL account, functional area, and fiscal period. Captures budget version (original, revised, forecast, long-range plan), budget type (OPEX/O&M, CAPEX, revenue), fiscal year, period-level budget amounts, total approved budget amount, variance threshold percentage, budget owner, and approval status. Supports monthly budget-vs-actual variance reporting, financial planning cycles, rate case cost-of-service test year development, PBR (Performance-Based Ratemaking) target-setting, and board-level capital program approval. Each budget record represents a unique combination of version, type, cost center, and GL account for a fiscal year. Sourced from SAP S/4HANA Controlling (CO-PA) or Oracle ERP Cloud Budgetary Control module.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`fixed_asset` (
    `fixed_asset_id` BIGINT COMMENT 'Unique surrogate identifier for the fixed asset record in the financial subledger. Primary key for the fixed_asset data product.',
    `capex_project_id` BIGINT COMMENT 'Foreign key linking to finance.capex_project. Business justification: fixed_asset is capitalized from CAPEX projects. The cwip_transfer_reference and wbs_element attributes suggest a link to the originating project. This FK allows tracing each asset back to its capital ',
    `cost_center_id` BIGINT COMMENT 'Foreign key linking to finance.cost_center. Business justification: fixed_asset has cost_center_code attribute. cost_center is the master for cost centers. Normalizing this reference allows joining to get full cost center details (name, responsible_manager, functional',
    `gl_account_id` BIGINT COMMENT 'Foreign key linking to finance.gl_account. Business justification: fixed_asset has gl_account_code attribute. gl_account is the master for GL accounts. Normalizing this reference allows joining to get full account details (account_name, ferc_account_description, acco',
    `master_id` BIGINT COMMENT 'Cross-reference identifier linking this financial fixed asset record to the corresponding operational asset record in the Enterprise Asset Management (EAM) system (Oracle WAM or IBM Maximo). Enables reconciliation between the financial subledger and the operational asset register for asset lifecycle management and maintenance cost tracking.',
    `vendor_id` BIGINT COMMENT 'Foreign key linking to supply.vendor. Business justification: Fixed assets track original vendor for warranty claims, maintenance contracts, spare parts sourcing, and asset provenance. Essential for asset lifecycle management, vendor performance tracking, and re',
    `accumulated_depreciation` DECIMAL(18,2) COMMENT 'Total depreciation accrued on the asset from in-service date through the current reporting period. Represents the cumulative reduction in the assets book value due to wear, obsolescence, and passage of time. Used to compute net book value and rate base. Denominated in USD. Corresponds to FERC Account 108 (Accumulated Provision for Depreciation of Electric Utility Plant) or equivalent gas accounts.',
    `acquisition_date` DATE COMMENT 'Date on which the utility acquired ownership or control of the asset (purchase date, transfer date, or contribution date). May differ from in-service date for assets acquired from third parties or contributed by developers (CIAC — Contribution in Aid of Construction).',
    `afudc_amount` DECIMAL(18,2) COMMENT 'Total Allowance for Funds Used During Construction (AFUDC) capitalized into the original cost of this asset during the construction period. AFUDC represents the cost of debt and equity capital used to finance construction before the asset is placed in service. Regulated by FERC and included in rate base. Denominated in USD.',
    `annual_depreciation_rate` DECIMAL(18,2) COMMENT 'The composite or straight-line annual depreciation rate applied to this asset or asset group, expressed as a decimal (e.g., 0.033333 for a 30-year life). Derived from the FERC or PUC-approved depreciation study. Used to compute annual depreciation expense for regulatory reporting and rate case cost-of-service studies.',
    `asset_class` STRING COMMENT 'Internal asset classification grouping used for depreciation study purposes and rate case cost-of-service analysis (e.g., Transmission Structure, Distribution Transformer, Gas Meter, Generation Turbine, Intangible Software). Maps to depreciation group/composite rates established in the most recent depreciation study approved by the state PUC or FERC.',
    `asset_description` STRING COMMENT 'Human-readable description of the capitalized utility plant asset (e.g., 138kV Transmission Line Segment — Substation A to Substation B, Gas Distribution Main — 4-inch PE Pipe). Sourced from the asset master record in the ERP fixed asset module.',
    `asset_number` STRING COMMENT 'Externally-known alphanumeric identifier assigned to the capitalized asset in the fixed asset subledger (e.g., SAP S/4HANA Asset Master number or Oracle ERP asset number). Used for cross-system reconciliation between the financial subledger and the operational asset register in Oracle WAM or IBM Maximo.',
    `asset_retirement_obligation` DECIMAL(18,2) COMMENT 'Recorded Asset Retirement Obligation (ARO) associated with this asset, representing the present value of the estimated future cost to retire the asset in accordance with legal or regulatory obligations (e.g., nuclear decommissioning, PCB-contaminated equipment disposal, gas main abandonment). Recognized per GAAP ASC 410-20 and tracked for FERC regulatory accounting. Denominated in USD.',
    `asset_status` STRING COMMENT 'Current lifecycle status of the fixed asset in the utility plant subledger. in_service indicates the asset is placed in service and included in rate base. cwip indicates Construction Work in Progress not yet transferred to plant in service. retired indicates the asset has been removed from service. Aligns with FERC plant account status classifications.. Valid values are `in_service|retired|abandoned|cwip|held_for_future_use|leased_to_others`',
    `asset_type` STRING COMMENT 'Broad classification of the asset as tangible utility plant, intangible plant, or Construction Work in Progress (CWIP). Tangible includes physical generation, transmission, and distribution infrastructure. Intangible includes software, licenses, and franchise rights. CWIP represents assets not yet placed in service.. Valid values are `tangible|intangible|cwip`',
    `capex_category` STRING COMMENT 'Strategic CAPEX category classifying the business driver for the capital investment in this asset. growth supports customer or load growth. reliability improves grid or system reliability (SAIDI/SAIFI improvement). compliance meets regulatory or environmental mandates. replacement replaces end-of-life infrastructure. technology supports grid modernization or AMI deployment. Used in IRP and regulatory filings.. Valid values are `growth|reliability|compliance|replacement|technology`',
    `capitalization_threshold` DECIMAL(18,2) COMMENT 'Minimum dollar threshold applied to determine whether an expenditure on this asset class is capitalized as plant in service or expensed as O&M. Established by the utilitys capitalization policy, approved by the board, and subject to SOX internal controls. Denominated in USD.',
    `ciac_amount` DECIMAL(18,2) COMMENT 'Amount of Contribution in Aid of Construction (CIAC) received from customers, developers, or third parties that offset the original cost of this asset. CIAC reduces the rate base for regulatory purposes. Tracked per FERC Account 271 and applicable state PUC tariff rules. Denominated in USD.',
    `cost_of_removal` DECIMAL(18,2) COMMENT 'Actual or estimated cost incurred to remove the asset from service upon retirement (excavation, demolition, environmental remediation, disposal). Subtracted from gross salvage to determine net salvage. Frequently exceeds gross salvage for underground utility infrastructure, resulting in negative net salvage. Denominated in USD.',
    `cwip_transfer_reference` STRING COMMENT 'Reference number or identifier of the Construction Work in Progress (CWIP) work order or project from which this asset was transferred upon completion and placement in service. Links the capitalized plant record back to the capital project that funded its construction. Corresponds to FERC Account 107 (Construction Work in Progress) transfer transactions.',
    `depreciation_group_code` STRING COMMENT 'Code identifying the depreciation group or composite account to which this asset belongs for group/composite depreciation purposes. Assets within the same depreciation group share a common composite depreciation rate derived from the FERC or PUC-approved depreciation study. Critical for utility industry group depreciation accounting.',
    `depreciation_method` STRING COMMENT 'Accounting method used to calculate periodic depreciation expense for this asset. straight_line allocates cost evenly over useful life. group_composite is the predominant utility industry method where assets are depreciated as a group using composite rates derived from depreciation studies approved by FERC or state PUCs. units_of_production is used for generation assets tied to output.. Valid values are `straight_line|group_composite|units_of_production|sum_of_years_digits`',
    `depreciation_study_year` STRING COMMENT 'The year of the most recent FERC or PUC-approved depreciation study from which the depreciation rates, useful life, and net salvage rate for this asset class were derived. Depreciation studies are typically conducted every 3–5 years and filed with the applicable regulatory authority. Tracks which study vintage governs the current depreciation parameters.',
    `ferc_plant_account` STRING COMMENT 'FERC Uniform System of Accounts plant account code to which this asset is classified (e.g., 101 Electric Plant in Service, 303 Miscellaneous Intangible Plant, 350 Land and Land Rights — Transmission, 376 Distribution Mains — Gas). Drives FERC Form 1 plant schedule reporting (Schedules 204–207) and rate base calculations.',
    `ferc_plant_account_name` STRING COMMENT 'Descriptive name corresponding to the FERC plant account code (e.g., Electric Plant in Service, Distribution Mains — Gas). Supports human-readable reporting on FERC Form 1 plant schedules without requiring a join to a reference table.',
    `functional_class` STRING COMMENT 'FERC functional classification of the utility plant asset: Generation, Transmission, Distribution, General Plant, or Intangible. Drives allocation of rate base and O&M costs across customer classes in rate case cost-of-service studies.. Valid values are `generation|transmission|distribution|general_plant|intangible`',
    `gross_salvage_amount` DECIMAL(18,2) COMMENT 'Actual or estimated gross salvage proceeds received or expected upon retirement of the asset (scrap value, resale proceeds). Used in conjunction with cost of removal to compute net salvage for depreciation study updates. Populated upon retirement; null for in-service assets. Denominated in USD.',
    `in_service_date` DATE COMMENT 'Date on which the asset was placed in service and began depreciating. Triggers the start of depreciation accrual and inclusion in the utility rate base. For CWIP-to-plant transfers, this is the date the CWIP balance is transferred to plant in service. Critical for AFUDC (Allowance for Funds Used During Construction) cessation.',
    `is_rate_base_eligible` BOOLEAN COMMENT 'Indicates whether this asset is eligible for inclusion in the utilitys regulatory rate base for cost-of-service rate case purposes. Assets funded by CIAC, regulatory disallowances, or held for future use may be excluded from rate base. Critical for PUC and FERC rate case filings.',
    `is_regulatory_asset` BOOLEAN COMMENT 'Indicates whether this item is classified as a regulatory asset under GAAP ASC 980 (Regulated Operations), meaning its recovery through future rates is probable. Regulatory assets arise from costs deferred for rate recovery (e.g., storm damage costs, deferred fuel costs, environmental remediation). Affects balance sheet presentation and rate case strategy.',
    `last_physical_inventory_date` DATE COMMENT 'Date of the most recent physical inventory verification confirming the existence and condition of this asset. Physical inventories are required for SOX compliance (internal controls over financial reporting) and support reconciliation between the fixed asset subledger and the operational asset register in Oracle WAM or IBM Maximo.',
    `location_code` STRING COMMENT 'Code identifying the physical or operational location of the asset within the utilitys service territory (e.g., substation identifier, distribution circuit code, gas pressure zone, plant site code). Used for geographic cost allocation in rate cases and for reconciliation with the GIS (ESRI ArcGIS) asset network model.',
    `net_book_value` DECIMAL(18,2) COMMENT 'Current net book value of the asset, calculated as original cost minus accumulated depreciation. Represents the carrying value of the asset on the utilitys balance sheet and is the primary basis for rate base inclusion in cost-of-service rate cases. Denominated in USD. Note: while derivable, this field is stored for performance and regulatory reporting efficiency.',
    `net_salvage_rate` DECIMAL(18,2) COMMENT 'The net salvage rate applied to this asset class in the depreciation study, expressed as a decimal. Net salvage equals gross salvage proceeds minus cost of removal. For utility assets, net salvage is frequently negative (negative salvage) because cost of removal (e.g., pole removal, underground cable excavation, gas main abandonment) exceeds any scrap value. Negative salvage rates increase the depreciable base and are a critical input unique to utility depreciation studies.',
    `original_cost` DECIMAL(18,2) COMMENT 'The original cost of the utility plant asset at the time it was first dedicated to public service, as defined by FERC Uniform System of Accounts. Includes all costs necessary to bring the asset to its intended use (materials, labor, AFUDC, overhead). This is the FERC-defined original cost, not necessarily the acquisition cost paid by the current owner. Denominated in USD.',
    `record_created_timestamp` TIMESTAMP COMMENT 'Timestamp when this fixed asset record was first created in the financial subledger system (SAP S/4HANA or Oracle ERP Cloud). Supports SOX audit trail requirements and data lineage tracking in the Databricks Silver Layer.',
    `record_updated_timestamp` TIMESTAMP COMMENT 'Timestamp when this fixed asset record was most recently modified in the financial subledger system. Tracks changes to depreciation parameters, status updates, retirement entries, and cost adjustments. Supports SOX audit trail and Silver Layer change data capture (CDC) processing.',
    `remaining_useful_life_years` DECIMAL(18,2) COMMENT 'Estimated remaining useful service life of the asset in years as of the most recent depreciation study or valuation date. Computed as useful life minus age (years since in-service date), adjusted for condition assessments. Used in rate case depreciation studies, IRP capital planning, and asset replacement forecasting.',
    `retirement_date` DATE COMMENT 'Date on which the asset was retired, abandoned, or removed from utility plant in service. Triggers cessation of depreciation accrual and removal from rate base. Null for assets currently in service. Required for FERC Form 1 plant retirement schedules.',
    `retirement_type` STRING COMMENT 'Classification of the asset retirement event. normal retirements are expected end-of-life removals consistent with the depreciation study survivor curve. abnormal retirements are premature removals due to accidents, storms, or regulatory mandates. extraordinary retirements involve large-scale plant abandonments. Classification affects regulatory accounting treatment and potential regulatory asset recovery.. Valid values are `normal|abnormal|extraordinary|sale|transfer`',
    `service_territory` STRING COMMENT 'Name or code of the regulatory service territory or jurisdiction in which the asset is located (e.g., state name, PUC jurisdiction code). Determines which state Public Utility Commission (PUC) has regulatory jurisdiction over the assets rate base treatment and depreciation rates.',
    `useful_life_years` DECIMAL(18,2) COMMENT 'Estimated useful service life of the asset in years, as established in the most recent FERC or PUC-approved depreciation study. Used to compute straight-line depreciation rates and to project future capital replacement needs in the Integrated Resource Plan (IRP). Decimal precision accommodates fractional lives from group/composite depreciation studies.',
    `utility_type` STRING COMMENT 'Identifies whether the asset belongs to the electric utility plant, gas utility plant, common plant (shared between electric and gas), or other. Critical for cost-of-service allocation studies in rate cases filed with state PUCs and FERC.. Valid values are `electric|gas|common|other`',
    `vintage_year` STRING COMMENT 'The year in which the asset was originally constructed or manufactured. Critical input for group/composite depreciation studies unique to the utility industry, where survivor curve analysis and Iowa Curve fitting require age distribution data by vintage year. Used in FERC-approved depreciation studies and PUC rate case filings.',
    `wbs_element` STRING COMMENT 'Work Breakdown Structure (WBS) element or capital project code from the ERP system associated with the construction or acquisition of this asset. Links the capitalized asset to the CAPEX project that funded it, supporting capital budget tracking and AFUDC calculation. Relevant for assets still in CWIP or recently transferred to plant in service.',
    CONSTRAINT pk_fixed_asset PRIMARY KEY(`fixed_asset_id`)
) COMMENT 'Master record for capitalized utility plant assets tracked in the fixed asset subledger, aligned to FERC Uniform System of Accounts plant accounts. Captures asset number, asset description, FERC plant account (e.g., 101 Electric Plant in Service, 303 Miscellaneous Intangible Plant, 376 Distribution Mains — Gas), asset class, vintage year, acquisition date, in-service date, original cost, accumulated depreciation, net book value, depreciation method (straight-line, group/composite), useful life, net salvage rate (including negative salvage/cost of removal), retirement date, retirement type (normal, abnormal, extraordinary), asset location, and CWIP-to-plant transfer reference. Serves as the financial SSOT for utility plant valuation, depreciation studies, rate base calculations, and FERC Form 1 plant schedules (Schedules 204-207). Complements the operational asset record in the asset domain. Vintage year and net salvage rate are critical for group/composite depreciation studies unique to the utility industry.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`depreciation_run` (
    `depreciation_run_id` BIGINT COMMENT 'Unique surrogate identifier for each depreciation calculation run executed against the fixed asset subledger. Primary key for this record.',
    `cost_center_id` BIGINT COMMENT 'Foreign key linking to finance.cost_center. Business justification: depreciation_run has cost_center_code attribute. cost_center is the master for cost centers. Normalizing this reference allows joining to get full cost center details (name, responsible_manager, funct',
    `depreciation_study_id` BIGINT COMMENT 'Reference identifier for the PUC-approved depreciation study whose rates were applied in this run. Links the run to the authoritative rate study (interim or final) that established the depreciation rates, supporting depreciation study true-up analysis and rate case cost-of-service documentation.',
    `financial_period_id` BIGINT COMMENT 'Foreign key linking to finance.financial_period. Business justification: depreciation_run has fiscal_year and fiscal_period attributes. financial_period is the master for fiscal periods. Normalizing this reference allows joining to get full period metadata (period dates, s',
    `gl_account_id` BIGINT COMMENT 'Foreign key linking to finance.gl_account. Business justification: depreciation_run has gl_account_code attribute. gl_account is the master for GL accounts. Normalizing this reference allows joining to get full account details (account_name, ferc_account_description,',
    `accumulated_depreciation_amount` DECIMAL(18,2) COMMENT 'Total accumulated depreciation balance (in USD) for the assets processed in this run as of the end of the fiscal period, across the specified depreciation area. Represents the cumulative depreciation charged against the gross plant-in-service balance. Used in FERC Form 1 Schedule 336 and rate base calculations for rate cases.',
    `approval_timestamp` TIMESTAMP COMMENT 'Timestamp when the depreciation run was approved for posting by the authorized finance approver. Part of the SOX audit trail for the depreciation posting lifecycle.',
    `approved_by` STRING COMMENT 'User ID or name of the finance manager or controller who approved the depreciation run for posting. Supports SOX segregation of duties controls requiring that the person who initiates a depreciation run is different from the person who approves it.',
    `asset_class_code` STRING COMMENT 'FERC or ERP asset class code identifying the category of fixed assets included in this depreciation run (e.g., 301 = Organization, 303 = Miscellaneous Intangible Plant, 350 = Land and Land Rights, 353 = Station Equipment, 362 = Meters, 391 = Office Furniture). Aligns with FERC Uniform System of Accounts plant account codes. If the run covers all asset classes, this field is null.',
    `assets_errored_count` STRING COMMENT 'Number of fixed asset records that encountered errors and were excluded from depreciation calculation during this run. A non-zero value requires investigation and potential rerun. Supports SOX completeness controls over the depreciation process.',
    `assets_processed_count` STRING COMMENT 'Total number of fixed asset records processed during this depreciation run. Used for run completeness validation, reconciliation against the fixed asset register count, and identifying partial runs or processing errors.',
    `company_code` STRING COMMENT 'SAP company code or ERP legal entity identifier representing the regulated utility entity (e.g., electric operating company, gas distribution company) for which the depreciation run was executed. Supports multi-entity utility holding company structures and separate FERC/PUC regulatory reporting by legal entity.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this depreciation run record was first captured in the data platform. Used for audit trail and SOX compliance over the depreciation posting process.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for the depreciation amounts in this run (e.g., USD). Supports multi-currency reporting for utility holding companies with international operations.. Valid values are `[A-Z]{3}`',
    `depreciation_area_code` STRING COMMENT 'Code identifying the depreciation valuation area for which this run was executed. Common utility depreciation areas: 01 = Book/GAAP, 10 = Federal Tax (MACRS), 15 = State Tax, 20 = Regulatory/FERC, 30 = Alternative Minimum Tax (AMT), 40 = Group/Composite. Each area maintains independent depreciation values per SAP FI-AA configuration. [ENUM-REF-CANDIDATE: 01|10|15|20|30|40 — promote to reference product]. Valid values are `01|10|15|20|30|40`',
    `depreciation_area_name` STRING COMMENT 'Human-readable name of the depreciation area (e.g., Book/GAAP, Federal Tax MACRS, State Tax, Regulatory/FERC, Alternative Minimum Tax, Group/Composite). Supports reporting and audit trail readability without requiring a join to a reference table.',
    `depreciation_method_code` STRING COMMENT 'Code identifying the depreciation calculation method applied during this run. SL = Straight-Line (primary GAAP method for utilities); GRP = Group/Composite (common for utility plant accounts per FERC); SYD = Sum-of-Years-Digits; DB = Declining Balance; UOP = Units-of-Production. Determines the mathematical basis for depreciation expense calculation.. Valid values are `SL|GRP|SYD|DB|UOP`',
    `depreciation_method_name` STRING COMMENT 'Full descriptive name of the depreciation method applied (e.g., Straight-Line, Group/Composite, Sum-of-Years-Digits, Declining Balance, Units-of-Production). Supports FERC Form 1 Schedule 336 reporting and rate case cost-of-service documentation.',
    `depreciation_rate` DECIMAL(18,2) COMMENT 'The composite or average depreciation rate (expressed as a decimal, e.g., 0.033333 for 3.3333%) applied during this run. For group/composite depreciation, this is the PUC-approved composite rate from the most recent depreciation study. For straight-line, this is the reciprocal of the average service life. Key parameter for depreciation study true-up analysis.',
    `depreciation_rate_type` STRING COMMENT 'Indicates whether the depreciation rates applied in this run are interim rates (provisionally approved by the PUC pending final order), final rates (approved in a final PUC order), proposed rates (filed but not yet approved), or approved rates (in effect under current tariff). Critical for regulatory accounting and rate case true-up calculations.. Valid values are `interim|final|proposed|approved`',
    `error_message` STRING COMMENT 'System-generated error message text when run_status = error. Captures the ERP error description to support troubleshooting and resolution of failed depreciation runs. Null when the run completed successfully.',
    `ferc_plant_account` STRING COMMENT 'FERC Uniform System of Accounts plant account number to which the depreciation expense from this run is attributed (e.g., 403 = Depreciation Expense — Electric, 404 = Amortization of Limited-Term Electric Plant). Required for FERC Form 1 Schedule 336 depreciation and amortization reporting.',
    `fiscal_period` STRING COMMENT 'The accounting period (1–12 for monthly, or 1–4 for quarterly) within the fiscal year to which this depreciation run applies. Determines the general ledger period into which depreciation expense is posted.',
    `fiscal_year` STRING COMMENT 'The fiscal year (four-digit integer, e.g., 2024) to which this depreciation run applies. Aligns with the utilitys GAAP and FERC regulatory accounting fiscal year for financial statement preparation and FERC Form 1 reporting.',
    `gross_plant_amount` DECIMAL(18,2) COMMENT 'Total gross plant-in-service value (in USD) of the assets processed in this depreciation run as of the run date. Represents the depreciable asset base. Used to validate the depreciation rate applied (total_depreciation_amount / gross_plant_amount) and supports rate base calculations in rate case cost-of-service studies.',
    `is_repeat_run` BOOLEAN COMMENT 'Indicates whether this run is a repeat execution for a period that was previously processed (True) or a first-time run for the period (False). Repeat runs occur after reversals or corrections. Relevant for SOX controls over duplicate depreciation postings.',
    `is_simulation` BOOLEAN COMMENT 'Indicates whether this depreciation run was executed in simulation (test) mode without posting to the general ledger (True) or as a live posting run (False). Simulation runs are used to preview depreciation amounts before period-end close.',
    `notes` STRING COMMENT 'Free-text notes entered by the run initiator or approver describing the purpose, scope, or any exceptions associated with this depreciation run (e.g., Year-end true-up run applying final PUC-approved rates from Docket 2024-001, Repeat run after reversal of period 6 posting error).',
    `planned_depreciation_amount` DECIMAL(18,2) COMMENT 'The budgeted or planned depreciation amount for this fiscal period and depreciation area, as established in the depreciation study or annual budget. Compared against total_depreciation_amount to identify variances for depreciation study true-up analysis and rate case cost-of-service reconciliation.',
    `posting_date` DATE COMMENT 'The date on which the depreciation amounts were posted to the general ledger. May differ from run_date if the run was simulated first and posted later. Critical for period-end close cutoff and GAAP accrual accounting.',
    `posting_document_number` STRING COMMENT 'ERP financial document number (e.g., SAP FI document number) generated when depreciation amounts are posted to the general ledger. Provides the audit trail linkage between the depreciation run and the actual GL posting for SOX compliance and external audit support.',
    `reversal_date` DATE COMMENT 'The date on which the depreciation run posting was reversed in the general ledger. Null if not reversed. Used in conjunction with reversal_document_number to track corrected depreciation entries.',
    `reversal_document_number` STRING COMMENT 'ERP financial document number of the reversal posting if this depreciation run was reversed. Null if the run has not been reversed. Supports audit trail for corrected depreciation postings and SOX compliance.',
    `run_date` DATE COMMENT 'The calendar date on which the depreciation calculation run was executed. This is the principal business event date — the date the depreciation program was triggered in the asset accounting system.',
    `run_end_timestamp` TIMESTAMP COMMENT 'Timestamp when the depreciation calculation program completed execution. Used with run_start_timestamp to measure total processing duration for operational monitoring of the period-end close process.',
    `run_initiator` STRING COMMENT 'User ID or system account that initiated the depreciation run in the ERP system. Required for SOX audit trail to establish accountability over the depreciation posting process and segregation of duties compliance.',
    `run_number` STRING COMMENT 'Externally-known business identifier assigned to the depreciation run by the ERP system (e.g., SAP S/4HANA depreciation run document number). Used for cross-system reconciliation and audit trail reference.',
    `run_start_timestamp` TIMESTAMP COMMENT 'Timestamp when the depreciation calculation program began execution in the ERP system. Used with run_end_timestamp to measure processing duration and identify performance issues with large asset portfolios.',
    `run_status` STRING COMMENT 'Current lifecycle state of the depreciation run. planned indicates scheduled but not yet executed; simulated indicates a test run without posting; posted indicates amounts have been committed to the general ledger; reversed indicates the posting has been reversed; error indicates the run failed during processing.. Valid values are `planned|simulated|posted|reversed|error`',
    `run_type` STRING COMMENT 'Classification of the depreciation run by its business purpose. periodic = standard monthly/quarterly run; year_end = annual closing run; special = off-cycle run for asset disposals or acquisitions; repeat = rerun of a previously executed period.. Valid values are `periodic|year_end|special|repeat`',
    `source_system_code` STRING COMMENT 'Code identifying the operational system of record from which this depreciation run record was sourced (e.g., SAP_S4, ORACLE_ERP). Supports data lineage tracking in the Databricks lakehouse silver layer.',
    `total_depreciation_amount` DECIMAL(18,2) COMMENT 'Total depreciation expense amount (in USD) calculated and posted during this run across all assets processed. This is the gross depreciation charge for the period and depreciation area. Key input for rate case cost-of-service calculations, FERC Form 1 Schedule 336 reporting, and GAAP income statement depreciation expense line.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp when this depreciation run record was last modified in the data platform. Tracks status changes such as reversal or error correction for SOX audit trail.',
    CONSTRAINT pk_depreciation_run PRIMARY KEY(`depreciation_run_id`)
) COMMENT 'Transactional record of periodic depreciation calculation runs executed against the fixed asset subledger. Captures run date, fiscal period, fiscal year, depreciation area (book/GAAP, federal tax, state tax, regulatory/FERC, AMT, group/composite), total depreciation amount posted, number of assets processed, run status (planned, simulated, posted, reversed), posting document reference, run initiator, and depreciation method applied (straight-line, group/composite, sum-of-years-digits, declining balance, units-of-production). Supports GAAP straight-line and group/composite depreciation methods commonly used by utilities, regulatory depreciation per PUC-approved depreciation study rates (including interim and final rates), tax depreciation (MACRS with bonus depreciation), and FERC Form 1 depreciation reporting (Schedule 336 — Depreciation and Amortization of Electric Plant). Enables audit trail for SOX compliance over the depreciation posting process, supports depreciation study true-up analysis, and provides the depreciation expense input for rate case cost-of-service calculations.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`opex_transaction` (
    `opex_transaction_id` BIGINT COMMENT 'Unique surrogate identifier for each operating expenditure transaction record in the general ledger. Primary key for the opex_transaction data product. Entity role: TRANSACTION_HEADER.',
    `cost_center_id` BIGINT COMMENT 'Reference to the organizational cost center to which this OPEX transaction is charged. Cost centers align with functional areas such as generation, transmission, distribution, or gas operations. Used for departmental O&M budget tracking and rate case cost allocation.',
    `financial_period_id` BIGINT COMMENT 'Foreign key linking to finance.financial_period. Business justification: opex_transaction has fiscal_year and fiscal_period attributes. financial_period is the master for fiscal periods. Normalizing this reference allows joining to get full period metadata. fiscal_year and',
    `gl_account_id` BIGINT COMMENT 'Foreign key linking to finance.gl_account. Business justification: opex_transaction has gl_account_code attribute. gl_account is the master for GL accounts. Normalizing this reference allows joining to get full account details (account_name, ferc_account_description,',
    `master_id` BIGINT COMMENT 'Reference to the utility asset (generation unit, transmission line, distribution equipment, or gas pipeline segment) for which this O&M expenditure was incurred. Links to the asset master in Oracle WAM or IBM Maximo. Critical for distinguishing maintenance OPEX from capital improvements (CAPEX) and for asset-level cost tracking.',
    `purchase_order_id` BIGINT COMMENT 'Reference to the purchase order associated with this OPEX transaction for contractor services, materials, or fuel procurement. Links to the procurement module in SAP S/4HANA or Oracle ERP Cloud. Supports three-way match (PO, goods receipt, invoice) for SOX procure-to-pay controls.',
    `vendor_id` BIGINT COMMENT 'Reference to the vendor or supplier associated with this OPEX transaction, applicable for contractor services, materials procurement, and fuel purchases. Links to the vendor master in the ERP system (SAP S/4HANA or Oracle ERP Cloud). Serves as the PARTY_REFERENCE for external counterparty transactions.',
    `work_order_id` BIGINT COMMENT 'Reference to the maintenance or construction work order (from Oracle WAM or IBM Maximo) that generated this OPEX transaction. Enables linkage between O&M labor and materials costs and specific asset maintenance activities. Critical for distinguishing OPEX from CAPEX in rate case filings.',
    `approval_status` STRING COMMENT 'Current workflow lifecycle state of the OPEX transaction. Tracks the transaction from initial entry through approval, posting to the general ledger, and potential reversal. Essential for SOX internal controls compliance and financial close processes.. Valid values are `draft|pending_approval|approved|rejected|posted|reversed`',
    `approved_by` STRING COMMENT 'Name or employee identifier of the individual who approved this OPEX transaction per the utilitys delegation of authority matrix. Required for SOX internal controls documentation and financial audit trails. Populated upon transition to approved or posted approval_status.',
    `approved_timestamp` TIMESTAMP COMMENT 'Timestamp when the OPEX transaction received final approval in the ERP workflow. Distinct from created_timestamp and updated_timestamp; captures the specific lifecycle event of approval. Used for SOX controls testing and financial close cycle time analysis.',
    `budget_amount` DECIMAL(18,2) COMMENT 'Approved O&M budget amount for the cost center and FERC account combination for the applicable fiscal period. Enables budget-to-actual variance analysis at the transaction level. Supports financial planning and rate case test-year budget justification.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the OPEX transaction record was first created in the source ERP system (SAP S/4HANA or Oracle ERP Cloud). Used for audit trail, SOX compliance, and data lineage tracking in the Silver layer.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for the transaction amount (e.g., USD). Required for multi-currency ERP environments and FERC financial reporting. Utility operations are predominantly USD but may include CAD for cross-border transmission operations.. Valid values are `^[A-Z]{3}$`',
    `employee_code` BIGINT COMMENT 'Reference to the employee associated with this OPEX transaction, applicable for labor cost postings (direct labor, overtime, benefits allocations) originating from the payroll system (SuccessFactors or Workday). Null for non-labor transactions such as vendor invoices or fuel purchases.',
    `expense_category` STRING COMMENT 'High-level classification of the operating expenditure type. Categories align with standard O&M cost-of-service study breakdowns used in rate case filings before state Public Utility Commissions (PUCs) and FERC. Labor includes direct and indirect employee costs; contractor_services covers third-party O&M contracts; fuel covers FAC-eligible fuel costs.. Valid values are `labor|materials|contractor_services|fuel|overhead_allocation|other`',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts account number to which this O&M expense is classified. Electric O&M accounts include the 500-series (Electric Operation) and 500-599 range; Gas O&M accounts include the 800-series (Gas Operation). Directly drives FERC Form 1 (electric) and FERC Form 2 (gas) O&M expense schedule reporting.',
    `ferc_account_description` STRING COMMENT 'Descriptive label for the FERC Uniform System of Accounts account code (e.g., Account 501 - Fuel, Account 510 - Steam Power Generation Operation, Account 803 - Natural Gas Purchased for Resale). Provides human-readable context for financial reporting and rate case cost-of-service studies.',
    `fiscal_period` STRING COMMENT 'The fiscal accounting period (1–12 for monthly, or 1–4 for quarterly) within the fiscal year in which this OPEX transaction is recognized. Used for period-end close, monthly O&M variance reporting, and regulatory test-year normalization.',
    `fiscal_year` STRING COMMENT 'The fiscal year (four-digit integer, e.g., 2024) in which this OPEX transaction is recognized for financial reporting purposes. Aligns with the utilitys regulatory fiscal year used in FERC Form 1/2 annual reports and rate case test-year filings.',
    `functional_area` STRING COMMENT 'Utility functional area to which this OPEX transaction is attributed, aligned with FERC Uniform System of Accounts functional classifications. Used to allocate O&M costs between electric and gas operations and between generation, transmission, and distribution for rate case cost-of-service studies and FERC Form 1/2 reporting.. Valid values are `electric_generation|electric_transmission|electric_distribution|gas_distribution|customer_service|administrative_general`',
    `is_capex_reclassified` BOOLEAN COMMENT 'Indicates whether this transaction was initially posted as OPEX but subsequently reclassified as a capital expenditure (CAPEX) following engineering or accounting review. OPEX-to-CAPEX reclassifications are common in utility accounting and are subject to regulatory scrutiny in rate cases.',
    `is_fac_eligible` BOOLEAN COMMENT 'Indicates whether this OPEX transaction represents a fuel cost eligible for recovery through the Fuel Adjustment Clause (FAC) mechanism. FAC-eligible costs (e.g., natural gas, coal, nuclear fuel purchases) are tracked separately for regulatory pass-through rate adjustments filed with state PUCs.',
    `is_rate_case_includable` BOOLEAN COMMENT 'Indicates whether this OPEX transaction is includable in the utilitys rate case cost-of-service study as a recoverable O&M expense. Transactions flagged as non-includable (e.g., lobbying costs, penalties, shareholder expenses) are excluded from the revenue requirement calculation per PUC and FERC guidelines.',
    `net_amount` DECIMAL(18,2) COMMENT 'Net total amount of the OPEX transaction after applying overhead allocations, adjustments, and any credits or reversals. Represents the final O&M cost recognized in the general ledger for this transaction. Used as the basis for FERC Form 1/2 O&M expense schedule line items.',
    `original_transaction_number` STRING COMMENT 'For reversal or correcting entries, the transaction_number of the original OPEX transaction being reversed or corrected. Enables audit trail linkage between original postings and their reversals. Null for original (non-reversal) transactions.',
    `overhead_allocation_amount` DECIMAL(18,2) COMMENT 'Dollar amount of indirect overhead costs allocated to this OPEX transaction using the utilitys cost allocation methodology (e.g., labor-hour basis, direct-cost basis). Overhead allocations are scrutinized in rate case cost-of-service studies to ensure only appropriate costs are included in revenue requirement calculations.',
    `posting_date` DATE COMMENT 'The date on which the OPEX transaction was posted to the general ledger accounting period. May differ from transaction_date due to accrual adjustments or late postings. Determines the fiscal period for financial statement inclusion.',
    `project_code` STRING COMMENT 'Internal project or WBS (Work Breakdown Structure) code from the ERP system to which this OPEX transaction is charged. Used for project-level O&M cost tracking, particularly for multi-year maintenance programs, storm restoration activities, and demand-side management (DSM) program cost tracking.',
    `quantity` DECIMAL(18,2) COMMENT 'The quantity of goods, services, or resources consumed in this OPEX transaction (e.g., labor hours, MCF of natural gas, MWh of fuel energy, units of materials). Used in conjunction with unit_of_measure for unit cost analysis and fuel consumption tracking for FAC filings.',
    `regulatory_jurisdiction` STRING COMMENT 'The regulatory jurisdiction (e.g., FERC, CA-CPUC, TX-PUC, NY-PSC) under whose rate-making authority this OPEX transaction falls. Used to allocate costs between FERC-jurisdictional (wholesale/transmission) and state PUC-jurisdictional (retail distribution) rate bases in cost-of-service studies.',
    `reversal_indicator` BOOLEAN COMMENT 'Indicates whether this OPEX transaction is a reversal entry (credit memo or correcting journal entry) that offsets a previously posted transaction. Reversal transactions are common for accrual reversals at period-end and for correcting misposted O&M costs.',
    `source_document_type` STRING COMMENT 'Classification of the originating document type that generated this OPEX transaction in the ERP system. Distinguishes between vendor invoices, manual journal entries, period-end accruals, payroll cost allocations, intercompany charges, and goods receipts. Used for financial audit and SOX controls testing.. Valid values are `vendor_invoice|journal_entry|accrual|payroll_allocation|intercompany|goods_receipt`',
    `source_system` STRING COMMENT 'Identifies the operational system of record from which this OPEX transaction originated. Supports data lineage tracking in the Databricks Silver layer and enables source-system reconciliation during financial close. Primary sources are SAP S/4HANA or Oracle ERP Cloud for financial postings, with work order costs originating from Oracle WAM or IBM Maximo.. Valid values are `SAP_S4HANA|Oracle_ERP_Cloud|Oracle_WAM|IBM_Maximo|manual_entry`',
    `transaction_amount` DECIMAL(18,2) COMMENT 'Gross base amount of the operating expenditure in the transaction currency before any adjustments, discounts, or overhead allocations. Represents the raw O&M cost posted to the general ledger. Used for OPEX budget variance analysis and FERC O&M expense reporting.',
    `transaction_date` DATE COMMENT 'The principal real-world business event date on which the operating expenditure was incurred or the cost was recognized. Used for period-end accruals, FERC O&M expense reporting, and rate case cost-of-service study period alignment.',
    `transaction_description` STRING COMMENT 'Free-text description of the operating expenditure as entered in the ERP system (SAP S/4HANA or Oracle ERP Cloud). Provides context for the nature of the O&M cost, such as Turbine blade inspection labor - Unit 3 or Natural gas fuel purchase - Peaker Plant. Used in audit reviews and rate case cost justification.',
    `transaction_number` STRING COMMENT 'Externally-known business identifier for the OPEX transaction as assigned by the ERP system (SAP S/4HANA or Oracle ERP Cloud). Corresponds to the document number or journal entry number used in financial reporting and audit trails. Supports FERC Form 1/2 O&M expense reconciliation.',
    `unit_of_measure` STRING COMMENT 'The unit of measure for the quantity field (e.g., hours for labor, MCF for natural gas volume, MWh for fuel energy, EA for each/unit of materials). Enables unit cost calculations and fuel consumption analysis for Fuel Adjustment Clause (FAC) regulatory filings.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp when the OPEX transaction record was last modified in the source ERP system. Tracks reversals, corrections, and approval workflow updates. Required for incremental ETL processing in the Databricks Silver layer.',
    `utility_type` STRING COMMENT 'Identifies whether this OPEX transaction relates to electric utility operations, gas utility operations, or common/shared utility costs. Required for cost separation between electric and gas rate bases in combined electric-and-gas utility rate cases filed with state PUCs and FERC.. Valid values are `electric|gas|common`',
    `vendor_invoice_number` STRING COMMENT 'The invoice number provided by the vendor or contractor for this OPEX transaction. Used for three-way match (PO, goods receipt, invoice) in the procure-to-pay process and for SOX accounts payable controls. Enables traceability from the general ledger entry back to the source vendor document.',
    CONSTRAINT pk_opex_transaction PRIMARY KEY(`opex_transaction_id`)
) COMMENT 'Transactional record capturing operating expenditures (O&M costs) posted to the general ledger, including labor, materials, contractor services, fuel costs (FAC-eligible), and overhead allocations. Captures transaction date, amount, FERC O&M account (e.g., Account 500-series for Electric Operation, Account 800-series for Gas Operation), cost center, functional area, expense category, purchase order reference, vendor, and approval status. Supports OPEX tracking against budget, rate case O&M cost-of-service studies, and FERC Form 1/2 O&M expense reporting.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`profit_center` (
    `profit_center_id` BIGINT COMMENT 'Unique surrogate identifier for the profit center record in the Databricks Silver Layer. Primary key generated by the lakehouse ingestion pipeline from SAP S/4HANA CO-PCA module.',
    `parent_profit_center_id` BIGINT COMMENT 'Self-referencing FK on profit_center (parent_profit_center_id)',
    `allowed_roe_percent` DECIMAL(18,2) COMMENT 'Regulatory-approved return on equity percentage for this profit center as determined in the most recent rate case or FERC order. Used to calculate the allowed return component in cost-of-service studies and PBR performance tracking.',
    `business_segment` STRING COMMENT 'Regulatory and operational business segment to which this profit center belongs. Drives FERC-required segment reporting and ROE/ROI analysis by business unit. Values align with the utilitys FERC Form 1 and state PUC segment reporting requirements: electric_generation, electric_transmission, electric_distribution, gas_distribution, unregulated.. Valid values are `electric_generation|electric_transmission|electric_distribution|gas_distribution|unregulated`',
    `capex_budget_usd` DECIMAL(18,2) COMMENT 'Approved annual capital expenditure budget allocated to this profit center in US dollars. Used for CAPEX tracking, rate base calculations, and AFUDC (Allowance for Funds Used During Construction) accruals in regulatory accounting.',
    `ciac_eligible` BOOLEAN COMMENT 'Indicates whether this profit center is eligible to receive Contributions in Aid of Construction (CIAC) from customers or developers. CIAC receipts reduce rate base and are tracked separately per FERC Account 271 and state PUC requirements.',
    `company_code` STRING COMMENT 'SAP Company Code (BUKRS) representing the legal entity to which this profit center is assigned. Used for GAAP financial statement preparation and SOX compliance segregation. Maps to the utilitys legal corporate structure.. Valid values are `^[A-Z0-9]{1,4}$`',
    `controlling_area_code` STRING COMMENT 'SAP Controlling Area (KOKRS) to which this profit center belongs. Defines the organizational unit within which cost and profit accounting is performed. All profit centers within a controlling area share the same fiscal year variant and currency.. Valid values are `^[A-Z0-9]{1,4}$`',
    `cost_center_assignment` STRING COMMENT 'Default cost center code associated with this profit center for overhead allocation and cost-of-service studies. Used in rate case preparation to allocate shared costs between regulated business segments per FERC and PUC requirements.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this profit center record was first created in the source SAP S/4HANA CO-PCA system. Used for audit trail, SOX compliance, and data lineage tracking in the Databricks Silver Layer.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for the profit centers reporting currency (e.g., USD). Defines the currency in which profit center financial results are reported and consolidated.. Valid values are `^[A-Z]{3}$`',
    `depreciation_method` STRING COMMENT 'Depreciation method applied to capital assets assigned to this profit center. Regulatory depreciation rates are typically set by PUC order and may differ from GAAP depreciation. Impacts rate base calculations and FERC account 403 (Depreciation and Amortization of Electric Plant).. Valid values are `straight_line|accelerated|units_of_production|regulatory`',
    `energy_commodity` STRING COMMENT 'Primary energy commodity handled by this profit center. Distinguishes electric utility operations from gas distribution operations for FERC Form 1 vs. Form 2 reporting, and for separate rate case cost-of-service studies.. Valid values are `electric|gas|both|none`',
    `ferc_account_class` STRING COMMENT 'FERC Uniform System of Accounts classification associated with this profit center (e.g., Electric Plant in Service accounts 301-399, Gas Plant accounts 101-199). Drives regulatory financial reporting on FERC Form 1 and Form 2.',
    `fiscal_year_variant` STRING COMMENT 'SAP Fiscal Year Variant (PERIV) that defines the fiscal year calendar applicable to this profit center. Determines period boundaries for financial reporting, budget cycles, and FERC annual report preparation.. Valid values are `^[A-Z0-9]{2}$`',
    `functional_area` STRING COMMENT 'SAP Functional Area (FUNC_AREA) assigned to this profit center, used to classify costs by business function (e.g., generation operations, transmission operations, distribution operations, customer service, administration). Supports FERC functional cost classification and CAPEX/OPEX segregation.',
    `gl_account_assignment_group` STRING COMMENT 'GL account assignment group that governs automatic account determination for revenue and cost postings to this profit center. Ensures correct FERC account mapping for regulated utility accounting.',
    `hierarchy_node` STRING COMMENT 'Node identifier within the SAP profit center standard hierarchy (SETCLASS 0106) to which this profit center is assigned. Enables roll-up reporting across organizational levels for EBITDA and segment reporting.',
    `intercompany_elimination_flag` BOOLEAN COMMENT 'Indicates whether transactions posted to this profit center are subject to intercompany elimination in consolidated financial statements. Critical for SOX-compliant consolidation and FERC affiliate transaction reporting.',
    `last_modified_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent modification to this profit center record in the source SAP S/4HANA CO-PCA system. Supports change tracking, SOX audit requirements, and incremental data pipeline processing.',
    `long_description` STRING COMMENT 'Extended description of the profit center providing full business context, including the scope of operations, regulatory segment, and reporting purpose. Corresponds to LTEXT in SAP CEPC.',
    `nerc_region` STRING COMMENT 'NERC reliability region (e.g., WECC, SERC, RFC, MRO) associated with this profit centers electric operations. Used for NERC compliance reporting and bulk electric system (BES) reliability cost allocation.',
    `opex_budget_usd` DECIMAL(18,2) COMMENT 'Approved annual operating expenditure budget allocated to this profit center in US dollars. Supports O&M cost tracking, rate case cost-of-service studies, and EBITDA reporting by segment.',
    `plant_location_code` STRING COMMENT 'Geographic or operational location code associated with this profit center, linking it to a specific generation plant, transmission substation, distribution district, or gas service territory. Used in GIS-integrated financial analysis and asset management reporting.',
    `profit_center_code` STRING COMMENT 'Externally-known alphanumeric code that uniquely identifies the profit center within the SAP S/4HANA Controlling (CO-PCA) module. Used in journal entries, cost allocations, and regulatory segment reports. Corresponds to the PRCTR field in SAP table CEPC.. Valid values are `^[A-Z0-9_-]{1,20}$`',
    `profit_center_group` STRING COMMENT 'Grouping identifier used to aggregate profit centers for management reporting, EBITDA analysis, and regulatory segment reporting. Corresponds to SAP profit center groups (SETCLASS 0106) used in report painter/writer reports.',
    `profit_center_name` STRING COMMENT 'Human-readable short name of the profit center as maintained in SAP CO-PCA (KTEXT field in CEPC). Used in financial reports, dashboards, and rate case cost-of-service studies.',
    `profit_center_status` STRING COMMENT 'Current lifecycle status of the profit center record. Active profit centers accept postings; locked centers are frozen for new transactions; inactive centers are retired from use. Corresponds to the LOCK_IND and PRCTR_STATUS indicators in SAP CEPC.. Valid values are `active|inactive|locked|pending_activation`',
    `profit_center_type` STRING COMMENT 'Classification of the profit center by regulatory and operational type. Regulated centers are subject to PUC/FERC oversight and rate-of-return regulation; unregulated centers operate in competitive markets; corporate centers capture holding company costs; shared_services centers allocate common costs.. Valid values are `regulated|unregulated|corporate|shared_services`',
    `rate_base_usd` DECIMAL(18,2) COMMENT 'Regulatory rate base value assigned to this profit center in US dollars, representing the net investment on which the utility is permitted to earn a regulated return. Used in ROE calculations and rate case cost-of-service studies filed with FERC and state PUCs.',
    `regulatory_jurisdiction` STRING COMMENT 'Indicates the regulatory jurisdiction governing this profit centers rates and operations. Federal indicates FERC jurisdiction (transmission, wholesale); state indicates PUC jurisdiction (distribution, retail); both indicates dual jurisdiction; unregulated indicates competitive/non-regulated operations.. Valid values are `federal|state|both|unregulated`',
    `responsible_manager_code` STRING COMMENT 'Employee identifier of the manager accountable for the financial performance of this profit center. Corresponds to the VERAK field in SAP CEPC. Used for accountability reporting and performance-based ratemaking (PBR) analysis.',
    `responsible_manager_name` STRING COMMENT 'Full name of the manager responsible for this profit centers financial performance. Sourced from SAP HR/CO integration. Used in management reporting and rate case cost-of-service studies.',
    `revenue_budget_usd` DECIMAL(18,2) COMMENT 'Approved annual revenue budget for this profit center in US dollars. Used in ROE and ROI analysis by business unit, EBITDA reporting by segment, and variance analysis against actual revenues.',
    `rto_iso_membership` STRING COMMENT 'RTO or ISO market area in which this profit center participates (e.g., PJM, MISO, CAISO, SPP, ERCOT). Drives energy market cost allocation, LMP-based settlement, and OATT compliance reporting.',
    `segment_reporting_code` STRING COMMENT 'Code used to map this profit center to a reportable segment under GAAP ASC 280 (Segment Reporting) and FERC segment reporting requirements. Enables aggregation of profit centers into disclosed business segments in annual reports and FERC filings.. Valid values are `^[A-Z0-9_]{1,10}$`',
    `source_system_code` STRING COMMENT 'Identifier of the operational source system from which this profit center record was ingested (e.g., SAP_S4HANA_PROD, SAP_S4HANA_QA). Supports data lineage, multi-system reconciliation, and Silver Layer provenance tracking.. Valid values are `^[A-Z0-9_]{1,20}$`',
    `sox_relevant` BOOLEAN COMMENT 'Indicates whether this profit center is within scope for SOX internal controls over financial reporting. SOX-relevant profit centers require documented controls, segregation of duties, and periodic management attestation.',
    `valid_from_date` DATE COMMENT 'Date from which this profit center is effective and available for financial postings. Corresponds to DATAB in SAP CEPC. Used to enforce temporal validity in period-based financial reporting and rate case cost studies.',
    `valid_to_date` DATE COMMENT 'Date through which this profit center remains effective. Corresponds to DATBI in SAP CEPC. A value of 9999-12-31 indicates an open-ended profit center with no planned deactivation.',
    `wip_account_indicator` BOOLEAN COMMENT 'Indicates whether this profit center is designated to capture Work in Progress (WIP) costs for capital projects prior to asset capitalization. When true, costs posted here are subject to AFUDC accrual per FERC accounting requirements.',
    CONSTRAINT pk_profit_center PRIMARY KEY(`profit_center_id`)
) COMMENT 'Master record for profit centers representing the utilitys business segments used for internal profitability reporting and regulatory segment reporting. Captures profit center code, description, responsible manager, business segment (electric generation, electric transmission, electric distribution, gas distribution, unregulated), company code, controlling area, and active status. Supports FERC-required segment reporting, ROE (Return on Equity) and ROI analysis by business unit, and EBITDA reporting by segment. Sourced from SAP S/4HANA Controlling (CO-PCA) module.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`rate_case_cost_study` (
    `rate_case_cost_study_id` BIGINT COMMENT 'Unique surrogate identifier for the rate case cost-of-service study record in the Databricks Silver Layer. Primary key for this entity.',
    `rate_case_id` BIGINT COMMENT 'Reference to the parent rate case docket for which this cost-of-service study was prepared. Links to the regulatory.rate_case product.',
    `accumulated_depreciation_amount` DECIMAL(18,2) COMMENT 'Total accumulated depreciation deducted from gross plant in service to arrive at net plant in rate base. Expressed in US dollars. Corresponds to FERC Account 108.',
    `adit_amount` DECIMAL(18,2) COMMENT 'Accumulated Deferred Income Tax (ADIT) balance deducted from rate base, representing the tax benefits of accelerated depreciation that have been passed through to customers. Expressed in US dollars. Corresponds to FERC Account 190/282/283.',
    `afudc_amount` DECIMAL(18,2) COMMENT 'Allowance for Funds Used During Construction (AFUDC) capitalized during the test year, representing the cost of financing construction work in progress (WIP). Expressed in US dollars. Corresponds to FERC Accounts 107 and 432.',
    `approved_date` DATE COMMENT 'Date on which the regulatory authority (PUC or FERC) issued a final order approving the rates derived from this cost-of-service study. Null if the study has not yet received final regulatory approval.',
    `authorized_roe_pct` DECIMAL(18,2) COMMENT 'Authorized or proposed Return on Equity (ROE) percentage used in the cost-of-service study to calculate the equity component of the allowed return on rate base. Expressed as a decimal percentage (e.g., 9.5000 for 9.5%). Benchmarked against comparable utility ROE awards by the PUC or FERC.',
    `capex_amount` DECIMAL(18,2) COMMENT 'Total Capital Expenditure (CAPEX) included in or supporting the rate base determination for this cost-of-service study. Represents plant additions during the test year or projected capital investment period. Expressed in US dollars.',
    `cost_allocation_method` STRING COMMENT 'Methodology used to allocate costs among customer classes or rate jurisdictions in this cost-of-service study. Fully Distributed Cost (FDC) allocates all costs; Marginal Cost reflects incremental costs; Embedded Cost uses historical average costs; Hybrid combines approaches.. Valid values are `fully_distributed_cost|marginal_cost|embedded_cost|hybrid`',
    `cost_of_debt_pct` DECIMAL(18,2) COMMENT 'Embedded cost of long-term debt used in the WACC calculation, representing the weighted average interest rate on the utilitys outstanding debt instruments. Expressed as a decimal percentage (e.g., 4.8500 for 4.85%).',
    `cpcn_reference_number` STRING COMMENT 'Reference number of the Certificate of Public Convenience and Necessity (CPCN) application supported by this cost-of-service study, if applicable. Links the cost justification to the capital project authorization for major infrastructure investments.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this cost-of-service study record was first created in the system. Supports SOX audit trail requirements and record lineage tracking. This is the RECORD_AUDIT_CREATED for this TRANSACTION_HEADER entity.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for all monetary amounts in this cost-of-service study. Typically USD for US utility rate cases. Included to support multi-currency reporting and GAAP financial statement alignment.. Valid values are `^[A-Z]{3}$`',
    `debt_ratio_pct` DECIMAL(18,2) COMMENT 'Percentage of the capital structure represented by long-term debt, used in the WACC calculation. Expressed as a decimal percentage (e.g., 48.0000 for 48%). Together with equity_ratio_pct must sum to 100%.',
    `depreciation_expense_amount` DECIMAL(18,2) COMMENT 'Total depreciation expense included in the revenue requirement for the test year, calculated using depreciation rates approved by the regulatory authority applied to the depreciable plant in service. Expressed in US dollars. Corresponds to FERC Account 403.',
    `effective_date` DATE COMMENT 'Date on which the new rates derived from this cost-of-service study become effective for customer billing. May be subject to refund if rates are later adjusted by the regulatory authority.',
    `equity_ratio_pct` DECIMAL(18,2) COMMENT 'Percentage of the capital structure represented by equity, used in the WACC calculation. Expressed as a decimal percentage (e.g., 52.0000 for 52%). Determined by the utilitys actual or hypothetical capital structure as accepted by the regulatory authority.',
    `existing_revenue_amount` DECIMAL(18,2) COMMENT 'Current annual revenue collected under existing rates at the time of the rate case filing. The difference between revenue_requirement_amount and existing_revenue_amount represents the revenue deficiency or excess (rate increase or decrease needed). Expressed in US dollars.',
    `filing_date` DATE COMMENT 'Date on which the cost-of-service study was formally filed with the regulatory authority (PUC or FERC). This is the BUSINESS_EVENT_TIMESTAMP (date precision) for this TRANSACTION_HEADER entity. Triggers statutory review timelines and suspension periods.',
    `filing_status` STRING COMMENT 'Current lifecycle status of the cost-of-service study within the rate case workflow. Tracks progression from internal preparation through regulatory submission and disposition. This is the LIFECYCLE_STATUS for this TRANSACTION_HEADER entity.. Valid values are `draft|under_review|filed|suspended|approved|rejected`',
    `functionalization_method` STRING COMMENT 'Primary functional category used to classify utility costs in this study per FERC Uniform System of Accounts: production, transmission, distribution, customer, or general/administrative. Drives cost allocation to customer classes and rate design. [ENUM-REF-CANDIDATE: production|transmission|distribution|customer|general — promote to reference product if multi-function studies require line-level detail]. Valid values are `production|transmission|distribution|customer|general`',
    `income_tax_expense_amount` DECIMAL(18,2) COMMENT 'Total income tax expense (federal and state) included in the revenue requirement, calculated on the allowed return on equity component of the rate base. Expressed in US dollars. Includes adjustments for accumulated deferred income taxes (ADIT).',
    `irp_reference_number` STRING COMMENT 'Reference number of the Integrated Resource Plan (IRP) submission that this cost-of-service study supports, if applicable. Connects long-term resource planning cost projections to the rate case revenue requirement.',
    `jurisdiction_state` STRING COMMENT 'Two-letter US state abbreviation identifying the state PUC jurisdiction for this filing (e.g., CA, TX, NY). Null if the filing is exclusively with FERC. Used to apply state-specific regulatory accounting rules and tariff structures.. Valid values are `^[A-Z]{2}$`',
    `jurisdiction_type` STRING COMMENT 'Indicates whether this cost-of-service study is filed with a state Public Utility Commission (PUC), the Federal Energy Regulatory Commission (FERC), or both (dual jurisdiction). Determines applicable regulatory accounting standards and reporting requirements.. Valid values are `state_puc|ferc|dual`',
    `om_expense_amount` DECIMAL(18,2) COMMENT 'Total Operations and Maintenance (O&M) expense included in the revenue requirement for the test year, covering labor, materials, and contracted services for operating and maintaining generation, transmission, and distribution assets. Expressed in US dollars.',
    `pbr_target_included` BOOLEAN COMMENT 'Indicates whether this cost-of-service study includes Performance-Based Ratemaking (PBR) performance targets or incentive mechanisms as part of the rate design. True if PBR metrics (e.g., SAIDI, SAIFI, customer satisfaction) are incorporated into the revenue requirement or rate structure.',
    `prepared_by` STRING COMMENT 'Name or employee identifier of the regulatory analyst or financial professional responsible for preparing this cost-of-service study. Supports SOX accountability and regulatory filing certification requirements. This is the PARTY_REFERENCE for this TRANSACTION_HEADER entity.',
    `property_tax_expense_amount` DECIMAL(18,2) COMMENT 'Total property and other taxes (excluding income taxes) included in the revenue requirement for the test year. Expressed in US dollars. Corresponds to FERC Account 408.1.',
    `rate_base_amount` DECIMAL(18,2) COMMENT 'Total rate base as determined in this cost-of-service study, representing the net investment on which the utility is entitled to earn a return. Includes net plant in service, working capital, and other allowable investments, less accumulated depreciation and deferred taxes. Expressed in US dollars.',
    `revenue_deficiency_amount` DECIMAL(18,2) COMMENT 'Net difference between the total revenue requirement and existing revenues. A positive value indicates a revenue deficiency (rate increase needed); a negative value indicates a revenue surplus (rate decrease). Expressed in US dollars. This is the MONETARY_TRIPLET adjustment/net component.',
    `revenue_requirement_amount` DECIMAL(18,2) COMMENT 'Total revenue requirement calculated in this cost-of-service study, representing the total amount the utility is authorized to collect from customers to recover its costs and earn a fair return. Expressed in US dollars. This is the primary MONETARY_TRIPLET gross amount for this TRANSACTION_HEADER entity.',
    `settlement_reached` BOOLEAN COMMENT 'Indicates whether the rate case associated with this cost-of-service study was resolved through a negotiated settlement agreement among the utility, regulatory staff, and intervening parties, rather than a fully litigated proceeding.',
    `study_description` STRING COMMENT 'Narrative description of the scope, purpose, and key assumptions of this cost-of-service study. Includes summary of major cost drivers, significant adjustments from prior rate case, and any unusual items requiring regulatory explanation.',
    `study_number` STRING COMMENT 'Externally-known alphanumeric identifier assigned to this cost-of-service study, used in regulatory filings and cross-referenced in dockets. Typically formatted as a combination of jurisdiction code, year, and sequence (e.g., CA-GRC-2024-001). This is the BUSINESS_IDENTIFIER for this TRANSACTION_HEADER entity.',
    `study_type` STRING COMMENT 'Classification of the rate case type for which this cost-of-service study is prepared. Determines the applicable regulatory framework, tariff schedules, and cost allocation methodology. [ENUM-REF-CANDIDATE: general_rate_case|transmission_rate_case|gas_rate_case|distribution_rate_case|limited_rate_case — promote to reference product if additional types are needed]. Valid values are `general_rate_case|transmission_rate_case|gas_rate_case|distribution_rate_case|limited_rate_case`',
    `study_version` STRING COMMENT 'Version number of this cost-of-service study, incremented when the study is revised during the regulatory proceeding (e.g., in response to data requests, settlement negotiations, or updated actuals). Version 1 is the initial filing; subsequent versions reflect amendments.',
    `test_year_end_date` DATE COMMENT 'End date of the test year used as the basis for cost-of-service calculations. Together with test_year_start_date, defines the 12-month test period. May be historical (fully known actuals) or projected (future test year with estimates).',
    `test_year_start_date` DATE COMMENT 'Start date of the test year (historical or projected) used as the basis for cost-of-service calculations. The test year is the 12-month period whose costs and revenues form the foundation of the revenue requirement determination.',
    `test_year_type` STRING COMMENT 'Indicates whether the test year is based on historical actuals, a projected future period, or a hybrid combining historical data with known and measurable adjustments. Affects the level of regulatory scrutiny and the types of adjustments permitted.. Valid values are `historical|projected|hybrid`',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp when this cost-of-service study record was last modified. Supports SOX audit trail and change management tracking. This is the RECORD_AUDIT_UPDATED for this TRANSACTION_HEADER entity.',
    `wacc_pct` DECIMAL(18,2) COMMENT 'Weighted Average Cost of Capital (WACC) used to determine the overall allowed rate of return on rate base, blending the cost of debt and equity weighted by their respective proportions in the capital structure. Expressed as a decimal percentage (e.g., 7.2500 for 7.25%).',
    `working_capital_amount` DECIMAL(18,2) COMMENT 'Working capital allowance included in rate base, representing the utilitys investment in cash, materials, supplies, and prepayments needed to operate the business between billing cycles. Expressed in US dollars.',
    CONSTRAINT pk_rate_case_cost_study PRIMARY KEY(`rate_case_cost_study_id`)
) COMMENT 'Master record for cost-of-service studies prepared in support of rate case filings with state PUCs or FERC. Captures rate case identifier, filing jurisdiction (PUC state, FERC), test year, rate case type (general rate case, transmission rate case, gas rate case), total revenue requirement, rate base amount, authorized ROE, WACC, O&M expense allocation, depreciation expense, taxes, and filing status. Links to supporting GL accounts, cost centers, and CAPEX projects. Supports CPCN applications, IRP cost justifications, and PBR performance target derivation.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`financial_period` (
    `financial_period_id` BIGINT COMMENT 'Unique surrogate identifier for each fiscal period record in the financial reporting calendar. Primary key for the financial_period data product.',
    `prior_year_period_financial_period_id` BIGINT COMMENT 'Reference to the corresponding fiscal period in the prior year, enabling year-over-year financial comparisons in regulatory filings, earnings reports, and rate case testimony. For example, Period 3 FY2024 links to Period 3 FY2023.',
    `accrual_cutoff_date` DATE COMMENT 'The last date by which accrual journal entries (unbilled revenue, fuel cost accruals, O&M accruals, AFUDC accruals) must be posted to be included in this fiscal periods financial results. May differ from calendar_end_date when the utilitys close schedule allows a grace period for late accruals. Format: yyyy-MM-dd.',
    `budget_period_flag` BOOLEAN COMMENT 'Indicates whether this fiscal period has an approved operating budget loaded in the financial planning system. True = budget data available for variance analysis; False = no budget loaded. Supports CAPEX/OPEX budget vs. actual variance reporting and rate case cost-of-service analysis.',
    `calendar_end_date` DATE COMMENT 'The calendar date on which this fiscal period ends (inclusive). Defines the boundary for accruals, revenue recognition cut-offs, and period-end close procedures. Format: yyyy-MM-dd.',
    `calendar_month` STRING COMMENT 'The calendar month number (1–12) corresponding to this fiscal period. For regular periods, this aligns with the calendar month. For adjustment periods (13–16), this retains the calendar month of the base period to which adjustments are attributed. Supports alignment with AMI billing cycles and meter read schedules.',
    `calendar_start_date` DATE COMMENT 'The calendar date on which this fiscal period begins (inclusive). Used to align fiscal period boundaries with calendar-month meter reads, billing cycles, energy market settlement dates, and regulatory reporting windows. Format: yyyy-MM-dd.',
    `calendar_year` STRING COMMENT 'The four-digit calendar year corresponding to this fiscal period. May differ from fiscal_year for utilities operating on a non-calendar fiscal year (e.g., April–March). Required for aligning fiscal periods with calendar-year regulatory reporting and energy market settlement calendars.',
    `close_workflow_status` STRING COMMENT 'Tracks the current state of the period-end or year-end close workflow for this fiscal period. not_started = close activities not yet initiated; in_progress = close tasks underway; completed = all close tasks finished; approved = controller/CFO sign-off obtained; failed = close workflow encountered errors requiring remediation.. Valid values are `not_started|in_progress|completed|approved|failed`',
    `company_code` STRING COMMENT 'The SAP company code or Oracle ERP legal entity identifier for which this fiscal period is defined. Utilities with separate regulated subsidiaries (e.g., electric utility vs. gas utility) maintain distinct company codes with potentially independent period open/close controls for regulatory ring-fencing.',
    `controlling_area` STRING COMMENT 'The SAP Controlling (CO) area or Oracle ERP ledger set identifier to which this fiscal period applies. A controlling area groups company codes for cost controlling, internal orders, and profit center accounting. Utilities with multiple regulated entities (electric vs. gas) may operate under separate controlling areas with distinct period open/close schedules.',
    `created_timestamp` TIMESTAMP COMMENT 'The date and time when this fiscal period record was first created in the financial system (SAP S/4HANA or Oracle ERP Cloud). Provides an audit trail for period configuration changes. Format: yyyy-MM-ddTHH:mm:ss.SSSXXX.',
    `days_in_period` STRING COMMENT 'The total number of calendar days in this fiscal period (derived from calendar_start_date and calendar_end_date). Used for daily rate proration in billing, depreciation calculations, fuel cost accruals, and energy generation output normalization. Stored explicitly to avoid runtime date arithmetic in reporting queries.',
    `depreciation_run_status` STRING COMMENT 'Indicates the status of the periodic depreciation calculation run for utility plant assets in this fiscal period. not_run = depreciation not yet calculated; in_progress = depreciation run executing; completed = calculated but not yet posted; posted = depreciation journal entries posted to the GL. Critical for CAPEX tracking and FERC plant account reporting.. Valid values are `not_run|in_progress|completed|posted`',
    `ferc_reporting_year` STRING COMMENT 'The FERC reporting year to which this fiscal periods financial data is attributed for FERC Form 1 (electric) and FERC Form 2 (gas) annual report submissions. May differ from fiscal_year for utilities with non-calendar fiscal years. Ensures correct period-to-FERC-filing alignment for regulatory compliance.',
    `fiscal_quarter` STRING COMMENT 'The fiscal quarter (1–4) to which this period belongs. Derived from period_number but stored explicitly to support quarterly financial reporting, quarterly FERC filings, and quarterly earnings disclosures without requiring runtime computation.',
    `fiscal_year` STRING COMMENT 'The four-digit fiscal year to which this period belongs (e.g., 2024). May differ from the calendar year when the utility operates on a non-calendar fiscal year variant. Used for annual financial reporting, FERC Form 1 submissions, and rate case cost-of-service studies.',
    `fiscal_year_variant` STRING COMMENT 'The fiscal year variant code from SAP S/4HANA (e.g., K4 for calendar-year variant, V3 for April–March) or equivalent accounting calendar identifier from Oracle ERP Cloud. Determines the mapping between fiscal periods and calendar months. Essential for multi-entity utilities operating under different fiscal calendars.',
    `intercompany_elimination_status` STRING COMMENT 'Tracks whether intercompany transaction eliminations have been completed for this fiscal period in consolidated financial statements. Relevant for utilities with multiple regulated subsidiaries (electric, gas, unregulated affiliates). not_required = single-entity utility; pending = eliminations not yet processed; completed = eliminations posted.. Valid values are `not_required|pending|completed`',
    `is_adjustment_period` BOOLEAN COMMENT 'Indicates whether this is a special adjustment period (periods 13–16) used for post-close audit adjustments, regulatory accounting entries, or tax provision postings that must be segregated from regular operating period activity. True = adjustment period; False = regular period.',
    `is_open_for_asset_posting` BOOLEAN COMMENT 'Indicates whether the asset accounting sub-ledger is open for depreciation runs, asset acquisitions, retirements, and transfers in this fiscal period. Utilities carry significant CAPEX in generation, transmission, and distribution assets; asset accounting periods may close independently from the GL. True = asset postings permitted; False = blocked.',
    `is_open_for_co_posting` BOOLEAN COMMENT 'Indicates whether the cost controlling module is open for internal order settlements, cost center allocations, and profit center postings in this fiscal period. True = CO postings permitted; False = blocked. Supports OPEX and CAPEX cost allocation for rate case cost-of-service studies.',
    `is_open_for_gl_posting` BOOLEAN COMMENT 'Indicates whether the general ledger module is currently open for journal entry postings in this fiscal period. True = GL postings permitted; False = GL postings blocked. Distinct from asset accounting and cost controlling open flags, as each sub-ledger may have independent open/close timing.',
    `is_open_for_mm_posting` BOOLEAN COMMENT 'Indicates whether the materials management module is open for goods receipts, inventory movements, and purchase order invoice verifications in this fiscal period. Relevant for utility supply chain — fuel procurement, spare parts, and construction materials. True = MM postings permitted; False = blocked.',
    `is_year_end_period` BOOLEAN COMMENT 'Indicates whether this fiscal period is a year-end closing period requiring full year-end close procedures including balance carryforward, retained earnings posting, and annual financial statement preparation. True = year-end period; False = regular or interim period.',
    `last_updated_timestamp` TIMESTAMP COMMENT 'The date and time when this fiscal period record was most recently modified (e.g., status change from open to closed, lock applied). Supports change data capture in the Databricks Silver layer ETL pipeline and SOX audit trail requirements. Format: yyyy-MM-ddTHH:mm:ss.SSSXXX.',
    `ledger_type` STRING COMMENT 'Identifies the accounting ledger to which this period definition applies. leading = primary GAAP ledger; extension = parallel ledger for IFRS or tax accounting; regulatory = FERC regulatory accounting ledger. Utilities maintain parallel ledgers to reconcile GAAP financial statements with FERC Uniform System of Accounts regulatory books.. Valid values are `leading|extension|regulatory`',
    `period_close_timestamp` TIMESTAMP COMMENT 'The date and time when this fiscal period was officially closed following completion of period-end close procedures (accruals, reconciliations, depreciation runs, allocations). Null if the period has not yet been closed. Format: yyyy-MM-ddTHH:mm:ss.SSSXXX.',
    `period_description` STRING COMMENT 'Free-text description providing additional context about this fiscal period, such as special close instructions, regulatory filing notes, or explanations for non-standard adjustment periods. Used by the financial close team and external auditors for period documentation.',
    `period_lock_timestamp` TIMESTAMP COMMENT 'The date and time when this fiscal period was hard-locked, preventing any further postings including adjustments. Represents the final SOX control point after which no unauthorized changes can be made to the periods financial data. Null if the period has not been locked. Format: yyyy-MM-ddTHH:mm:ss.SSSXXX.',
    `period_name` STRING COMMENT 'Human-readable label for the fiscal period (e.g., January 2024, Q1 2024 Adjustment, Year-End Close 2024). Used in financial reports, dashboards, and regulatory filings for display purposes.',
    `period_number` STRING COMMENT 'The sequential period number within the fiscal year. Regular operating periods are numbered 1 through 12 (monthly). Adjustment and special closing periods are numbered 13 through 16 per SAP S/4HANA fiscal year variant conventions. Controls which posting periods are open in the general ledger, asset accounting, and cost controlling modules.',
    `period_open_timestamp` TIMESTAMP COMMENT 'The date and time when this fiscal period was officially opened for journal entry postings. Provides an audit trail for period lifecycle management and SOX compliance. Format: yyyy-MM-ddTHH:mm:ss.SSSXXX.',
    `period_short_code` STRING COMMENT 'Compact alphanumeric code uniquely identifying the fiscal period in the format YYYY.PPP (e.g., 2024.001 for Period 1 of FY2024, 2024.013 for the first adjustment period). Used as a display key in financial reports, journal entry headers, and regulatory filings where space is constrained.. Valid values are `^[0-9]{4}.[0-9]{3}$`',
    `period_status` STRING COMMENT 'Current lifecycle state of the fiscal period controlling whether journal entry postings are permitted. open = postings allowed; closed = period-end close completed, no new postings; locked = SOX-compliant hard lock preventing any unauthorized postings; future = period not yet reached. Critical SOX internal control — period lock prevents unauthorized retroactive postings to closed periods.. Valid values are `open|closed|locked|future`',
    `period_type` STRING COMMENT 'Classifies the nature of the fiscal period. regular = standard monthly operating period (1-12); adjustment = post-close adjustment period (13-14); year_end_closing = year-end closing period (15); special = utility-specific special posting period (16). Determines which business transactions and journal entry types are permitted during the period.. Valid values are `regular|adjustment|year_end_closing|special`',
    `rate_case_test_year_flag` BOOLEAN COMMENT 'Indicates whether this fiscal period falls within the designated test year for an active or pending rate case proceeding before the PUC or FERC. True = period is part of the rate case test year; False = not a test year period. Triggers enhanced cost tracking and cost-of-service study data collection for regulatory testimony.',
    `regulatory_reporting_period` BOOLEAN COMMENT 'Indicates whether this fiscal period aligns with a mandatory regulatory reporting deadline (e.g., FERC Form 1 annual filing, quarterly PUC financial reports, NERC reliability reporting). True = regulatory filing due at end of this period; False = no regulatory filing deadline. Triggers regulatory reporting workflow initiation.',
    `source_system_period_key` STRING COMMENT 'The natural key or technical identifier for this fiscal period as it exists in the originating source system (e.g., SAP S/4HANA fiscal year + posting period concatenation 202401, or Oracle ERP Cloud period_name Jan-24). Enables lineage tracing from the Silver layer back to the operational system of record for audit and reconciliation purposes.',
    `sox_certification_status` STRING COMMENT 'Tracks the SOX Section 302/404 internal control certification status for this fiscal period. not_required = period not subject to SOX certification (e.g., interim adjustment periods); pending = certification in progress; certified = management certification completed with no material weaknesses; exceptions_noted = material weakness or significant deficiency identified.. Valid values are `not_required|pending|certified|exceptions_noted`',
    CONSTRAINT pk_financial_period PRIMARY KEY(`financial_period_id`)
) COMMENT 'Reference master for fiscal periods and fiscal years used across the utilitys financial reporting calendar. Captures fiscal period number (1-12 plus adjustment periods 13-16), fiscal year, calendar month start and end dates, period status (open, closed, locked, future), period type (regular, adjustment, year-end closing, special), and controlling area. Governs which periods are open for journal entry posting, controls period-end and year-end close workflows, ensures consistent fiscal period alignment across GL, asset accounting, cost controlling, and regulatory reporting modules. Critical for SOX compliance — period lock controls prevent unauthorized postings to closed periods. Sourced from SAP S/4HANA FI fiscal year variant configuration or Oracle ERP Cloud accounting calendar.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`tax_provision` (
    `tax_provision_id` BIGINT COMMENT 'Unique identifier for the tax provision record. Primary key.',
    `financial_period_id` BIGINT COMMENT 'Foreign key linking to finance.financial_period. Business justification: tax_provision has fiscal_year and fiscal_period attributes. financial_period is the master for fiscal periods. Normalizing this reference allows joining to get full period metadata. fiscal_year and fi',
    `rate_case_id` BIGINT COMMENT 'Foreign key reference to the associated rate case cost study if this provision is part of test year calculations for a regulatory rate filing.',
    `prior_period_tax_provision_id` BIGINT COMMENT 'Self-referencing FK on tax_provision (prior_period_tax_provision_id)',
    `adit_accelerated_depreciation` DECIMAL(18,2) COMMENT 'Component of ADIT balance attributable to timing differences from accelerated tax depreciation methods versus book depreciation, the largest ADIT category for utilities.',
    `adit_balance` DECIMAL(18,2) COMMENT 'Cumulative balance of Accumulated Deferred Income Taxes at the end of the provision period, representing the net deferred tax liability or asset position that directly reduces rate base in regulatory accounting.',
    `adit_pension_obligations` DECIMAL(18,2) COMMENT 'Component of ADIT balance attributable to timing differences from pension and other post-retirement benefit obligations where book and tax recognition timing differs.',
    `adit_regulatory_liabilities` DECIMAL(18,2) COMMENT 'Component of ADIT balance attributable to regulatory liabilities and deferred revenue items that create temporary differences between book and tax treatment.',
    `adit_storm_cost_deferrals` DECIMAL(18,2) COMMENT 'Component of ADIT balance attributable to deferred storm restoration costs and other extraordinary event deferrals that create temporary differences.',
    `approval_timestamp` TIMESTAMP COMMENT 'Date and time when this tax provision was formally approved for posting, establishing the audit trail for SOX compliance.',
    `approved_by` STRING COMMENT 'Name or identifier of the authorized approver who signed off on this tax provision for posting to the general ledger.',
    `created_timestamp` TIMESTAMP COMMENT 'Date and time when this tax provision record was first created in the system.',
    `currency_code` STRING COMMENT 'Three-letter ISO 4217 currency code for all monetary amounts in this provision record, typically USD for U.S. utilities.. Valid values are `USD`',
    `current_federal_tax_expense` DECIMAL(18,2) COMMENT 'Current period federal income tax expense calculated on taxable income for the provision period, representing taxes payable to the federal government in the current year.',
    `current_state_tax_expense` DECIMAL(18,2) COMMENT 'Current period state income tax expense calculated on taxable income for the provision period, representing taxes payable to state jurisdictions in the current year.',
    `deferred_federal_tax_expense` DECIMAL(18,2) COMMENT 'Deferred federal income tax expense arising from temporary differences between book and tax accounting, representing future tax consequences of events recognized in financial statements.',
    `deferred_state_tax_expense` DECIMAL(18,2) COMMENT 'Deferred state income tax expense arising from temporary differences between book and tax accounting at the state jurisdiction level.',
    `edit_amortization_amount` DECIMAL(18,2) COMMENT 'Amount of Excess Deferred Income Taxes amortized during the provision period, flowing back to customers through reduced rates or regulatory liability accounts.',
    `edit_protected_balance` DECIMAL(18,2) COMMENT 'Protected portion of Excess Deferred Income Taxes related to public utility property that must be amortized using Average Rate Assumption Method (ARAM) per IRS normalization requirements.',
    `edit_unprotected_balance` DECIMAL(18,2) COMMENT 'Unprotected portion of Excess Deferred Income Taxes not subject to IRS normalization rules, which can be amortized more quickly to benefit customers.',
    `effective_tax_rate_pct` DECIMAL(18,2) COMMENT 'Effective tax rate percentage calculated as total tax expense divided by pre-tax book income, used for financial statement disclosure and rate case analysis.',
    `excess_deferred_income_taxes` DECIMAL(18,2) COMMENT 'Excess Deferred Income Taxes balance resulting from the Tax Cuts and Jobs Act (TCJA) federal rate reduction from 35% to 21%, requiring amortization back to customers per IRS normalization rules.',
    `federal_tax_jurisdiction` STRING COMMENT 'Federal tax jurisdiction code or identifier, typically IRS or federal tax authority reference for the provision calculation.',
    `fiscal_period` STRING COMMENT 'Fiscal period number within the fiscal year (1-12 for monthly, 1-4 for quarterly) to which this tax provision applies.',
    `fiscal_year` STRING COMMENT 'Fiscal year to which this tax provision applies, used for regulatory reporting and financial statement preparation.',
    `itc_amortization_amount` DECIMAL(18,2) COMMENT 'Amount of Investment Tax Credit amortized during the provision period, representing the systematic recognition of ITC benefits over the life of qualifying renewable energy or other eligible assets per IRS normalization rules.',
    `itc_unamortized_balance` DECIMAL(18,2) COMMENT 'Remaining unamortized balance of Investment Tax Credits at the end of the provision period, representing future tax benefits to be recognized over the remaining asset life.',
    `permanent_difference_amount` DECIMAL(18,2) COMMENT 'Total permanent differences between book and tax income that will never reverse, such as non-deductible expenses, tax-exempt income, and meals and entertainment disallowances.',
    `pre_tax_book_income` DECIMAL(18,2) COMMENT 'Pre-tax book income for the provision period per GAAP financial statements, serving as the starting point for the tax provision calculation and effective rate reconciliation.',
    `prepared_by` STRING COMMENT 'Name or identifier of the tax professional or system user who prepared this tax provision calculation.',
    `provision_number` STRING COMMENT 'Business identifier for the tax provision record, typically following a sequential or period-based numbering scheme for external reference and audit trail purposes.',
    `provision_period_end_date` DATE COMMENT 'End date of the period covered by this tax provision calculation, typically the last day of a fiscal quarter or year.',
    `provision_period_start_date` DATE COMMENT 'Start date of the period covered by this tax provision calculation, typically the first day of a fiscal quarter or year.',
    `provision_status` STRING COMMENT 'Current lifecycle status of the tax provision record indicating its stage in the approval and posting workflow.. Valid values are `draft|submitted|approved|posted|adjusted|closed`',
    `provision_type` STRING COMMENT 'Classification of the tax provision indicating whether it is a regular quarterly provision, annual provision, interim adjustment, amended filing, or year-end true-up calculation.. Valid values are `quarterly|annual|interim|amended|true-up`',
    `rate_base_adit_offset` DECIMAL(18,2) COMMENT 'ADIT amount used to reduce rate base in regulatory ratemaking, representing zero-cost capital that reduces the utilitys investment base for return calculation purposes.',
    `rate_case_test_year_flag` BOOLEAN COMMENT 'Boolean indicator identifying whether this provision period is part of a rate case test year, requiring special normalization and adjustment procedures for regulatory filings.',
    `reviewed_by` STRING COMMENT 'Name or identifier of the senior tax professional or manager who reviewed and validated this tax provision calculation.',
    `state_tax_jurisdiction` STRING COMMENT 'State tax jurisdiction code or abbreviation identifying the primary state tax authority for this provision, critical for multi-state utilities with apportionment requirements.',
    `statutory_federal_tax_rate_pct` DECIMAL(18,2) COMMENT 'Statutory federal income tax rate percentage in effect for the provision period, currently 21% post-TCJA, used as the baseline for effective rate reconciliation.',
    `statutory_state_tax_rate_pct` DECIMAL(18,2) COMMENT 'Statutory state income tax rate percentage in effect for the provision period in the primary state jurisdiction, used for state tax expense calculation.',
    `taxable_income` DECIMAL(18,2) COMMENT 'Taxable income calculated per Internal Revenue Code for the provision period, after adjusting book income for permanent and temporary differences.',
    `temporary_difference_amount` DECIMAL(18,2) COMMENT 'Total temporary differences between book and tax income that will reverse in future periods, giving rise to deferred tax assets or liabilities.',
    `total_tax_expense` DECIMAL(18,2) COMMENT 'Total income tax expense for the provision period, calculated as the sum of current and deferred federal and state tax expenses.',
    `uncertain_tax_position_reserve` DECIMAL(18,2) COMMENT 'Reserve established for uncertain tax positions under FIN 48 (ASC 740-10) where the utility has taken a tax position that may not be sustained upon examination by tax authorities.',
    `updated_timestamp` TIMESTAMP COMMENT 'Date and time when this tax provision record was last modified, supporting audit trail and change tracking requirements.',
    `valuation_allowance` DECIMAL(18,2) COMMENT 'Valuation allowance established against deferred tax assets when it is more likely than not that some portion will not be realized, per GAAP ASC 740 guidance.',
    CONSTRAINT pk_tax_provision PRIMARY KEY(`tax_provision_id`)
) COMMENT 'Periodic record for income tax provisions, deferred income tax calculations, and Accumulated Deferred Income Taxes (ADIT) balances for the utility. Captures tax provision period, fiscal year, current federal tax expense, current state tax expense, deferred federal tax expense, deferred state tax expense, ADIT balance by timing difference category (accelerated depreciation, regulatory liabilities, pension obligations, storm cost deferrals, excess deferred income taxes — EDIT), federal vs. state tax jurisdiction, effective tax rate, statutory tax rate, permanent and temporary difference reconciliation items, and ITC (Investment Tax Credit) amortization. Supports FERC Form 1 Schedule 272 (Accumulated Deferred Income Taxes), rate base ADIT offset calculations per IRS normalization rules, GAAP ASC 740 income tax accounting, rate case test year tax expense normalization, and Tax Cuts and Jobs Act (TCJA) excess ADIT amortization tracking. Essential for regulatory accounting where ADIT directly reduces rate base.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`regulatory_deferral` (
    `regulatory_deferral_id` BIGINT COMMENT 'Unique identifier for the regulatory deferral record. Primary key for the regulatory deferral master table.',
    `cost_center_id` BIGINT COMMENT 'Foreign key linking to finance.cost_center. Business justification: regulatory_deferral has cost_center_code attribute. cost_center is the master for cost centers. Normalizing this reference allows joining to get full cost center details (name, responsible_manager, fu',
    `financial_period_id` BIGINT COMMENT 'Foreign key linking to finance.financial_period. Business justification: regulatory_deferral has fiscal_year attribute. financial_period is the master for fiscal periods. Normalizing this reference allows joining to get full period metadata (period dates, status, etc.). fi',
    `gl_account_id` BIGINT COMMENT 'Foreign key linking to finance.gl_account. Business justification: regulatory_deferral has gl_account_code attribute. gl_account is the master for GL accounts. Normalizing this reference allows joining to get full account details (account_name, ferc_account_descripti',
    `profit_center_id` BIGINT COMMENT 'Foreign key linking to finance.profit_center. Business justification: regulatory_deferral has profit_center_code attribute. profit_center is the master for profit centers. Normalizing this reference allows joining to get full profit center details (name, responsible_man',
    `rate_case_id` BIGINT COMMENT 'Identifier of the rate case proceeding in which the regulatory deferral was authorized or is being sought for recovery or refund.',
    `originating_regulatory_deferral_id` BIGINT COMMENT 'Self-referencing FK on regulatory_deferral (originating_regulatory_deferral_id)',
    `accumulated_carrying_charges` DECIMAL(18,2) COMMENT 'Total carrying charges (interest) accumulated on the regulatory deferral balance to date, representing the time value of money on deferred costs or revenues.',
    `accumulated_deferral_amount` DECIMAL(18,2) COMMENT 'Total amount of costs or revenues accumulated in the regulatory deferral account to date, representing the gross balance before any amortization.',
    `amortization_method` STRING COMMENT 'Method prescribed by the regulatory authority for amortizing the deferred amount over the recovery period, such as straight-line, declining balance, units of production, levelized, or custom regulatory-approved method.. Valid values are `straight_line|declining_balance|units_of_production|levelized|custom`',
    `amortization_period_years` STRING COMMENT 'Number of years over which the regulatory deferral is authorized to be amortized and recovered through customer rates or refunded to customers.',
    `annual_amortization_amount` DECIMAL(18,2) COMMENT 'Planned annual amortization amount to be recovered or refunded each year based on the authorized amortization method and period.',
    `authorization_date` DATE COMMENT 'Date on which the regulatory authority (PUC or FERC) authorized the deferral of costs or revenues for future rate recovery or refund.',
    `authorized_deferral_amount` DECIMAL(18,2) COMMENT 'Total amount authorized by the regulatory authority for deferral, representing the maximum cost or revenue that may be deferred for future rate recovery or refund.',
    `carrying_charge_rate_pct` DECIMAL(18,2) COMMENT 'Annual percentage rate applied to the unamortized balance to calculate carrying charges (interest) on the regulatory deferral, typically based on the utilitys weighted average cost of capital or a regulatory-approved rate.',
    `company_code` STRING COMMENT 'Company code or legal entity identifier to which the regulatory deferral belongs, supporting multi-entity consolidated financial reporting.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the regulatory deferral record was first created in the system, supporting audit trail and data lineage tracking.',
    `currency_code` STRING COMMENT 'Three-letter ISO 4217 currency code for all monetary amounts in the regulatory deferral record. Power and Utilities operates in USD.. Valid values are `USD`',
    `deferral_category` STRING COMMENT 'Specific category of the regulatory deferral such as storm cost, pension/OPEB, fuel adjustment clause under/over-recovery, environmental remediation, rate case expense, EDIT (Excess Deferred Income Taxes), demand-side management program costs, renewable energy program costs, or other regulatory-approved deferral categories. [ENUM-REF-CANDIDATE: storm_cost|pension_opeb|fuel_adjustment_clause|environmental_remediation|rate_case_expense|edit|dsm_program|renewable_program|transmission_upgrade|distribution_upgrade|other — promote to reference product]',
    `deferral_description` STRING COMMENT 'Detailed business description of the regulatory deferral, including the nature of the deferred costs or revenues, the business justification, and the regulatory authorization basis.',
    `deferral_number` STRING COMMENT 'Business identifier or tracking number assigned to the regulatory deferral for external reference and regulatory reporting.',
    `deferral_status` STRING COMMENT 'Current lifecycle status of the regulatory deferral indicating whether it is pending regulatory approval, approved and active, fully amortized, terminated, or suspended.. Valid values are `pending_approval|approved|active|fully_amortized|terminated|suspended`',
    `deferral_type` STRING COMMENT 'Classification of the deferral as either a regulatory asset (costs deferred for future recovery) or regulatory liability (revenues deferred for future refund to customers).. Valid values are `regulatory_asset|regulatory_liability`',
    `effective_end_date` DATE COMMENT 'Date on which the regulatory deferral is scheduled to be fully amortized or terminated. Nullable for deferrals with indefinite recovery periods pending future rate proceedings.',
    `effective_start_date` DATE COMMENT 'Date from which the regulatory deferral becomes effective and begins accumulating deferred amounts or commencing amortization.',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts code for the regulatory deferral, typically Account 182.3 (Other Regulatory Assets) or Account 254 (Other Regulatory Liabilities).',
    `fiscal_year` STRING COMMENT 'Fiscal year in which the regulatory deferral was established or is currently being amortized, supporting period-based financial reporting and analysis.',
    `functional_class` STRING COMMENT 'Functional classification of the regulatory deferral indicating whether it relates to generation, transmission, distribution, customer service, or administrative and general operations.. Valid values are `generation|transmission|distribution|customer_service|administrative`',
    `is_ferc_reportable` BOOLEAN COMMENT 'Boolean flag indicating whether the regulatory deferral must be reported on FERC Form 1 Schedules 232 (Regulatory Assets) or 254 (Regulatory Liabilities).',
    `is_rate_base_eligible` BOOLEAN COMMENT 'Boolean flag indicating whether the regulatory deferral balance is included in the utilitys rate base for purposes of calculating allowed return on equity (ROE) and revenue requirement.',
    `is_sox_relevant` BOOLEAN COMMENT 'Boolean flag indicating whether the regulatory deferral is subject to Sarbanes-Oxley Act internal control and audit requirements due to materiality or financial statement impact.',
    `notes` STRING COMMENT 'Additional notes, comments, or special instructions related to the regulatory deferral, including any regulatory conditions, audit findings, or management commentary.',
    `puc_authorization_reference` STRING COMMENT 'Reference number or citation of the PUC order, rate case docket, or FERC order that authorized the regulatory deferral.',
    `recovery_mechanism` STRING COMMENT 'Description of the rate mechanism through which the regulatory deferral will be recovered from or refunded to customers, such as base rates, rider, surcharge, fuel adjustment clause, or other regulatory-approved mechanism.',
    `regulatory_jurisdiction` STRING COMMENT 'State or federal regulatory jurisdiction under which the deferral was authorized, such as state PUC code or FERC for interstate transmission.',
    `source_system` STRING COMMENT 'Identifier of the source system from which the regulatory deferral record originated, typically the ERP financial system or regulatory accounting system.',
    `unamortized_balance` DECIMAL(18,2) COMMENT 'Remaining balance of the regulatory deferral that has not yet been amortized or recovered through rates, representing the current carrying value on the balance sheet.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp when the regulatory deferral record was last modified, supporting change tracking and audit trail requirements.',
    `utility_type` STRING COMMENT 'Type of utility service to which the regulatory deferral applies: electric, gas, or combined electric and gas operations.. Valid values are `electric|gas|combined`',
    CONSTRAINT pk_regulatory_deferral PRIMARY KEY(`regulatory_deferral_id`)
) COMMENT 'Master record for regulatory assets and regulatory liabilities recognized under ASC 980 (Regulated Operations) that represent costs or revenues deferred for future rate recovery or refund. Captures deferral type (regulatory asset or regulatory liability), deferral category (storm cost, pension/OPEB, fuel adjustment clause under/over-recovery, environmental remediation, rate case expense, EDIT — Excess Deferred Income Taxes), authorized deferral amount, amortization method, amortization period, remaining unamortized balance, PUC/FERC authorization reference, and deferral status. Supports FERC Form 1 Schedules 232 (Regulatory Assets) and 254 (Regulatory Liabilities), rate case revenue requirement calculations, and GAAP balance sheet presentation under ASC 980.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`regulatory_asset_entry` (
    `regulatory_asset_entry_id` BIGINT COMMENT 'Unique identifier for the regulatory asset or liability entry in the regulatory asset base (RAB). Primary key for tracking individual regulatory accounting entries reported to PUCs and FERC.',
    `capex_project_id` BIGINT COMMENT 'Reference to the capital project that originated this regulatory asset entry, linking the entry to the project authorization, budget, and work breakdown structure (WBS).',
    `cost_center_id` BIGINT COMMENT 'FK to finance.cost_center',
    `financial_period_id` BIGINT COMMENT 'Foreign key linking to finance.financial_period. Business justification: regulatory_asset_entry has fiscal_year and fiscal_period attributes. financial_period is the master for fiscal periods. Normalizing this reference allows joining to get full period metadata. fiscal_ye',
    `gl_account_id` BIGINT COMMENT 'FK to finance.gl_account',
    `master_id` BIGINT COMMENT 'Reference to the underlying fixed asset in the Enterprise Asset Management (EAM) system when this regulatory entry represents a specific capitalized asset or plant addition.',
    `profit_center_id` BIGINT COMMENT 'FK to finance.profit_center',
    `rate_case_id` BIGINT COMMENT 'Reference to the rate case proceeding in which this regulatory asset or liability was approved for recovery or refund, linking the entry to the regulatory order and cost-of-service study.',
    `prior_period_regulatory_asset_entry_id` BIGINT COMMENT 'Self-referencing FK on regulatory_asset_entry (prior_period_regulatory_asset_entry_id)',
    `accumulated_amortization` DECIMAL(18,2) COMMENT 'Total cumulative amortization expense recognized to date for this regulatory asset or liability, representing the portion already recovered or refunded through customer rates.',
    `afudc_amount` DECIMAL(18,2) COMMENT 'Total AFUDC amount capitalized to this regulatory asset during the construction period, representing the financing cost component added to the asset base.',
    `amortization_end_date` DATE COMMENT 'Scheduled date on which amortization of the regulatory asset or liability is expected to be fully completed, representing the end of the recovery or refund period.',
    `amortization_method` STRING COMMENT 'Method used to calculate periodic amortization expense for the regulatory asset or liability, as prescribed by the regulatory commission or approved accounting policy.. Valid values are `straight_line|declining_balance|units_of_production|custom`',
    `amortization_period_months` STRING COMMENT 'Total number of months over which the regulatory asset or liability is scheduled to be amortized, as approved by the regulatory commission in the rate case order.',
    `amortization_start_date` DATE COMMENT 'Date on which amortization of the regulatory asset or liability begins, marking the commencement of systematic recovery or refund through customer rates.',
    `annual_amortization_amount` DECIMAL(18,2) COMMENT 'Planned annual amortization expense for the regulatory asset or liability, representing the amount to be recovered or refunded each year through customer rates.',
    `carrying_cost_amount` DECIMAL(18,2) COMMENT 'Dollar amount of carrying costs accrued on the regulatory asset balance for the current period, representing the return component recoverable through rates in addition to amortization.',
    `carrying_cost_rate` DECIMAL(18,2) COMMENT 'Annual percentage rate applied to the unamortized balance of the regulatory asset to calculate carrying costs (return on investment), representing the weighted average cost of capital (WACC) or authorized rate of return.',
    `ciac_amount` DECIMAL(18,2) COMMENT 'Dollar amount of customer or third-party contributions received to offset the cost of this regulatory asset, reducing the net amount included in rate base.',
    `ciac_indicator` BOOLEAN COMMENT 'Indicates whether this regulatory asset entry includes or is offset by Contribution in Aid of Construction (CIAC) amounts received from customers or third parties to fund capital improvements.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this regulatory asset entry record was first created in the financial system, supporting audit trail and data lineage tracking.',
    `currency_code` STRING COMMENT 'Three-letter ISO 4217 currency code for all monetary amounts in this entry. Utility operates in USD.. Valid values are `USD`',
    `current_balance` DECIMAL(18,2) COMMENT 'Current unamortized balance of the regulatory asset or liability as of the reporting date, reflecting the remaining amount to be recovered or refunded through future rates.',
    `effective_date` DATE COMMENT 'Date on which the regulatory asset or liability becomes effective for rate recovery or refund purposes, as specified in the regulatory order or tariff filing.',
    `entry_description` STRING COMMENT 'Detailed narrative description of the regulatory asset or liability, explaining the nature of the deferred cost or obligation, the business justification, and the regulatory treatment approved by the commission.',
    `entry_number` STRING COMMENT 'Business identifier for the regulatory asset or liability entry, used for external reporting and cross-referencing in rate case filings and regulatory submissions.',
    `entry_status` STRING COMMENT 'Current lifecycle status of the regulatory asset or liability entry, tracking its progression from initial recording through amortization to retirement or transfer. [ENUM-REF-CANDIDATE: active|pending_approval|approved|amortizing|fully_amortized|retired|transferred — 7 candidates stripped; promote to reference product]',
    `entry_type` STRING COMMENT 'Classification of the regulatory accounting entry indicating whether it represents a regulatory asset, regulatory liability, deferred debit, deferred credit, construction work in progress (CWIP), or plant in service.. Valid values are `regulatory_asset|regulatory_liability|deferred_debit|deferred_credit|cwip|plant_in_service`',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts code identifying the specific plant, asset, or regulatory account classification for this entry. Critical for regulatory reporting and rate case cost-of-service studies.',
    `ferc_account_description` STRING COMMENT 'Full descriptive name of the FERC account code, providing human-readable context for the regulatory accounting classification.',
    `fiscal_period` STRING COMMENT 'Fiscal period (month or quarter) within the fiscal year for which this regulatory entry is reported, supporting period-level financial and regulatory reporting.',
    `fiscal_year` STRING COMMENT 'Fiscal year in which this regulatory asset or liability entry was recognized or is being reported, aligning with the utilitys financial reporting calendar.',
    `functional_class` STRING COMMENT 'Functional classification of the regulatory asset or liability within utility operations, aligning with FERC functional cost categories for rate base allocation and cost-of-service studies.. Valid values are `generation|transmission|distribution|general`',
    `is_afudc_eligible` BOOLEAN COMMENT 'Indicates whether this regulatory asset is eligible for accrual of Allowance for Funds Used During Construction (AFUDC), representing the cost of capital during the construction period.',
    `is_cwip_eligible` BOOLEAN COMMENT 'Indicates whether this entry represents construction work in progress that is eligible for inclusion in rate base before the asset is placed in service, subject to regulatory approval.',
    `is_rate_base_eligible` BOOLEAN COMMENT 'Indicates whether this regulatory asset is eligible for inclusion in the rate base for calculation of allowed return on equity (ROE) and revenue requirement in rate case proceedings.',
    `jurisdiction_state` STRING COMMENT 'Two-letter state code identifying the specific state Public Utility Commission (PUC) jurisdiction for state-regulated regulatory assets and liabilities.',
    `original_amount` DECIMAL(18,2) COMMENT 'Original dollar value of the regulatory asset or liability at the time of initial recognition, representing the total amount authorized for recovery or refund before any amortization.',
    `recognition_date` DATE COMMENT 'Date on which the regulatory asset or liability was initially recognized in the regulatory accounting records, typically corresponding to the regulatory order or commission approval date.',
    `regulatory_jurisdiction` STRING COMMENT 'Level of regulatory authority governing this regulatory asset or liability entry, indicating whether it is subject to federal (FERC), state (PUC), or municipal oversight.. Valid values are `federal|state|municipal`',
    `regulatory_order_date` DATE COMMENT 'Date on which the regulatory commission issued the order authorizing this regulatory asset or liability, establishing the legal basis for rate recovery or refund.',
    `regulatory_order_number` STRING COMMENT 'Official order or docket number issued by the regulatory commission (FERC or state PUC) authorizing the recognition and recovery of this regulatory asset or liability.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp when this regulatory asset entry record was last modified, supporting change tracking and audit compliance for regulatory accounting records.',
    `utility_type` STRING COMMENT 'Type of utility service to which this regulatory asset or liability applies, distinguishing between electric operations, gas operations, or combined utility functions.. Valid values are `electric|gas|combined`',
    `wbs_element` STRING COMMENT 'Work breakdown structure element linking this regulatory entry to the originating capital project hierarchy for project cost tracking and CAPEX reporting.',
    CONSTRAINT pk_regulatory_asset_entry PRIMARY KEY(`regulatory_asset_entry_id`)
) COMMENT 'Tracks regulatory assets and liabilities in the regulatory asset base (RAB) as reported to PUCs and FERC for rate case proceedings, capturing asset-in-service values, CWIP, and accumulated depreciation by FERC account.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`depreciation_study` (
    `depreciation_study_id` BIGINT COMMENT 'Primary key for depreciation_study',
    `prior_study_id` BIGINT COMMENT 'Reference to the previous depreciation study that this study supersedes or updates. Nullable for initial studies.',
    `prior_depreciation_study_id` BIGINT COMMENT 'Self-referencing FK on depreciation_study (prior_depreciation_study_id)',
    `accumulated_depreciation_amount` DECIMAL(18,2) COMMENT 'Total accumulated depreciation reserve for all assets in the study scope as of the study analysis date, measured in US dollars.',
    `actuarial_method` STRING COMMENT 'Statistical method used to estimate service life and survivor characteristics of asset groups. Iowa curves are industry standard for utility depreciation studies.',
    `annual_depreciation_expense` DECIMAL(18,2) COMMENT 'Projected annual depreciation expense resulting from the rates recommended in this study, measured in US dollars.',
    `approval_date` DATE COMMENT 'Date when the regulatory body officially approved the depreciation study and its recommended rates. Nullable for pending or internal studies.',
    `approval_order_number` STRING COMMENT 'Official order or decision number issued by the regulatory body approving the depreciation study. Nullable for unapproved studies.',
    `asset_base_amount` DECIMAL(18,2) COMMENT 'Total gross plant value (original cost) of all assets included in the scope of this depreciation study, measured in US dollars.',
    `average_remaining_life_years` DECIMAL(18,2) COMMENT 'Weighted average remaining service life for existing assets in the study scope, measured in years.',
    `average_service_life_years` DECIMAL(18,2) COMMENT 'Weighted average estimated service life across all asset classes included in the study, measured in years.',
    `consultant_firm_name` STRING COMMENT 'Name of the external consulting firm that prepared or assisted with the depreciation study. Nullable if study was performed entirely in-house.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this depreciation study record was first created in the system.',
    `depreciation_method` STRING COMMENT 'Primary depreciation calculation methodology applied in this study. Straight-line is most common for utility assets under FERC guidelines. Remaining life and equal life group methods are used for mass property accounts.',
    `effective_date` DATE COMMENT 'Date when the depreciation rates and parameters from this study become effective for accounting and regulatory purposes.',
    `expiration_date` DATE COMMENT 'Date when the depreciation study parameters are scheduled to be superseded by a new study. Nullable for studies with indefinite applicability.',
    `filing_date` DATE COMMENT 'Date when the depreciation study was officially filed with the regulatory body. Nullable for internal studies.',
    `filing_docket_number` STRING COMMENT 'Official docket or case number assigned by the regulatory body when the depreciation study is filed for approval. Nullable for internal studies not requiring regulatory filing.',
    `gaap_compliance_indicator` BOOLEAN COMMENT 'Flag indicating whether the depreciation study methodology and rates comply with Generally Accepted Accounting Principles. True for studies used in GAAP financial reporting.',
    `last_modified_timestamp` TIMESTAMP COMMENT 'Timestamp when this depreciation study record was most recently updated in the system.',
    `lead_analyst_name` STRING COMMENT 'Name of the primary analyst or actuary responsible for conducting the depreciation study.',
    `net_book_value_amount` DECIMAL(18,2) COMMENT 'Net plant value (gross plant minus accumulated depreciation) for all assets in the study scope, measured in US dollars.',
    `net_salvage_percent` DECIMAL(18,2) COMMENT 'Weighted average net salvage value as a percentage of original cost across all asset classes. Net salvage represents gross salvage minus cost of removal. Can be negative when removal costs exceed salvage value.',
    `notes` STRING COMMENT 'Additional notes, comments, or special considerations related to the depreciation study, including any deviations from standard methodology or unique circumstances.',
    `rate_case_docket_number` STRING COMMENT 'Docket number of the associated rate case if this study was prepared for rate case purposes. Nullable if not associated with a rate case.',
    `rate_case_indicator` BOOLEAN COMMENT 'Flag indicating whether this depreciation study was prepared specifically to support a rate case filing. True if study is part of rate case, false otherwise.',
    `regulatory_body` STRING COMMENT 'Name of the specific regulatory agency or commission that has jurisdiction over this depreciation study (e.g., FERC, state public utility commission name).',
    `regulatory_jurisdiction` STRING COMMENT 'Primary regulatory jurisdiction governing this depreciation study. Federal studies follow FERC guidelines, state studies follow public utility commission requirements, and multi-jurisdictional studies address multiple regulatory bodies.',
    `sox_compliance_indicator` BOOLEAN COMMENT 'Flag indicating whether this depreciation study was subject to Sarbanes-Oxley internal control requirements and review. True for studies affecting financial statements of publicly traded utilities.',
    `study_completion_date` DATE COMMENT 'Date when the depreciation study analysis was completed and finalized for submission or approval.',
    `study_documentation_url` STRING COMMENT 'File path or URL to the complete depreciation study report and supporting documentation in the document management system.',
    `study_name` STRING COMMENT 'Descriptive name of the depreciation study, typically including the asset class or scope covered.',
    `study_number` STRING COMMENT 'Business identifier for the depreciation study, typically formatted as DS-YYYY-NNNN where YYYY is year and NNNN is sequence number.',
    `study_scope_description` STRING COMMENT 'Detailed description of the asset classes, FERC accounts, and organizational units covered by this depreciation study.',
    `study_start_date` DATE COMMENT 'Date when the depreciation study analysis and data collection commenced.',
    `study_status` STRING COMMENT 'Current lifecycle status of the depreciation study. Tracks progression from initial draft through regulatory approval and implementation.',
    `study_type` STRING COMMENT 'Classification of the depreciation study based on scope and purpose. Comprehensive studies cover all asset classes, interim studies update specific parameters, special studies address unique circumstances, rate case studies support regulatory filings, and asset class specific studies focus on particular equipment categories.',
    CONSTRAINT pk_depreciation_study PRIMARY KEY(`depreciation_study_id`)
) COMMENT 'Master reference table for depreciation_study. Referenced by depreciation_study_id.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`journal_entry_template` (
    `journal_entry_template_id` BIGINT COMMENT 'Primary key for journal_entry_template',
    `superseded_by_template_id` BIGINT COMMENT 'Reference to the newer template that replaces this template when it is deprecated or archived. Null for current active templates.',
    `recurring_journal_entry_template_id` BIGINT COMMENT 'Self-referencing FK on journal_entry_template (recurring_journal_entry_template_id)',
    `accounting_standard` STRING COMMENT 'Primary accounting standard framework that governs the use and structure of this journal entry template.',
    `approval_workflow_code` STRING COMMENT 'Reference to the approval workflow configuration that governs the review and authorization process for entries using this template.',
    `approved_by` STRING COMMENT 'User identifier of the authorized person who approved this template for production use. Null for templates not yet approved.',
    `approved_timestamp` TIMESTAMP COMMENT 'Date and time when this journal entry template was approved for production use. Null for templates not yet approved.',
    `auto_reverse_flag` BOOLEAN COMMENT 'Indicates whether journal entries created from this template should automatically generate reversing entries in the subsequent accounting period.',
    `balance_type` STRING COMMENT 'Indicates whether the template enforces balanced debits and credits, allows unbalanced entries, or relies on system calculation for balancing.',
    `control_objective` STRING COMMENT 'Description of the internal control objective this template supports for financial reporting accuracy and compliance purposes.',
    `cost_center_required_flag` BOOLEAN COMMENT 'Indicates whether a cost center assignment is mandatory for journal entries created from this template for cost accounting purposes.',
    `created_timestamp` TIMESTAMP COMMENT 'Date and time when this journal entry template record was first created in the system.',
    `currency_code` STRING COMMENT 'Three-letter ISO 4217 currency code for journal entries created from this template. Typically USD for US utility operations.',
    `default_posting_period` STRING COMMENT 'Default accounting period relative to the entry creation date where journal entries from this template should be posted.',
    `effective_end_date` DATE COMMENT 'Date after which this journal entry template is no longer active and should not be used for new journal entries. Null for templates with no planned end date.',
    `effective_start_date` DATE COMMENT 'Date from which this journal entry template becomes active and available for use in creating journal entries.',
    `functional_area` STRING COMMENT 'Business functional area or department that primarily uses this template for their accounting transactions and financial reporting.',
    `intercompany_flag` BOOLEAN COMMENT 'Indicates whether this template is used for intercompany transactions requiring elimination entries during financial consolidation.',
    `last_modified_by` STRING COMMENT 'User identifier of the person who most recently modified this journal entry template record.',
    `last_modified_timestamp` TIMESTAMP COMMENT 'Date and time when this journal entry template record was most recently modified in the system.',
    `last_used_date` DATE COMMENT 'Most recent date when this template was used to create a journal entry, supporting template usage analysis and archival decisions.',
    `notes` STRING COMMENT 'Additional notes, comments, or special considerations related to this journal entry template for accounting staff reference.',
    `project_required_flag` BOOLEAN COMMENT 'Indicates whether a project or work order assignment is mandatory for entries using this template to support capital expenditure (CAPEX) tracking.',
    `recurrence_day` STRING COMMENT 'Day of the month (1-31) or week (1-7) when recurring journal entries using this template should be posted. Null for non-recurring templates.',
    `recurrence_frequency` STRING COMMENT 'Frequency at which this template is intended to be used for recurring journal entries. Null for non-recurring templates.',
    `regulatory_account_class` STRING COMMENT 'Federal Energy Regulatory Commission (FERC) account classification applicable to this template for regulatory reporting and rate case preparation.',
    `requires_approval_flag` BOOLEAN COMMENT 'Indicates whether journal entries created from this template require supervisory approval before posting to the general ledger.',
    `reverse_period_offset` STRING COMMENT 'Number of accounting periods after the original entry when the automatic reversing entry should be posted. Null if auto_reverse_flag is false.',
    `source_system` STRING COMMENT 'Name of the originating system or module that typically generates journal entries using this template for automated posting scenarios.',
    `sox_control_flag` BOOLEAN COMMENT 'Indicates whether this template is subject to Sarbanes-Oxley internal control requirements and enhanced audit trail documentation.',
    `journal_entry_template_status` STRING COMMENT 'Current lifecycle status of the journal entry template indicating whether it is available for use in creating journal entries.',
    `tax_relevant_flag` BOOLEAN COMMENT 'Indicates whether journal entries from this template have tax implications requiring special handling for tax accounting and reporting.',
    `template_category` STRING COMMENT 'Business category classification of the template indicating the functional area or accounting domain it serves within utility operations.',
    `template_code` STRING COMMENT 'Unique business identifier code for the journal entry template used for external reference and system integration.',
    `template_description` STRING COMMENT 'Detailed description of the journal entry template including its purpose, usage guidelines, and business scenarios where it should be applied.',
    `template_name` STRING COMMENT 'Human-readable name of the journal entry template describing its business purpose and usage context.',
    `template_type` STRING COMMENT 'Classification of the journal entry template based on its accounting purpose and timing within the financial cycle.',
    `usage_count` STRING COMMENT 'Total number of times this template has been used to create journal entries, supporting template effectiveness analysis.',
    `usage_instructions` STRING COMMENT 'Detailed instructions for accounting staff on how to properly use this template including data entry requirements and business rules.',
    `version_number` STRING COMMENT 'Version number of the template to track changes and maintain audit trail of template modifications over time.',
    `created_by` STRING COMMENT 'User identifier of the person who created this journal entry template record in the system.',
    CONSTRAINT pk_journal_entry_template PRIMARY KEY(`journal_entry_template_id`)
) COMMENT 'Master reference table for journal_entry_template. Referenced by recurring_template_id.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`wbs_element` (
    `wbs_element_id` BIGINT COMMENT 'Primary key for wbs_element',
    `cost_center_id` BIGINT COMMENT 'Reference to the cost center for financial tracking and allocation of expenses related to this WBS element.',
    `gl_account_id` BIGINT COMMENT 'Reference to the general ledger account for posting financial transactions related to this WBS element.',
    `parent_wbs_element_id` BIGINT COMMENT 'Reference to the parent WBS element in the hierarchical structure. Null for top-level elements.',
    `capex_project_id` BIGINT COMMENT 'Reference to the capital or operational project to which this WBS element belongs.',
    `organization_id` BIGINT COMMENT 'Reference to the organizational unit or department responsible for executing and managing this WBS element.',
    `actual_end_date` DATE COMMENT 'Actual date when work was completed on this WBS element.',
    `actual_start_date` DATE COMMENT 'Actual date when work commenced on this WBS element.',
    `asset_class` STRING COMMENT 'Classification of the asset type for utility plant accounting and depreciation purposes per FERC guidelines.',
    `budget_amount` DECIMAL(18,2) COMMENT 'Approved budget allocation for this WBS element in US dollars.',
    `compliance_requirement` STRING COMMENT 'Regulatory or compliance mandate driving this WBS element (e.g., NERC CIP, EPA emissions, state PUC order).',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this WBS element record was first created in the system.',
    `currency_code` STRING COMMENT 'Three-letter ISO 4217 currency code for financial amounts. Typically USD for US-based utility operations.',
    `depreciation_method` STRING COMMENT 'Method used to calculate depreciation for capitalized assets associated with this WBS element.',
    `effective_end_date` DATE COMMENT 'Date when this WBS element record ceased to be effective. Null for currently effective records.',
    `effective_start_date` DATE COMMENT 'Date when this WBS element record became effective for financial and project tracking purposes.',
    `expenditure_type` STRING COMMENT 'Classification of the WBS element as capital expenditure (CAPEX), operating expenditure (OPEX), or mixed.',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts code for regulatory reporting and classification of capital and operating expenses.',
    `is_active` BOOLEAN COMMENT 'Indicates whether this WBS element is currently active and available for cost posting and project management.',
    `is_billable` BOOLEAN COMMENT 'Indicates whether costs associated with this WBS element are billable to customers or included in rate base calculations.',
    `is_capitalizable` BOOLEAN COMMENT 'Indicates whether costs for this WBS element qualify for capitalization as plant assets under GAAP and FERC accounting rules.',
    `modified_by` STRING COMMENT 'User identifier or system account that last modified this WBS element record.',
    `modified_timestamp` TIMESTAMP COMMENT 'Timestamp when this WBS element record was last modified.',
    `planned_end_date` DATE COMMENT 'Scheduled completion date for work on this WBS element.',
    `planned_start_date` DATE COMMENT 'Scheduled start date for work on this WBS element.',
    `priority_level` STRING COMMENT 'Business priority ranking for resource allocation and scheduling decisions.',
    `regulatory_treatment` STRING COMMENT 'Classification of how costs for this WBS element are treated for regulatory accounting and rate recovery purposes.',
    `risk_category` STRING COMMENT 'Primary risk category associated with this WBS element for risk management and mitigation planning.',
    `wbs_element_status` STRING COMMENT 'Current lifecycle status of the WBS element indicating its execution state.',
    `useful_life_years` STRING COMMENT 'Expected useful life in years for assets capitalized under this WBS element, used for depreciation calculations.',
    `wbs_code` STRING COMMENT 'Hierarchical alphanumeric code representing the WBS element position in the project structure. Used for external identification and reporting to FERC and regulatory bodies.',
    `wbs_description` STRING COMMENT 'Detailed description of the scope, deliverables, and purpose of the WBS element.',
    `wbs_level` STRING COMMENT 'Numeric level in the WBS hierarchy where 1 is the top level (project) and higher numbers represent deeper decomposition.',
    `wbs_name` STRING COMMENT 'Business name or title of the WBS element describing the work package, project phase, or cost center.',
    `wbs_type` STRING COMMENT 'Classification of the WBS element indicating its role in the project structure.',
    `created_by` STRING COMMENT 'User identifier or system account that created this WBS element record.',
    CONSTRAINT pk_wbs_element PRIMARY KEY(`wbs_element_id`)
) COMMENT 'Master reference table for wbs_element. Referenced by wbs_element_id.';

CREATE OR REPLACE TABLE `power_and_utilities`.`finance`.`organization` (
    `organization_id` BIGINT COMMENT 'Primary key for organization',
    `address_line_1` STRING COMMENT 'Primary street address of the organizations physical location. Used for regulatory filings and correspondence.',
    `address_line_2` STRING COMMENT 'Secondary address information such as suite, floor, or building number.',
    `annual_budget_amount` DECIMAL(18,2) COMMENT 'Total approved budget for the current fiscal year in US dollars. Used for budget variance analysis and financial planning.',
    `budget_owner_id` BIGINT COMMENT 'Reference to the employee or executive responsible for budget planning and variance management for this organization.',
    `city` STRING COMMENT 'City where the organization is located.',
    `cost_center_code` STRING COMMENT 'Financial accounting code used to track and allocate operating expenses (OPEX) and capital expenditures (CAPEX) to this organization. Aligns with general ledger chart of accounts.',
    `country_code` STRING COMMENT 'Three-letter ISO 3166-1 alpha-3 country code where the organization is located.',
    `created_timestamp` TIMESTAMP COMMENT 'Date and time when this organization record was first created in the system. Format: yyyy-MM-ddTHH:mm:ss.SSSXXX.',
    `currency_code` STRING COMMENT 'Three-letter ISO 4217 currency code for financial transactions associated with this organization. Typically USD for US-based utilities.',
    `depreciation_method` STRING COMMENT 'Accounting method used to depreciate capital assets owned by this organization. Regulatory method follows FERC-prescribed rates; other methods align with GAAP.',
    `organization_description` STRING COMMENT 'Detailed narrative description of the organizations purpose, responsibilities, and scope within the utility enterprise.',
    `effective_end_date` DATE COMMENT 'Date when this organization was closed or became inactive. Null for currently active organizations. Used for historical cost analysis and organizational change tracking.',
    `effective_start_date` DATE COMMENT 'Date when this organization became active and began accepting financial transactions. Used for time-based cost allocation and historical reporting.',
    `email_address` STRING COMMENT 'Primary email contact for the organization.',
    `functional_area` STRING COMMENT 'Primary operational function of the organization within the utility value chain. Generation produces electricity; transmission moves high-voltage power; distribution delivers to end customers; customer service manages billing and support; corporate provides enterprise services; regulatory handles compliance and rate cases.',
    `is_rate_base_eligible` BOOLEAN COMMENT 'Indicates whether capital investments by this organization are eligible for inclusion in the regulatory rate base for cost recovery. Critical for CAPEX planning and rate case preparation.',
    `is_regulated` BOOLEAN COMMENT 'Indicates whether this organization is subject to regulatory oversight and rate regulation. True for generation, transmission, and distribution organizations; false for unregulated competitive business units.',
    `last_modified_timestamp` TIMESTAMP COMMENT 'Date and time when this organization record was last updated. Format: yyyy-MM-ddTHH:mm:ss.SSSXXX.',
    `legal_entity_id` STRING COMMENT 'Identifier of the legal entity that owns or operates this organization. Used for consolidation in GAAP financial statements and SOX compliance reporting.',
    `manager_id` BIGINT COMMENT 'Reference to the employee who manages this organization unit. Used for accountability and approval workflows.',
    `organization_code` STRING COMMENT 'Unique business identifier code for the organization used in financial reporting and cost allocation. Typically assigned by the enterprise resource planning system.',
    `organization_level` STRING COMMENT 'Numeric level in the organizational hierarchy where 1 represents the top level (enterprise) and higher numbers represent deeper nested levels. Used for roll-up reporting and consolidation.',
    `organization_name` STRING COMMENT 'Full legal or business name of the organization unit. Used for financial reporting, regulatory filings, and internal cost center identification.',
    `organization_short_name` STRING COMMENT 'Abbreviated name or acronym for the organization used in reports and user interfaces.',
    `organization_type` STRING COMMENT 'Classification of the organization entity indicating its role in the financial structure. Cost centers track expenses only; profit centers track both revenue and expenses; business units are strategic operational divisions; departments are functional groups; divisions are major organizational segments; subsidiaries are legally separate entities.',
    `parent_organization_id` BIGINT COMMENT 'Reference to the parent organization in the hierarchy. Null for top-level organizations. Enables hierarchical cost allocation and financial consolidation.',
    `phone_number` STRING COMMENT 'Primary contact phone number for the organization.',
    `postal_code` STRING COMMENT 'ZIP or postal code for the organizations address. Format: XXXXX or XXXXX-XXXX.',
    `profit_center_code` STRING COMMENT 'Financial accounting code used to track revenue and profitability for this organization. Used in return on equity (ROE) and return on investment (ROI) calculations. Null for cost-only centers.',
    `regulatory_jurisdiction` STRING COMMENT 'Regulatory body or commission with oversight authority over this organization (e.g., state public utility commission, FERC). Critical for rate case filings and compliance reporting.',
    `service_territory` STRING COMMENT 'Geographic region or jurisdiction served by this organization. Used for regulatory reporting and rate case cost allocation by service area.',
    `sox_scope_flag` BOOLEAN COMMENT 'Indicates whether this organization is within the scope of SOX internal controls testing and audit requirements. True for organizations with material financial impact.',
    `state_province` STRING COMMENT 'Two-letter state or province code where the organization is located. Critical for regulatory jurisdiction determination.',
    `organization_status` STRING COMMENT 'Current lifecycle status of the organization. Active organizations are operational and can have transactions posted; inactive organizations are temporarily suspended; pending organizations are being established; closed organizations are permanently retired.',
    `tax_identification_number` STRING COMMENT 'Federal employer identification number (EIN) or tax ID assigned to this organization for tax reporting purposes. Format: XX-XXXXXXX.',
    CONSTRAINT pk_organization PRIMARY KEY(`organization_id`)
) COMMENT 'Master reference table for organization. Referenced by responsible_organization_id.';

